import type { Lang } from "@/lib/i18n";

/**
 * Data-driven drip content for the 33-language path (Gadi 2026-08-23).
 *
 * The original en/he drip stays in mail-*-{en,he}.ts (untouched). Every OTHER
 * language lives here as data and is rendered by build-i18n-drip.ts through the
 * shared i18n-layout. A language is only "live" once it appears in DRIP_CONTENT;
 * until then getDripForLang() falls back to the English drip.
 *
 * Emails 2 (meanings) and 3 (etymology) are authored per language around a rich,
 * polysemous word native to that language (like he uses רוח, en uses "spirit"),
 * NOT translated. `exampleWord` is that word, used to link the meanings CTA.
 * Etymology must be accurate (reviewed).
 */

export type DripEmail = {
  subject: string;
  preheader: string;
  /** Body paragraphs, WITHOUT the greeting (the builder prepends it). Plain
   *  text with entities allowed; each becomes its own <p>. */
  paras: string[];
  /** CTA button label. */
  cta: string;
  /** meanings/etymology only: the language's chosen example word (links the CTA). */
  exampleWord?: string;
  /** Optional small gray P.S. line (meanings has one). */
  ps?: string;
  /** Optional signature lines (welcome). Last line renders small/gray (the title). */
  signOff?: string[];
};

export type LangDrip = {
  /** Greeting with a {name} placeholder, e.g. "Hi {name}," */
  greetNamed: string;
  /** Greeting with no name, e.g. "Hi," */
  greetPlain: string;
  /** Localized: "You're receiving this because you signed up for Gadit." */
  footerReason: string;
  /** Localized "Unsubscribe". */
  unsubscribeLabel: string;
  welcome: DripEmail;
  meanings: DripEmail;
  etymology: DripEmail;
  visual: DripEmail;
  summary: DripEmail;
};

/** Per-language drip content. Filled in reviewed waves. en/he are NOT here (they
 *  keep using their original files). */
export const DRIP_CONTENT: Partial<Record<Lang, LangDrip>> = {
  es: {"greetNamed":"Hola {name},","greetPlain":"Hola,","footerReason":"Recibes este correo porque te registraste en Gadit.","unsubscribeLabel":"Cancelar suscripción","welcome":{"subject":"Te damos la bienvenida a Gadit","preheader":"Un diccionario, una misión. Descifrar una palabra hasta el fondo. Así empiezas.","paras":["Gracias por unirte a Gadit. Nos alegra mucho tenerte aquí.","Gadit es un diccionario con una sola misión: descifrar una palabra hasta el fondo. Nada de una definición de una línea, nada de una traducción seca. Todos los significados, las expresiones, el origen de la palabra y la forma en que la gente la usa de verdad hoy en día.","Tu cuenta gratuita incluye 10 búsquedas al día y un cuaderno de hasta 30 palabras.","Cuando entiendes una palabra por completo, la idea que hay detrás se vuelve clara, y con ella cómo piensas, cómo aprendes y cómo decides.","Gadit es una plataforma viva que no deja de crecer. Si encuentras un error en alguna definición o en algún ejemplo, hay un botón para reportarlo que vale la pena pulsar. Nuestro equipo lo lee todo y lo corrige.","¿Empezamos?"],"cta":"Busca tu primera palabra","signOff":["Un abrazo,","El equipo de Gadit"]},"meanings":{"subject":"Una palabra, capas que no habías visto","preheader":"La mayoría de las herramientas se quedan en la definición. Gadit sigue hasta que se te queda.","exampleWord":"banco","paras":["Toma la palabra banco, y mira cómo una sola palabra puede abrir un mundo entero.","Un banco es el asiento largo donde te sientas en un parque. También es la institución donde guardas tu dinero, y el edificio en el que entras a hacer un trámite. Es un banco de peces, ese grupo enorme que se mueve junto bajo el agua. Es un banco de arena que aparece en el mar cuando baja la marea. Y es también un banco de datos o un banco de sangre, un lugar donde se reúne y se guarda algo valioso para cuando haga falta.","Una palabra, capas que no habías visto, cada una viviendo en su propio mundo.","En Gadit recibes tres ejemplos reales para cada definición, frases donde la palabra funciona de verdad, para que veas cómo cambia según el mundo en el que aparece.","Este es el corazón de Gadit: una palabra, hasta el fondo, a lo largo de todos sus significados.","Te invitamos a buscar banco, y quizá después otra palabra que creas que ya entiendes del todo. A lo mejor te sorprende."],"cta":"Busca la palabra banco","ps":"P.D. Cuando llegues a un significado que no esperabas, fíjate en el botón de compartir que hay al lado. Es perfecto para ese momento de \"no tenía ni idea\"."},"etymology":{"subject":"De dónde viene de verdad una palabra","preheader":"Cada palabra tiene un pasado, y a veces explica el presente mejor que cualquier definición.","exampleWord":"banco","paras":["Llegamos a nuestra parte favorita: de dónde viene la palabra.","Cada palabra tiene un pasado, y a veces ese pasado explica el presente mejor que cualquier definición.","Banco viene del germánico bank, que significaba precisamente eso: un banco, un asiento largo de madera. De ahí salen palabras que comparten la misma raíz, como banca, banquillo, banqueta e incluso banquete.","El salto curioso está en el dinero. En las ferias medievales de Italia, los cambistas hacían sus operaciones sentados en un banco, una mesa larga sobre la que contaban las monedas. Ese banco de trabajo terminó dando nombre al negocio entero, y así el asiento se convirtió en la institución financiera que hoy conocemos.","Todo un viaje en una sola palabra, que fue de un mueble concreto a una idea abstracta y se quedó con nosotros.","Saber esto te ayuda a recordar la palabra y a ver por qué sus significados, tan distintos a primera vista, en realidad están conectados.","En Gadit, debajo de las definiciones de cada palabra hay una sección que explica su origen, y eso convierte un diccionario en una historia."],"cta":"Descubre el origen de la siguiente palabra"},"visual":{"subject":"Una palabra a la altura de los ojos","preheader":"Modo Niños: cada palabra explicada en el idioma de un niño, sin perder la profundidad.","paras":["Pasa muy seguido: un niño pregunta qué significa una palabra, y la definición oficial es demasiado complicada para responderle.","Por eso Gadit tiene el Modo Niños: lo activas y cada palabra queda explicada en el idioma de un niño de cinco a diez años, con la misma profundidad pero sin las palabras difíciles.","Por ejemplo, en lugar de definir gravedad como \"la fuerza de atracción que ejerce la masa de un cuerpo\", el Modo Niños dice algo como: es lo que hace que las cosas caigan al suelo cuando las sueltas, y lo que nos mantiene con los pies en la tierra.","Y no es solo para niños. A veces la explicación sencilla es justo lo que también necesitamos los adultos.","Junto al Modo Niños, Gadit muestra una imagen para cada significado, para que la palabra se entienda más rápido y se te quede por más tiempo.","El Modo Niños forma parte del plan Family, pensado para familias con niños. La imagen para cada significado también viene con el plan Individual.","Si tienes un niño cerca, siéntate con él, activa el Modo Niños, busca una palabra y mira su imagen. Es un rato precioso para compartir."],"cta":"Conoce el Modo Niños"},"summary":{"subject":"Dos semanas, una palabra","preheader":"El recorrido, y dos formas de seguir a partir de aquí.","paras":["En estas dos semanas hemos conocido las caras de una palabra: todos sus significados y su historia.","Y también las funciones que hacen de Gadit una herramienta para entender más a fondo: el Modo Niños y una imagen para cada significado.","Algunas funciones están abiertas para todos: la cuenta gratuita incluye 10 búsquedas al día y un cuaderno de hasta 30 palabras.","Las demás se desbloquean con Individual: búsquedas ilimitadas, una imagen para cada significado, un cuaderno que guarda cada palabra con práctica inteligente, juegos y cuestionarios, Cada palabra (haz una foto de una página y toca cualquier palabra), Dilo para practicar la pronunciación, y componer una oración y recibir comentarios. Si Gadit ya se volvió parte de tu día, esto marca la diferencia.","¿Tienes hijos en casa? El plan <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> incluye hasta 5 niños, con el Modo Niños y un panel para padres.","Además, tenemos un programa de socios: un enlace personal que te da una comisión por cada registro de pago que llegue a través de él. Una forma bonita de compartir algo que te gusta y ganar algo por el camino.","Gracias por estas dos semanas. Esto apenas empieza."],"cta":"Conoce Individual","ps":"P.D. Siempre nos encanta saber qué funciones te gustaría ver en Gadit. Solo tienes que responder a este correo."}},
  pt: {"greetNamed":"Olá {name},","greetPlain":"Olá,","footerReason":"Você está recebendo este email porque se cadastrou no Gadit.","unsubscribeLabel":"Cancelar inscrição","welcome":{"subject":"Boas-vindas ao Gadit","preheader":"Um dicionário, uma missão. Entender uma palavra por completo. Veja como começar.","paras":["Parabéns por entrar no Gadit. Que bom ter você aqui.","O Gadit é um dicionário com uma missão só: entender uma palavra por completo. Nada de uma definição de uma linha, nada de tradução seca. Todos os sentidos, as expressões, a origem da palavra e a forma como as pessoas realmente a usam hoje.","Sua conta gratuita inclui 10 buscas por dia e um caderno de até 30 palavras.","Quando você capta uma palavra por inteiro, a ideia por trás dela fica clara, e com ela a forma como você pensa, aprende e decide.","O Gadit é uma plataforma viva, que não para de crescer. Se você encontrar um erro em qualquer definição ou exemplo, existe um botão de reportar que vale a pena apertar. Nossa equipe lê tudo e corrige.","Pronto para começar?"],"cta":"Buscar sua primeira palavra","signOff":["Um abraço,","Equipe Gadit"]},"meanings":{"subject":"Uma palavra, camadas que você ainda não tinha visto","preheader":"A maioria das ferramentas para na definição. O Gadit segue até a ideia grudar.","exampleWord":"banco","paras":["Pegue a palavra banco e veja como uma palavra só pode abrir um mundo inteiro.","Um banco é onde você guarda seu dinheiro. É também o assento comprido de uma praça onde você senta para descansar. É o banco de dados que guarda informações, o banco de areia que aparece no mar raso, o banco de sangue do hospital e até a reserva de jogadores esperando para entrar em campo.","Uma palavra só, camadas que você não tinha percebido, cada uma no seu próprio mundo.","No Gadit você recebe três exemplos reais para cada definição, frases em que a palavra funciona na prática e não só na teoria.","É esse o coração do Gadit: uma palavra, até o fim, em todas as suas definições.","Que tal buscar banco agora, e depois tentar outra palavra que você acha que já conhece por completo?"],"cta":"Buscar a palavra banco","ps":"P.S. Ao lado de um sentido que te surpreender, tem um botão de compartilhar. Manda para alguém que vai achar tão curioso quanto você."},"etymology":{"subject":"De onde uma palavra realmente vem","preheader":"Toda palavra tem um passado, e às vezes ele explica o presente.","exampleWord":"banco","paras":["Chegamos à nossa parte favorita: de onde a palavra vem.","Toda palavra tem um passado, e às vezes esse passado explica o presente melhor do que qualquer definição.","Banco vem do germânico bank, que significava justamente um assento comprido, uma tábua onde as pessoas se sentavam. Da mesma raiz vêm banca, bancada e até bancarrota.","O salto para a palavra que usamos no dia a dia é lindo. Na Itália do fim da Idade Média, os cambistas faziam negócios sentados atrás de um banco, uma bancada na praça. Com o tempo, o nome do móvel passou a nomear a própria atividade, e o assento virou a instituição financeira. E quando um cambista quebrava e não podia pagar, seu banco era literalmente partido: banca rota, a bancarrota.","É uma viagem inteira dentro de uma palavra que ficou com a gente.","Saber disso ajuda você a lembrar da palavra e a enxergar por que os seus vários sentidos se conectam, do assento da praça ao cofre do dinheiro.","No Gadit, embaixo de cada palavra tem uma seção de origem que transforma um dicionário em uma história."],"cta":"Descobrir a origem da próxima palavra"},"visual":{"subject":"Uma palavra na altura dos olhos","preheader":"Modo Kids: cada palavra explicada na língua de uma criança, sem perder a profundidade.","paras":["Um pedido que chega o tempo todo: a criança pergunta o que uma palavra significa, e a definição oficial é complicada demais para ela entender.","Por isso o Gadit tem o Modo Kids: cada palavra explicada na linguagem de uma criança de 5 a 10 anos, com a mesma profundidade, mas sem palavras difíceis.","Pegue a palavra gravidade. No modo normal, ela vira física e fórmulas. No Modo Kids, é a força invisível que puxa tudo para o chão, por isso a bola sempre volta para baixo quando você a joga para o alto.","E não é só para crianças. Às vezes a explicação simples é exatamente o que nós, adultos, precisamos para a ficha cair.","O Gadit também mostra uma imagem para cada significado, para o entendimento chegar mais rápido e ficar mais tempo.","O Modo Kids faz parte do plano Family, feito para famílias com crianças. A imagem para cada significado também vem com o plano Individual.","Se tiver uma criança por perto, liguem o Modo Kids juntos, busquem uma palavra e vejam a imagem dela. É uma delícia de ver."],"cta":"Conhecer o Modo Kids"},"summary":{"subject":"Duas semanas, uma palavra","preheader":"A jornada até aqui, e dois caminhos para continuar.","paras":["Nessas duas semanas a gente conheceu os lados de uma palavra: todos os seus sentidos e a sua história.","E também os recursos que fazem do Gadit uma ferramenta de entendimento mais profundo: o Modo Kids e uma imagem para cada significado.","Alguns recursos são abertos para todo mundo: a conta gratuita inclui 10 buscas por dia e um caderno de até 30 palavras.","Os outros se liberam com o Individual: buscas ilimitadas, uma imagem para cada significado, um caderno que guarda cada palavra com prática inteligente, jogos e quizzes, Cada palavra (fotografe uma página e toque em qualquer palavra), Diga para praticar a pronúncia, e compor uma frase e receber feedback. Se o Gadit já faz parte do seu dia, é aí que a diferença aparece.","Tem filhos em casa? O plano <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> inclui até 5 crianças, com o Modo Kids e um painel dos pais.","E temos um programa de parceiros: um link pessoal que rende uma comissão a cada novo cadastro pago feito por ele.","Obrigado por caminhar com a gente até aqui. Isso é só o começo."],"cta":"Conhecer o Individual","ps":"P.S. A gente sempre adora saber quais recursos você gostaria de ver no Gadit. É só responder a este email."}},
  fr: {"greetNamed":"Bonjour {name},","greetPlain":"Bonjour,","footerReason":"Vous recevez ce message parce que vous vous êtes inscrit à Gadit.","unsubscribeLabel":"Se désinscrire","welcome":{"subject":"Bienvenue sur Gadit","preheader":"Un dictionnaire, une mission : comprendre un mot jusqu'au bout. Voici par où commencer.","paras":["Félicitations, vous venez de rejoindre Gadit.","Gadit est un dictionnaire avec une seule mission : comprendre un mot jusqu'au bout. Pas une définition en une ligne, pas une traduction sèche. Tous les sens, les expressions, l'origine du mot et la façon dont on l'emploie vraiment aujourd'hui.","Votre compte gratuit comprend 10 recherches par jour et un carnet pouvant contenir jusqu'à 30 mots.","Quand vous saisissez un mot dans sa totalité, l'idée qu'il porte devient claire, et avec elle votre manière de penser, d'apprendre et de décider.","Gadit est une plateforme vivante qui ne cesse de grandir. Si vous repérez une erreur dans une définition ou un exemple, il y a un bouton de signalement qui vaut le coup d'être utilisé. Notre équipe lit tout et corrige.","Prêt à commencer ?"],"cta":"Chercher votre premier mot","signOff":["Bien à vous,","L'équipe Gadit"]},"meanings":{"subject":"Un mot, des couches que vous n'aviez pas vues","preheader":"La plupart des outils s'arrêtent à la définition. Gadit continue jusqu'à ce que ça reste.","exampleWord":"voler","paras":["Prenez le mot voler, et voyez comment un seul mot ouvre tout un monde.","Voler, c'est se déplacer dans les airs, comme un oiseau ou un avion. Mais voler, c'est aussi prendre le bien d'autrui, dérober. Et en fauconnerie, l'oiseau de proie vole le gibier, il fond sur lui pour le saisir.","Un seul mot, des couches que vous n'aviez pas vues, chacune dans son propre monde.","Dans Gadit, chaque sens vient avec trois exemples réels, tirés de la vraie langue, pour que vous voyiez le mot en action et pas seulement sa définition.","C'est le cœur de Gadit : un mot, du début à la fin.","Essayez de le chercher, puis cherchez un autre mot que vous croyez déjà connaître. Vous pourriez être surpris."],"cta":"Chercher ce mot","ps":"P.S. Un sens vous a plu ? Il y a un bouton de partage à côté de chaque mot : envoyez-le à quelqu'un qui appréciera."},"etymology":{"subject":"D'où vient vraiment un mot","preheader":"Chaque mot a un passé, et parfois il explique le présent.","exampleWord":"voler","paras":["Voici notre partie préférée : d'où vient le mot.","Chaque mot a un passé qui éclaire son présent, et voler ne fait pas exception.","Il vient du latin volare, qui voulait dire simplement se déplacer dans les airs. À l'origine, le mot ne parlait que de vol, celui de l'oiseau. On retrouve la même racine dans vol, s'envoler, volée ou volatile.","Le sens de dérober est venu bien plus tard, par la chasse au faucon. On disait que le rapace volait sa proie, qu'il fondait sur elle pour la saisir en plein vol. Peu à peu, ce geste de saisir en fondant est devenu voler au sens de prendre ce qui n'est pas à soi. Du concret, le mouvement dans l'air, vers l'abstrait, le vol d'un bien.","Tout un voyage tient dans un seul mot.","Connaître cette histoire aide à retenir le mot, et montre pourquoi ses sens, si éloignés en apparence, sont en réalité reliés.","Dans Gadit, une section origine accompagne chaque mot, et transforme un dictionnaire en récit."],"cta":"Découvrir l'origine du prochain mot"},"visual":{"subject":"Un mot à hauteur d'yeux","preheader":"Mode Enfants : chaque mot expliqué dans la langue d'un enfant, sans rien perdre de la profondeur.","paras":["Voici une demande qui revient souvent : un enfant demande le sens d'un mot, mais la définition officielle est bien trop compliquée pour lui.","Le Mode Enfants explique chaque mot dans la langue d'un enfant de cinq à dix ans. La même profondeur, sans les grands mots.","Prenez un mot un peu abstrait : en Mode Enfants, il devient simple, imagé, à hauteur d'yeux, sans jamais trahir son vrai sens.","Et ce n'est pas réservé aux enfants. Les adultes y gagnent aussi : rien ne clarifie mieux une idée qu'une explication vraiment simple.","Gadit montre aussi une image pour chaque sens. Voir le mot, et pas seulement le lire, aide à ce qu'il reste vraiment.","Le Mode Enfants fait partie du plan Family, conçu pour les familles avec enfants. L'image pour chaque sens est aussi incluse dans le plan Individual.","Si un enfant est près de vous, faites-le ensemble. C'est un beau moment à partager."],"cta":"Découvrir le Mode Enfants"},"summary":{"subject":"Deux semaines, un mot","preheader":"Le chemin parcouru, et deux façons de continuer à partir d'ici.","paras":["Voilà deux semaines que nous apprenons à connaître un mot par toutes ses faces : ses sens, son histoire, sa vraie origine.","En chemin, vous avez découvert les fonctions qui approfondissent la compréhension : le Mode Enfants, qui met chaque mot à hauteur d'yeux, et une image pour chaque sens, qui rend le mot visible.","Certaines de ces fonctions sont ouvertes à tous : le compte gratuit comprend 10 recherches par jour et un carnet pouvant contenir jusqu'à 30 mots.","Les autres se débloquent avec Individual : recherches illimitées, une image pour chaque sens, un carnet qui garde chaque mot avec une révision intelligente, des jeux et des quiz, Every Word (photographiez une page et touchez n'importe quel mot), Dis-le pour s'entraîner à la prononciation, et la composition d'une phrase avec un retour.","Vous avez des enfants ? Le plan <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> accueille jusqu'à 5 enfants, avec le Mode Enfants et un tableau des parents.","Nous avons aussi un programme de partenaires : un lien personnel qui rapporte une commission sur chaque inscription payante qu'il amène.","Prêt pour la suite ?"],"cta":"Découvrir Individual","ps":"P.S. Nous aimons toujours savoir quelles fonctionnalités vous aimeriez voir dans Gadit. Il vous suffit de répondre à ce message."}},
  de: {"greetNamed":"Hallo {name},","greetPlain":"Hallo,","footerReason":"Du erhältst diese E-Mail, weil du dich bei Gadit angemeldet hast.","unsubscribeLabel":"Abmelden","welcome":{"subject":"Willkommen bei Gadit","preheader":"Ein Wörterbuch, eine Mission. Ein Wort ganz zu durchdringen. So fängst du an.","paras":["Herzlichen Glückwunsch, du bist jetzt bei Gadit dabei. Schön, dass du da bist.","Gadit ist ein Wörterbuch mit einer einzigen Mission: ein Wort ganz zu durchdringen. Keine Erklärung in einer Zeile, keine trockene Übersetzung. Alle Bedeutungen, Redewendungen, die Herkunft des Wortes und die Art, wie Menschen es heute wirklich benutzen.","Dein kostenloses Konto umfasst 10 Suchen pro Tag und ein Wörter-Notizbuch für bis zu 30 Wörter.","Wenn du ein Wort vollständig erfasst, wird auch die Idee dahinter klar. Und mit ihr, wie du denkst, lernst und entscheidest.","Gadit ist eine lebendige Plattform, die ständig wächst. Wenn dir in einer Definition oder einem Beispiel ein Fehler auffällt, gibt es einen Melden-Button, der es wert ist, gedrückt zu werden. Unser Team liest alles und bessert es aus.","Bereit anzufangen? Such dein erstes Wort und schau, was passiert."],"cta":"Such dein erstes Wort","signOff":["Herzlich,","Dein Gadit-Team"]},"meanings":{"subject":"Ein Wort, Schichten, die du noch nicht gesehen hast","preheader":"Die meisten Tools hören bei der Definition auf. Gadit macht weiter, bis es sitzt.","exampleWord":"Zug","paras":["Nimm das Wort Zug und sieh, wie ein einziges Wort eine ganze Welt öffnet.","Ein Zug ist die Bahn, die in den Bahnhof rollt. Ein Zug ist der geschickte Schachzug, der eine Partie entscheidet. Ein Zug ist der kalte Luftstrom, der durch die Tür zieht. Ein Zug ist der kräftige Schluck aus dem Glas. Ein Zug ist ein Charakterzug, ein Wesensmerkmal eines Menschen. Und ein Zug ist auch der Vogelzug, der ganze Schwärme über Kontinente führt.","Ein Wort, Schichten, die du vorher nicht gesehen hast, und jede lebt in ihrer eigenen Welt.","In Gadit bekommst du zu jeder dieser Bedeutungen drei echte Beispiele, damit du nicht nur weißt, was das Wort bedeutet, sondern auch, wie es klingt, wenn Menschen es benutzen.","Das ist das Herz von Gadit: ein Wort, ganz bis zum Ende. Such Zug einmal nach und dann noch ein Wort, von dem du glaubst, du kennst es längst. Wahrscheinlich wartet auch dort eine Schicht auf dich."],"cta":"Such dieses Wort","ps":"P.S. Wenn eine Bedeutung dich überrascht, gibt es einen Teilen-Button. Gib das Wort an jemanden weiter, der es auch zu kennen glaubt."},"etymology":{"subject":"Woher ein Wort wirklich kommt","preheader":"Jedes Wort hat eine Vergangenheit, und manchmal erklärt sie die Gegenwart.","exampleWord":"Zug","paras":["Jetzt kommt unser Lieblingsteil: woher ein Wort kommt.","Jedes Wort hat eine Vergangenheit, die seine Gegenwart erklärt. Beim Wort Zug ist diese Vergangenheit besonders schön zu sehen.","Zug gehört zum Verb ziehen. Der eigentliche Ursprung ist ganz konkret: das Ziehen, das Gezogenwerden. Aus derselben Wurzel stammen verwandte Wörter wie Zügel, erziehen und Herzog. Alle tragen denselben Kern in sich: etwas oder jemanden in eine Richtung ziehen.","Von dieser handfesten Grundbedeutung aus ist das Wort ins Abstrakte gewachsen. Vom gezogenen Wagen zum Eisenbahnzug. Vom Ziehen der Hand zum Schachzug. Vom Zug der Linie im Gesicht zum Charakterzug eines Menschen. Eine ganze Reise steckt in einem einzigen Wort.","Wenn du das weißt, bleibt das Wort besser im Gedächtnis, und du siehst plötzlich, warum all diese Bedeutungen zusammengehören. Sie ziehen alle an demselben Faden.","In Gadit findest du zu jedem Wort einen Herkunftsabschnitt. Er macht aus einem Wörterbuch eine Geschichte, die du gern zu Ende liest."],"cta":"Entdeck die Herkunft des nächsten Wortes"},"visual":{"subject":"Ein Wort auf Augenhöhe","preheader":"Kids Mode: jedes Wort in Kindersprache erklärt, ohne die Tiefe zu verlieren.","paras":["Eine Bitte hören wir immer wieder: Ein Kind fragt nach einem Wort, und die richtige Definition ist einfach zu kompliziert, um sie laut vorzulesen.","Dafür gibt es den Kids Mode. Er erklärt jedes Wort in der Sprache eines fünf- bis zehnjährigen Kindes. Dieselbe Tiefe, nur ohne die großen, sperrigen Wörter.","Nimm ein Wort wie ziehen. Im Kids Mode klingt es plötzlich einfach: etwas zu dir heranholen, so wie du an einer Schnur ziehst, damit der Schlitten zu dir kommt. Kein Kind steigt da aus.","Und der Kids Mode ist nicht nur für Kinder da. Auch Erwachsene profitieren davon, wenn ein schwieriges Wort einmal ganz ruhig und ganz klar dasteht.","Gadit zeigt außerdem ein Bild für jede Bedeutung, das das Wort sichtbar macht. Wenn du etwas nicht nur liest, sondern auch siehst, bleibt das Verständnis länger.","Der Kids Mode gehört zum Family-Tarif, der für Familien mit Kindern gemacht ist. Ein Bild für jede Bedeutung gibt es auch im Individual-Tarif.","Wenn gerade ein Kind neben dir ist: Probiert es zusammen aus. Ein Wort zu zweit zu knacken macht doppelt Freude."],"cta":"Kids Mode entdecken"},"summary":{"subject":"Zwei Wochen, ein Wort","preheader":"Die Reise, und zwei Wege, von hier aus weiterzugehen.","paras":["Zwei Wochen lang haben wir uns angesehen, wie viele Seiten ein einziges Wort haben kann: seine Bedeutungen, seine Beispiele, seine Geschichte. Wir hoffen, du siehst Wörter seither ein bisschen anders.","Unterwegs sind dir Funktionen begegnet, die das Verständnis vertiefen: der Kids Mode, der jedes Wort auf Augenhöhe bringt, und ein Bild für jede Bedeutung, das ein Wort sichtbar macht.","Manches davon steht allen offen: Das kostenlose Konto umfasst 10 Suchen pro Tag und ein Wörter-Notizbuch für bis zu 30 Wörter.","Anderes schaltest du mit Individual frei: unbegrenzte Suchen, ein Bild für jede Bedeutung, ein Wörter-Notizbuch, das jedes Wort speichert, mit smartem Üben, Spiele und Quiz, Jedes Wort (fotografiere eine Seite und tippe auf ein beliebiges Wort), Sag es zum Üben der Aussprache und eigene Sätze schreiben mit Feedback. So wird ein Wort nicht nur erklärt, sondern auch wirklich behalten.","Kinder im Haus? Der <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a>-Tarif umfasst bis zu 5 Kinder, mit Kids Mode und einer Elternübersicht.","Und noch etwas: Es gibt ein Partnerprogramm mit einem persönlichen Link. Für jede bezahlte Anmeldung darüber verdienst du eine Provision. Wenn Gadit dir hilft, kann es dir also auch etwas zurückgeben.","Wenn du bereit bist, weiterzugehen, schau dir an, was Individual für dich bereithält."],"cta":"Lern Individual kennen","ps":"P.S. Wir freuen uns immer zu hören, welche Funktionen du dir in Gadit wünschst. Antworte einfach auf diese E-Mail."}},
  af: {"greetNamed":"Hallo {name},","greetPlain":"Hallo,","footerReason":"Jy ontvang hierdie e-pos omdat jy by Gadit aangesluit het.","unsubscribeLabel":"Teken uit","welcome":{"subject":"Welkom by Gadit","preheader":"Een woordeboek, een missie. Om 'n woord heeltemal te verstaan. So begin jy.","paras":["Welkom by Gadit, en baie dankie dat jy aangesluit het.","Gadit is 'n woordeboek met een missie: om 'n woord heeltemal te verstaan. Nie 'n definisie van een reël nie, nie 'n droë vertaling nie. Al die betekenisse, die idiome, die oorsprong van die woord en hoe mense dit vandag regtig gebruik.","Jou gratis rekening sluit 10 opsoeke per dag in en 'n notaboek vir tot 30 woorde.","Wanneer jy 'n woord heeltemal begryp, word die idee daaragter helder, en daarmee saam die manier waarop jy dink, leer en besluit.","Gadit is 'n lewende platform wat aanhou groei. As jy 'n fout in enige definisie, voorbeeld of ander deel raaksien, is daar 'n rapporteerknoppie wat die moeite werd is om te druk. Ons span lees alles en maak dit reg.","Gereed om te begin?"],"cta":"Soek jou eerste woord op","signOff":["Groete,","Die Gadit-span"]},"meanings":{"subject":"Een woord, lae wat jy nog nie gesien het nie","preheader":"Die meeste hulpmiddels stop by die definisie. Gadit gaan aan totdat dit vassit.","exampleWord":"spoor","paras":["Neem die woord spoor, en kyk hoe een woord 'n hele wêreld kan oopmaak.","'n Spoor is die afdruk wat 'n dier in die sand of modder laat, soos die spoor van 'n leeu langs die rivier. Dit is die spoorweg, die twee staalrelings waarop 'n trein loop. Dit is 'n teken of oorblyfsel, soos wanneer iemand spoorloos verdwyn. Dit is die rigting waarin jy beweeg, wanneer jy op die regte spoor is. En vir 'n spoorsnyer word dit 'n hele storie: wie hier verbygekom het, wanneer en waarheen.","Een woord, lae wat jy nie daarin raakgesien het nie, elkeen in sy eie wêreld.","In Gadit kry jy drie regte voorbeelde vir elke definisie. Sinne waarin die woord in die praktyk werk, nie in teorie nie. So sien jy nie net wat die woord sê nie, maar ook hoe dit klink wanneer dit gebruik word.","Dit is die hart van Gadit. Een woord, heeltemal deur, oor al sy definisies heen.","Ons stel voor jy soek spoor op, en dalk nog 'n woord wat jy dink jy reeds verstaan. Jy kan dalk verras word."],"cta":"Soek spoor op en sien al die kante","ps":"NS. Wanneer jy 'n verrassende betekenis vind, is daar 'n deelknoppie langsaan. Die moeite werd om aan iemand te stuur wat dit sal waardeer."},"etymology":{"subject":"Waar 'n woord regtig vandaan kom","preheader":"Elke woord het 'n verlede, en soms verduidelik dit die hede.","exampleWord":"spoor","paras":["Ons het by ons gunstelingdeel gekom. Waar die woord vandaan kom.","Elke woord het 'n verlede. En soms verduidelik daardie verlede die hede beter as enige definisie.","Spoor is 'n pragtige voorbeeld. Dit kom van die Nederlandse spoor, wat in die Middelnederlands al die afdruk van 'n voet of 'n dier se spoor beteken het. Dit is 'n ou Germaanse woord, familie van die Duitse Spur, wat ook spoor beteken.","Uit die afdruk op die grond het die idee gegroei van 'n baan wat iets agterlaat: die spore van wawiele, en later die vaste spore waarop 'n trein ry. Daarom praat ons van 'n spoorweg. En nog verder het die woord abstrak geword: 'n spoor van hoop, die regte spoor in die lewe.","Daar is nog 'n draai in die verhaal. Engels het die woord spoor in die 19de eeu in Suid-Afrika uit Afrikaans en Nederlands geleen, vir die spoor van wild.","'n Hele reis in een woord. Van 'n afdruk in die stof tot die gedagte dat 'n lewe 'n rigting volg. Alles in een woord wat al eeue lank by ons is.","Wanneer jy dit weet, onthou jy nie net die woord beter nie. Jy verstaan ook waarom al sy betekenisse aan mekaar verbind is. Hulle woon nie toevallig saam nie.","In Gadit is daar onder die definisies van elke woord 'n afdeling wat sy oorsprong verduidelik. Die historiese agtergrond, waar dit vandaan kom. Dit is wat 'n woordeboek van 'n lys definisies in 'n verhaal verander."],"cta":"Ontdek die oorsprong van die volgende woord"},"visual":{"subject":"'n Woord op ooghoogte","preheader":"Kindermodus: elke woord verduidelik in 'n kind se taal, sonder om die diepte te verloor.","paras":["Een van die versoeke wat ons die meeste gekry het, was eenvoudig. 'n Kind vra wat 'n woord beteken, en die amptelike definisie is te ingewikkeld vir die kind.","Daarom het Gadit Kindermodus. Skakel dit aan, en elke woord word verduidelik in die taal van 'n kind van vyf tot tien jaar. Dieselfde diepte, sonder die groot woorde.","Neem spoor. In die gewone modus word dit in verskeie lae verduidelik. In Kindermodus word dit iets wat 'n kind dadelik snap, soos die pootjies wat 'n hond in die nat sand los, sodat jy kan sien waarheen hy gehardloop het.","En dit is nie net vir kinders nie. Soms, wanneer 'n woord regtig moeilik is, is die eenvoudige verduideliking presies wat grootmense ook nodig het om dit te begryp.","Saam met Kindermodus wys Gadit ook 'n prent vir elke betekenis, sodat 'n kind die woord kan sien en nie net lees nie. Begrip kom vinniger en bly langer.","Kindermodus is deel van die Family-plan, gemaak vir gesinne met kinders. 'n Prent vir elke betekenis kom ook saam met die Individual-plan.","As daar 'n kind naby is, sit 'n oomblik saam, skakel Kindermodus aan, soek saam 'n woord op en kyk na sy prent. Só lyk die oomblik van moeitelose begrip."],"cta":"Ontdek Kindermodus"},"summary":{"subject":"Twee weke, een woord","preheader":"Die reis, en twee maniere om van hier af verder te gaan.","paras":["Oor die afgelope twee weke het ons die verskillende kante van 'n woord leer ken. Al sy betekenisse, en sy geskiedenis.","Daarnaas het ons die funksies leer ken wat Gadit 'n hulpmiddel vir dieper begrip maak: Kindermodus, en 'n prent vir elke betekenis.","Sommige van hierdie funksies is oop vir elke gebruiker. 'n Gratis rekening sluit 10 opsoeke per dag in en 'n notaboek vir tot 30 woorde.","Die res ontsluit met Individual: onbeperkte opsoeke, 'n prent vir elke betekenis, 'n notaboek wat elke woord stoor met slim oefening, speletjies en vasvrae, Elke woord (neem 'n foto van 'n bladsy en tik op enige woord), Sê dit om uitspraak te oefen, en om 'n sin saam te stel en terugvoer te kry. As Gadit deel van jou daaglikse roetine geword het, is dit die funksies wat die verskil maak.","Kinders by die huis? Die <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a>-plan dek tot 5 kinders, met Kindermodus en 'n ouer-paneelbord.","En ons het ook 'n vennootprogram: 'n persoonlike skakel wat vir jou kommissie verdien op elke betalende aanmelding wat daardeur kom. 'n Gerieflike manier om iets te deel waarvan jy hou, en langs die pad iets te verdien."],"cta":"Leer Individual ken","ps":"NS. Ons hoor altyd graag van funksies wat jy in Gadit wil sien. Antwoord net op hierdie e-pos."}},
  am: {"greetNamed":"ሰላም {name}፣","greetPlain":"ሰላም፣","footerReason":"ይህን ኢሜይል የተቀበሉት ለ Gadit ስለተመዘገቡ ነው።","unsubscribeLabel":"ምዝገባን ይሰርዙ","welcome":{"subject":"ወደ Gadit እንኳን በደህና መጡ","preheader":"አንድ መዝገበ ቃላት፣ አንድ ተልዕኮ። አንድን ቃል ሙሉ በሙሉ መረዳት። እንዴት እንደሚጀምሩ እነሆ።","paras":["ወደ Gadit እንኳን በደህና መጡ፣ ስለተቀላቀሉን እናመሰግናለን።","Gadit አንድ ተልዕኮ ያለው መዝገበ ቃላት ነው፦ አንድን ቃል ሙሉ በሙሉ መረዳት። የአንድ መስመር ፍቺ አይደለም፣ ደረቅ ትርጉምም አይደለም። ሁሉም ትርጉሞች፣ ፈሊጦች፣ የቃሉ አመጣጥ፣ እና ሰዎች ዛሬ ቃሉን በእውነት የሚጠቀሙበት መንገድ።","ነፃ መለያዎ በቀን 10 ፍለጋዎችንና እስከ 30 ቃላት የሚይዝ ደብተርን ያካትታል።","አንድን ቃል ሙሉ በሙሉ ሲረዱ፣ ከጀርባው ያለው ሐሳብ ግልጽ ይሆናል፣ ከእሱም ጋር የሚያስቡበት፣ የሚማሩበትና የሚወስኑበት መንገድ።","Gadit ሁልጊዜ የሚያድግ ሕያው መድረክ ነው። በማንኛውም ፍቺ፣ ምሳሌ ወይም ሌላ ክፍል ውስጥ ስህተት ካዩ፣ ሊጫኑት የሚገባ የሪፖርት ቁልፍ አለ። ቡድናችን ሁሉንም ያነባል፣ ያስተካክላልም።","ለመጀመር ዝግጁ ነዎት?"],"cta":"የመጀመሪያ ቃልዎን ይፈልጉ","signOff":["ከሰላምታ ጋር፣","የ Gadit ቡድን"]},"meanings":{"subject":"አንድ ቃል፣ ያላዩዋቸው ንብርብሮች","preheader":"አብዛኞቹ መሣሪያዎች ፍቺው ላይ ይቆማሉ። Gadit ቃሉ በአእምሮዎ እስኪቀር ድረስ ይቀጥላል።","exampleWord":"ልብ","paras":["“ልብ” የሚለውን ቃል ይውሰዱ፣ አንድ ቃል እንዴት አንድ ሙሉ ዓለም ሊከፍት እንደሚችል ይመልከቱ።","ልብ በደረታችን ውስጥ ደም የሚያዘዋውር አካል ነው። ልብ ስሜት ነው፣ ልቡ ተሰበረ ስንል። ልብ ማስተዋልና ትኩረት ነው፣ “ልብ በል” ማለት ትኩረት ስጥ ማለት ነው። ልብ ድፍረትና መተማመን ነው፣ ልበ ሙሉ ሰው። ልብ የአንድ ነገር መሃል ነው፣ የከተማው ልብ። ልብ ወለድ ደግሞ ከልብ የተወለደ ታሪክ ነው።","አንድ ቃል፣ በውስጡ ያላዩዋቸው ንብርብሮች፣ እያንዳንዳቸው በራሳቸው ዓለም ውስጥ የሚኖሩ።","በ Gadit ለእያንዳንዱ ፍቺ ሦስት እውነተኛ ምሳሌዎችን ያገኛሉ። ቃሉ በንድፈ ሐሳብ ብቻ ሳይሆን በተግባር የሚሠራባቸው ዓረፍተ ነገሮች። በዚህ መንገድ ቃሉ ምን እንደሚል ብቻ ሳይሆን፣ ሲነገር እንዴት እንደሚሰማም ያያሉ።","ይህ የ Gadit ልብ ነው። አንድ ቃል፣ ከመጀመሪያ እስከ መጨረሻ፣ በሁሉም ፍቺዎቹ።","“ልብ”ን እንዲፈልጉ እንጋብዝዎታለን፣ ምናልባትም ቀድሞውኑ ሙሉ በሙሉ እንደሚያውቁት የሚያስቡትን ሌላ ቃል። ሊገረሙ ይችላሉ።"],"cta":"“ልብ”ን ይፈልጉ፣ ሁሉንም ገጽታዎቹን ይዩ","ps":"ማስታወሻ፦ የሚያስገርም ትርጉም ሲያገኙ፣ አጠገቡ የማጋሪያ ቁልፍ አለ። ለሚያደንቀው ሰው መላክ የሚገባው ነው።"},"etymology":{"subject":"አንድ ቃል በእርግጥ ከየት ይመጣል","preheader":"እያንዳንዱ ቃል ያለፈ ታሪክ አለው፣ አንዳንዴም ያ ታሪክ የአሁኑን ያብራራል።","exampleWord":"ልብ","paras":["ወደምንወደው ክፍል ደርሰናል። ቃሉ ከየት እንደመጣ።","እያንዳንዱ ቃል ያለፈ ታሪክ አለው። አንዳንዴም ያ ታሪክ የአሁኑን ከማንኛውም ፍቺ በተሻለ ያብራራል።","ልብ ውብ ምሳሌ ነው። ቃሉ ከግዕዝ “ልብ” የመጣ ነው፣ ሥሩም በብዙ ሴማዊ ቋንቋዎች ውስጥ የሚገኝ በጣም ጥንታዊ ቃል ነው። በዕብራይስጥ “ሌቭ” ልብ ማለት ነው፣ በዓረብኛ ደግሞ ተመሳሳይ ሥር ያለው “ሉብ” የአንድ ነገር ውስጠኛ ክፍልና አእምሮ ማለት ነው።","በእነዚህ ጥንታዊ ቋንቋዎች ልብ የደረት አካል ብቻ አልነበረም፣ የማሰቢያና የማስተዋያ ቦታ ተደርጎም ይታይ ነበር። ለዚህ ነው ዛሬም በአማርኛ “ልብ በል” ስንል ትኩረት ስጥ ማለታችን፣ ልብ ወለድ ስንል ደግሞ በሰው ሐሳብ የተፈጠረ ታሪክ ማለታችን።","በአንድ ቃል ውስጥ ሙሉ ጉዞ። በጣም ከሚዳሰሰው ነገር፣ በደረት ውስጥ ካለው አካል፣ በጣም ረቂቅ ወደሆነው፣ ወደ ሰው ሐሳብና ማስተዋል። ሁሉም በሺዎች ለሚቆጠሩ ዓመታት ከእኛ ጋር በቆየ አንድ ቃል ውስጥ።","ይህን ካወቁ በኋላ ቃሉን በተሻለ ማስታወስ ብቻ አይደለም። ሁሉም ትርጉሞቹ ለምን እንደተያያዙም ይረዳሉ። በአጋጣሚ አብረው አይኖሩም።","በ Gadit ከእያንዳንዱ ቃል ፍቺዎች በታች አመጣጡን የሚያብራራ ክፍል አለ። ታሪካዊ ዳራው፣ ከየት እንደመጣ። መዝገበ ቃላትን ከፍቺዎች ዝርዝር ወደ ታሪክ የሚለውጠው ይህ ነው።"],"cta":"የሚቀጥለውን ቃል አመጣጥ ያግኙ"},"visual":{"subject":"በልጅ ዓይን ደረጃ ያለ ቃል","preheader":"Kids Mode፦ እያንዳንዱ ቃል በልጅ ቋንቋ ይብራራል፣ ጥልቀቱን ሳያጣ።","paras":["ከተቀበልናቸው በጣም የተለመዱ ጥያቄዎች አንዱ ቀላል ነበር። አንድ ልጅ የአንድ ቃል ትርጉም ምን እንደሆነ ይጠይቃል፣ ይፋዊው ፍቺ ግን ለእሱ በጣም የተወሳሰበ ነው።","ለዚህ ነው Gadit Kids Mode ያለው። ያብሩት፣ እያንዳንዱ ቃልም ከአምስት እስከ አሥር ዓመት ባለው ልጅ ቋንቋ ይብራራል። ያው ጥልቀት፣ ያለ ከባድ ቃላት።","“የስበት ኃይል”ን ይውሰዱ። በመደበኛው ሁነታ በፊዚክስና በክብደት መሳሳብ ይብራራል። በ Kids Mode ደግሞ ልጅ ወዲያውኑ የሚረዳው ነገር ይሆናል፦ ሁሉንም ነገር ወደ መሬት የሚስብ የማይታይ ኃይል፣ ለዚህም ነው ወደ ላይ የተወረወረ ኳስ ሁልጊዜ ወደ ታች የሚወርደው።","ይህ ለልጆች ብቻ አይደለም። አንዳንዴ አንድ ቃል በእርግጥ ከባድ ሲሆን፣ ቀላሉ ማብራሪያ አዋቂዎችም ቃሉን እንዲረዱ የሚያስፈልጋቸው ነገር ነው።","ከ Kids Mode ጋር Gadit ለእያንዳንዱ ትርጉም ሥዕልም ያሳያል፣ ልጁ ቃሉን ከማንበብ በተጨማሪ እንዲያየው። መረዳቱ በፍጥነት ይመጣል፣ ረዘም ላለ ጊዜም ይቆያል።","Kids Mode ልጆች ላሏቸው ቤተሰቦች የተዘጋጀው የ Family ዕቅድ አካል ነው። ለእያንዳንዱ ትርጉም ሥዕል በ Individual ዕቅድም ይገኛል።","አጠገብዎ ልጅ ካለ፣ ለአንድ ደቂቃ አብረውት ይቀመጡ፣ Kids Mode ን ያብሩ፣ አብረው ቃል ይፈልጉ፣ ሥዕሉንም ይመልከቱ። ያለ ድካም የመረዳት ቅጽበት ይህን ይመስላል።"],"cta":"Kids Mode ን ይመልከቱ"},"summary":{"subject":"ሁለት ሳምንታት፣ አንድ ቃል","preheader":"እስካሁን ያለው ጉዞ፣ እና ከዚህ ለመቀጠል ሁለት መንገዶች።","paras":["ባለፉት ሁለት ሳምንታት የአንድን ቃል የተለያዩ ገጽታዎች ተዋውቀናል። ሁሉንም ትርጉሞቹንና ታሪኩን።","ከዚህ ጎን ለጎን Gadit ን ለጥልቅ መረዳት መሣሪያ የሚያደርጉትን ባህሪያት ተዋውቀናል፦ Kids Mode እና ለእያንዳንዱ ትርጉም ሥዕል።","ከእነዚህ ባህሪያት አንዳንዶቹ ለሁሉም ተጠቃሚ ክፍት ናቸው። ነፃ መለያ በቀን 10 ፍለጋዎችንና እስከ 30 ቃላት የሚይዝ ደብተርን ያካትታል።","ሌሎቹ በ Individual ይከፈታሉ፦ ያልተገደበ ፍለጋ፣ ለእያንዳንዱ ትርጉም ሥዕል፣ እያንዳንዱን ቃል ከብልህ ልምምድ ጋር የሚያስቀምጥ ደብተር፣ ጨዋታዎችና ጥያቄዎች፣ “እያንዳንዱ ቃል” (የገጽ ፎቶ ያንሱና ማንኛውንም ቃል ይንኩ)፣ ለአነባበብ ልምምድ Say it፣ እና ዓረፍተ ነገር ጽፎ አስተያየት ማግኘት። Gadit የዕለት ተዕለት ልማድዎ ከሆነ፣ ልዩነቱን የሚያመጡት እነዚህ ባህሪያት ናቸው።","ቤት ውስጥ ልጆች አሉ? የ <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> ዕቅድ እስከ 5 ልጆችን ይሸፍናል፣ ከ Kids Mode እና ከወላጅ ሰሌዳ ጋር።","የአጋር ፕሮግራምም አለን፦ በእሱ በኩል ለሚመጣ እያንዳንዱ የሚከፈልበት ምዝገባ ኮሚሽን የሚያስገኝልዎ የግል ሊንክ። የሚወዱትን ነገር ለማጋራትና በዚያውም ገቢ ለማግኘት ምቹ መንገድ።"],"cta":"Individual ን ይወቁ","ps":"ማስታወሻ፦ በ Gadit ውስጥ ማየት የሚፈልጓቸውን ባህሪያት ሁልጊዜ መስማት እንወዳለን። ለዚህ ኢሜይል መልስ መስጠት ብቻ በቂ ነው።"}},
  ar: {"greetNamed":"مرحبًا {name}،","greetPlain":"مرحبًا،","footerReason":"تصلك هذه الرسالة لأنك سجّلت في Gadit.","unsubscribeLabel":"إلغاء الاشتراك","welcome":{"subject":"أهلًا بك في Gadit","preheader":"قاموس واحد ومهمة واحدة. أن تفهم الكلمة حتى النهاية. هكذا تبدأ.","paras":["أهلًا بك في Gadit، وشكرًا لانضمامك.","Gadit قاموس له مهمة واحدة: أن يكشف الكلمة كاملة. لا تعريفًا من سطر واحد، ولا ترجمة جافة. كل المعاني، والتعابير، وأصل الكلمة، والطرق التي يستعملها بها الناس اليوم فعلًا.","حسابك المجاني يشمل 10 عمليات بحث يوميًا ودفترًا يتسع حتى 30 كلمة.","حين تفهم الكلمة فهمًا كاملًا، تتضح الفكرة التي وراءها، ومعها طريقتك في التفكير والتعلّم واتخاذ القرار.","Gadit منصة حية لا تتوقف عن النمو. إذا لاحظت خطأ في أي تعريف أو مثال أو أي جزء آخر، فهناك زر للإبلاغ يستحق أن تضغطه. فريقنا يقرأ كل شيء ويصلحه.","هل أنت مستعد للبدء؟"],"cta":"ابحث عن كلمتك الأولى","signOff":["مع أطيب التحيات،","فريق Gadit"]},"meanings":{"subject":"كلمة واحدة، وطبقات لم ترها من قبل","preheader":"معظم الأدوات تتوقف عند التعريف. Gadit يواصل حتى تثبت الكلمة.","exampleWord":"عين","paras":["خذ كلمة «عين»، وانظر كيف يمكن لكلمة واحدة أن تفتح عالمًا كاملًا.","العين هي العضو الذي نبصر به. والعين هي نبع الماء الذي يخرج من الأرض، ومنها جاءت أسماء أماكن كثيرة. والعين أيضًا الجاسوس الذي يراقب لحساب غيره. والعين هي ذات الشيء ونفسه، كما نقول: هذا هو الرجل بعينه. والأعيان هم وجهاء القوم وأبرز الناس فيهم. والعين كذلك اسم حرف من حروف الهجاء، حرف ع.","كلمة واحدة، وطبقات لم ترها فيها، كل واحدة منها تعيش في عالمها الخاص.","في Gadit ستجد ثلاثة أمثلة حقيقية لكل تعريف. جمل تعمل فيها الكلمة في الواقع، لا في النظرية. هكذا ترى لا ما تعنيه الكلمة فحسب، بل كيف تبدو حين تُستعمل.","هذا هو قلب Gadit. كلمة واحدة، حتى النهاية، عبر كل تعريفاتها.","نقترح أن تبحث عن «عين»، وربما عن كلمة أخرى تظن أنك تفهمها جيدًا. قد تفاجئك."],"cta":"ابحث عن «عين» وشاهد كل وجوهها","ps":"ملاحظة: حين تجد معنى مفاجئًا، ستجد بجانبه زر مشاركة. يستحق أن ترسله إلى شخص سيقدّره."},"etymology":{"subject":"من أين تأتي الكلمة حقًا","preheader":"لكل كلمة ماضٍ، وأحيانًا يفسّر هذا الماضي الحاضر.","exampleWord":"عين","paras":["وصلنا إلى الجزء المفضل لدينا. من أين تأتي الكلمة.","لكل كلمة ماضٍ. وأحيانًا يفسّر هذا الماضي الحاضرَ أفضل من أي تعريف.","كلمة «عين» مثال جميل. إنها من أقدم الكلمات في اللغات السامية، ومعناها الأول العضو الذي نرى به. ولهذا نجدها بصورة قريبة جدًا في لغات شقيقة للعربية: «عَيِن» في العبرية، و«عَينا» في الآرامية، و«إينو» في الأكادية القديمة.","ومن العين التي تبصر انتقلت الكلمة إلى معانٍ أخرى بالتشبيه والمجاز. فسُمّي نبع الماء عينًا، وسُمّي الجاسوس عينًا لأنه يرى لغيره، ثم اتسع المعنى أكثر فصارت العين تعني ذات الشيء ونفسه. وحتى لاسم حرف العين قصة: في الأبجديات القديمة التي خرجت منها حروف العربية، كان هذا الحرف يُرسم أول الأمر على شكل عين، ولذلك حمل اسمها. ومن الشكل نفسه جاء أيضًا الحرف اللاتيني O.","رحلة كاملة في كلمة واحدة. من أكثر الأشياء حسية، العين التي ترى، إلى معنى مجرد هو ذات الشيء وحقيقته. وكل ذلك في كلمة رافقت الناس آلاف السنين.","حين تعرف هذا، لا تتذكر الكلمة أفضل فحسب، بل تفهم أيضًا لماذا ترتبط معانيها كلها ببعض. فهي لا تعيش معًا مصادفة.","في Gadit، تحت تعريفات كل كلمة، هناك قسم يشرح أصلها. الخلفية التاريخية، ومن أين جاءت. وهذا ما يحوّل القاموس من قائمة تعريفات إلى حكاية."],"cta":"اكتشف أصل الكلمة التالية"},"visual":{"subject":"كلمة على مستوى العين","preheader":"وضع الأطفال: كل كلمة مشروحة بلغة طفل، من دون أن تفقد عمقها.","paras":["من أكثر الطلبات التي وصلتنا طلبٌ بسيط. يسأل الطفل عن معنى كلمة، فيكون التعريف الرسمي معقّدًا جدًا عليه.","لهذا يوجد في Gadit وضع الأطفال. شغّله، فتُشرح كل كلمة بلغة طفل بين الخامسة والعاشرة. العمق نفسه، من دون الكلمات الصعبة.","خذ كلمة «عين». في الوضع العادي تُشرح في عدة طبقات. وفي وضع الأطفال تصبح شيئًا يفهمه الطفل فورًا، مثل: العين هي ما نرى به الألوان والوجوه، وعين الماء مكان يخرج منه الماء من الأرض.","وهذا ليس للأطفال فقط. أحيانًا، حين تكون الكلمة صعبة فعلًا، يكون الشرح البسيط هو بالضبط ما يحتاجه الكبار ليفهموها أيضًا.","وإلى جانب وضع الأطفال، يعرض Gadit صورة لكل معنى، فيستطيع الطفل أن يرى الكلمة لا أن يقرأها فقط. يصل الفهم أسرع ويبقى أطول.","وضع الأطفال جزء من خطة Family، المصممة للعائلات التي لديها أطفال. والصورة لكل معنى متوفرة أيضًا في خطة Individual.","إذا كان بقربك طفل، فاجلس معه دقيقة، وشغّلا وضع الأطفال، وابحثا معًا عن كلمة وانظرا إلى صورتها. هكذا تبدو لحظة الفهم التي تأتي بلا جهد."],"cta":"تعرّف على وضع الأطفال"},"summary":{"subject":"أسبوعان، وكلمة واحدة","preheader":"الرحلة، وطريقتان للمتابعة من هنا.","paras":["خلال الأسبوعين الماضيين تعرّفنا على الجوانب المختلفة للكلمة. كل معانيها، وتاريخها.","وإلى جانب ذلك تعرّفنا على الميزات التي تجعل Gadit أداة لفهم أعمق: وضع الأطفال، وصورة لكل معنى.","بعض هذه الميزات مفتوح لكل مستخدم. الحساب المجاني يشمل 10 عمليات بحث يوميًا ودفترًا يتسع حتى 30 كلمة.","والباقي يُفتح مع Individual: بحث غير محدود، وصورة لكل معنى، ودفتر يحفظ كل كلمة مع تدريب ذكي، وألعاب واختبارات، و«كل كلمة» (صوّر صفحة واضغط على أي كلمة)، و«قلها» لتدريب النطق، وتأليف جملة مع ملاحظات عليها. إذا أصبح Gadit جزءًا من يومك، فهذه هي الميزات التي تصنع الفرق.","لديك أطفال في البيت؟ خطة <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> تشمل حتى 5 أطفال، مع وضع الأطفال ولوحة للوالدين.","ولدينا أيضًا برنامج شركاء: رابط شخصي يمنحك عمولة عن كل اشتراك مدفوع يأتي عبره. طريقة مريحة لمشاركة شيء تحبه، والربح في الطريق."],"cta":"تعرّف على Individual","ps":"ملاحظة: يسعدنا دائمًا أن نعرف ما الميزات التي تودّ أن تراها في Gadit. يكفي أن تردّ على هذه الرسالة."}},
  bn: {"greetNamed":"হ্যালো {name},","greetPlain":"হ্যালো,","footerReason":"আপনি এই ইমেইলটি পাচ্ছেন কারণ আপনি Gadit-এ সাইন আপ করেছেন।","unsubscribeLabel":"আনসাবস্ক্রাইব করুন","welcome":{"subject":"Gadit-এ আপনাকে স্বাগতম","preheader":"একটি অভিধান, একটি লক্ষ্য। একটি শব্দকে পুরোপুরি বোঝা। এভাবে শুরু করুন।","paras":["Gadit-এ আপনাকে স্বাগতম, আর যোগ দেওয়ার জন্য ধন্যবাদ।","Gadit এমন একটি অভিধান যার লক্ষ্য একটাই: একটি শব্দকে পুরোপুরি বোঝা। এক লাইনের সংজ্ঞা নয়, শুকনো অনুবাদ নয়। সব অর্থ, বাগধারা, শব্দের উৎপত্তি, আর মানুষ আজ সত্যিই যেভাবে শব্দটি ব্যবহার করে।","আপনার ফ্রি অ্যাকাউন্টে দিনে 10টি খোঁজ আর 30টি শব্দ পর্যন্ত একটি নোটবুক আছে।","যখন আপনি একটি শব্দ পুরোপুরি বোঝেন, তখন তার পেছনের ধারণাটি স্পষ্ট হয়ে যায়, আর তার সঙ্গে আপনার ভাবা, শেখা আর সিদ্ধান্ত নেওয়ার ধরনও।","Gadit একটি জীবন্ত প্ল্যাটফর্ম যা ক্রমাগত বাড়ছে। কোনো সংজ্ঞা, উদাহরণ বা অন্য কোনো অংশে ভুল চোখে পড়লে রিপোর্ট বাটনটি অবশ্যই চাপুন। আমাদের টিম সবকিছু পড়ে আর ঠিক করে দেয়।","শুরু করতে প্রস্তুত?"],"cta":"আপনার প্রথম শব্দটি খুঁজুন","signOff":["শুভেচ্ছাসহ,","Gadit টিম"]},"meanings":{"subject":"একটি শব্দ, এমন স্তর যা আপনি দেখেননি","preheader":"বেশিরভাগ টুল সংজ্ঞাতেই থেমে যায়। Gadit এগিয়ে যায়, যতক্ষণ না মনে গেঁথে যায়।","exampleWord":"মাথা","paras":["“মাথা” শব্দটি নিন, আর দেখুন একটি শব্দ কীভাবে পুরো একটা জগৎ খুলে দিতে পারে।","মাথা হলো শরীরের সবচেয়ে ওপরের অংশ। মাথা কোনো কিছুর চূড়া বা ওপরের দিক, গাছের মাথা, পাহাড়ের মাথা। মাথা কোনো কিছুর শেষ প্রান্ত, রাস্তার মাথা। মাথা দলের প্রধান, পাড়ার মাথা। মাথা বুদ্ধি, অঙ্কে ওর মাথা খুব ভালো। আর বাগধারায় মাথা ঘামানো মানে কোনো কিছু নিয়ে ভাবা।","একটি শব্দ, এমন সব স্তর যা আপনি এতে দেখেননি, প্রতিটি নিজের জগতে।","Gadit-এ আপনি প্রতিটি সংজ্ঞার জন্য তিনটি আসল উদাহরণ পাবেন। এমন বাক্য যেখানে শব্দটি বাস্তবে কাজ করে, শুধু তত্ত্বে নয়। এভাবে আপনি শুধু দেখেন না শব্দটি কী বলে, বরং ব্যবহারে সেটি কেমন শোনায়।","এটাই Gadit-এর হৃদয়। একটি শব্দ, শুরু থেকে শেষ পর্যন্ত, তার সব সংজ্ঞাসহ।","আমরা পরামর্শ দিই “মাথা” খুঁজে দেখতে, আর হয়তো আরেকটি শব্দ, যেটা আপনি মনে করেন আগে থেকেই পুরোপুরি বোঝেন। আপনি অবাক হতে পারেন।"],"cta":"“মাথা” খুঁজুন আর সব রূপ দেখুন","ps":"পুনশ্চ: যখন কোনো অবাক করা অর্থ পাবেন, তার পাশেই একটি শেয়ার বাটন আছে। এমন কাউকে পাঠানোর মতো যিনি এর কদর করবেন।"},"etymology":{"subject":"একটি শব্দ আসলে কোথা থেকে আসে","preheader":"প্রতিটি শব্দের একটি অতীত আছে, আর কখনো কখনো সেই অতীত বর্তমানকে ব্যাখ্যা করে।","exampleWord":"মাথা","paras":["আমরা পৌঁছে গেছি আমাদের প্রিয় অংশে। শব্দটি কোথা থেকে এসেছে।","প্রতিটি শব্দের একটি অতীত আছে। আর কখনো কখনো সেই অতীত যেকোনো সংজ্ঞার চেয়ে বর্তমানকে ভালো ব্যাখ্যা করে।","মাথা এর একটি সুন্দর উদাহরণ। এর মূল সংস্কৃত “মস্তক”, যার অর্থ মাথা, আবার কোনো কিছুর চূড়াও। শতাব্দীর পর শতাব্দী মানুষের মুখে মুখে ঘুরে, প্রাকৃতের মধ্য দিয়ে, মস্তক বদলে হয়ে গেছে মাথা। মজার ব্যাপার, সংস্কৃত শব্দটিও বাংলায় রয়ে গেছে: আনুষ্ঠানিক ভাষায় আমরা এখনও “মস্তক” বলি। একই উৎস থেকে এসেছে হিন্দির “माथा”, যার মানে কপাল।","শরীরের একটি অঙ্গ থেকে অর্থটি ছড়িয়ে পড়েছে। মাথা যেমন শরীরের সবচেয়ে ওপরে, তেমনি গাছের মাথা আর পাহাড়ের মাথা। মাথা যেমন শরীরকে চালায়, তেমনি দলের মাথা। আর মাথার ভেতরেই যেহেতু চিন্তা, তাই মাথা মানে বুদ্ধিও।","একটি শব্দে পুরো একটা যাত্রা। সবচেয়ে বাস্তব জিনিস, শরীরের একটি অঙ্গ, থেকে সবচেয়ে বিমূর্ত জিনিস, মানুষের বুদ্ধি পর্যন্ত। সবই এমন একটি শব্দে যা হাজার বছরেরও বেশি সময় ধরে আমাদের সঙ্গে আছে।","এটা জানার পর আপনি শুধু শব্দটি ভালো মনে রাখেন না। আপনি এটাও বোঝেন কেন এর সব অর্থ একে অপরের সঙ্গে জড়িত। তারা হঠাৎ করে একসঙ্গে থাকে না।","Gadit-এ প্রতিটি শব্দের সংজ্ঞার নিচে একটি অংশ আছে যা তার উৎপত্তি ব্যাখ্যা করে। ঐতিহাসিক পটভূমি, শব্দটি কোথা থেকে এসেছে। এটাই একটি অভিধানকে সংজ্ঞার তালিকা থেকে একটি গল্পে বদলে দেয়।"],"cta":"পরের শব্দের উৎপত্তি জানুন"},"visual":{"subject":"শিশুর চোখের উচ্চতায় একটি শব্দ","preheader":"কিডস মোড: প্রতিটি শব্দ শিশুর ভাষায় ব্যাখ্যা করা, গভীরতা না হারিয়ে।","paras":["আমরা সবচেয়ে বেশি যে অনুরোধগুলো পেয়েছি, তার একটি খুব সহজ। একটি শিশু জিজ্ঞেস করে একটি শব্দের মানে কী, আর আনুষ্ঠানিক সংজ্ঞাটি তার জন্য খুব জটিল।","এজন্যই Gadit-এ আছে কিডস মোড। চালু করুন, আর প্রতিটি শব্দ ব্যাখ্যা করা হবে পাঁচ থেকে দশ বছরের শিশুর ভাষায়। একই গভীরতা, কঠিন শব্দ ছাড়া।","“মাধ্যাকর্ষণ” শব্দটি নিন। সাধারণ মোডে এটি পদার্থবিদ্যা আর ভরের আকর্ষণ দিয়ে ব্যাখ্যা করা হয়। কিডস মোডে এটি এমন কিছু হয়ে যায় যা শিশু সঙ্গে সঙ্গে বোঝে: একটি অদৃশ্য টান যা সবকিছুকে মাটির দিকে টেনে নেয়, তাই ওপরে ছোড়া বল সবসময় নিচে নেমে আসে।","আর এটা শুধু শিশুদের জন্য নয়। কখনো কখনো, যখন একটি শব্দ সত্যিই কঠিন, সহজ ব্যাখ্যাটাই বড়দেরও বুঝতে সাহায্য করে।","কিডস মোডের পাশাপাশি Gadit প্রতিটি অর্থের জন্য একটি ছবিও দেখায়, যাতে শিশু শব্দটি পড়ার সঙ্গে সঙ্গে দেখতেও পায়। বোঝাটা দ্রুত আসে আর অনেক দিন থাকে।","কিডস মোড Family প্ল্যানের অংশ, যা শিশু আছে এমন পরিবারের জন্য তৈরি। প্রতিটি অর্থের জন্য ছবি Individual প্ল্যানেও আছে।","কাছে কোনো শিশু থাকলে, এক মিনিট তার সঙ্গে বসুন, কিডস মোড চালু করুন, একসঙ্গে একটি শব্দ খুঁজুন আর তার ছবিটি দেখুন। অনায়াসে বুঝে ফেলার মুহূর্তটা দেখতে এমনই।"],"cta":"কিডস মোড দেখুন"},"summary":{"subject":"দুই সপ্তাহ, একটি শব্দ","preheader":"এ পর্যন্ত যাত্রা, আর এখান থেকে এগোনোর দুটি পথ।","paras":["গত দুই সপ্তাহে আমরা একটি শব্দের নানা দিক চিনেছি। তার সব অর্থ, আর তার ইতিহাস।","এর পাশাপাশি আমরা চিনেছি সেই ফিচারগুলো যা Gadit-কে গভীরভাবে বোঝার একটি টুল করে তোলে: কিডস মোড, আর প্রতিটি অর্থের জন্য একটি ছবি।","এর মধ্যে কিছু ফিচার সব ব্যবহারকারীর জন্য খোলা। ফ্রি অ্যাকাউন্টে দিনে 10টি খোঁজ আর 30টি শব্দ পর্যন্ত একটি নোটবুক আছে।","বাকিগুলো খোলে Individual-এ: সীমাহীন খোঁজ, প্রতিটি অর্থের জন্য একটি ছবি, একটি নোটবুক যা প্রতিটি শব্দ স্মার্ট অনুশীলনসহ সেভ করে, গেম আর কুইজ, “প্রতিটি শব্দ” (পাতার ছবি তুলুন আর যেকোনো শব্দে ট্যাপ করুন), উচ্চারণ অনুশীলনের জন্য Say it, আর ফিডব্যাকসহ বাক্য রচনা। Gadit যদি আপনার রোজকার অভ্যাস হয়ে থাকে, এই ফিচারগুলোই পার্থক্য গড়ে দেয়।","বাড়িতে বাচ্চা আছে? <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> প্ল্যানে 5 জন পর্যন্ত শিশু থাকতে পারে, সঙ্গে কিডস মোড আর অভিভাবক বোর্ড।","আর আমাদের একটি পার্টনার প্রোগ্রামও আছে: একটি ব্যক্তিগত লিংক, যার মাধ্যমে আসা প্রতিটি পেইড সাইন আপে আপনি কমিশন পান। পছন্দের জিনিস শেয়ার করার আর সঙ্গে আয় করার একটি সহজ উপায়।"],"cta":"Individual সম্পর্কে জানুন","ps":"পুনশ্চ: Gadit-এ আপনি কোন কোন ফিচার দেখতে চান, তা জানতে আমরা সবসময়ই ভালোবাসি। শুধু এই ইমেইলের উত্তর দিন।"}},
  cs: {"greetNamed":"Dobrý den, {name},","greetPlain":"Dobrý den,","footerReason":"Tento e-mail dostáváte, protože máte účet v Gadit.","unsubscribeLabel":"Odhlásit odběr","welcome":{"subject":"Vítejte v Gadit","preheader":"Jeden slovník, jedno poslání. Pochopit slovo do hloubky. Tady je, jak začít.","paras":["Vítejte v Gadit a děkujeme, že jste s námi.","Gadit je slovník s jediným posláním: pochopit slovo do hloubky. Žádná definice na jeden řádek, žádný suchý překlad. Všechny významy, ustálená spojení, původ slova a to, jak ho lidé dnes doopravdy používají.","Váš bezplatný účet zahrnuje 10 vyhledání denně a sešit až pro 30 slov.","Když slovo pochopíte úplně, vyjasní se i myšlenka, která za ním stojí, a s ní i to, jak přemýšlíte, učíte se a rozhodujete.","Gadit je živá platforma, která stále roste. Pokud narazíte na chybu v definici, v příkladu nebo kdekoli jinde, je tu tlačítko pro nahlášení a vyplatí se ho zmáčknout. Náš tým všechno čte a opravuje.","Můžeme začít?"],"cta":"Vyhledejte své první slovo","signOff":["Srdečně,","Tým Gadit"]},"meanings":{"subject":"Jedno slovo, vrstvy, které jste v něm neviděli","preheader":"Většina nástrojů skončí u definice. Gadit pokračuje, dokud vám slovo neutkví v paměti.","exampleWord":"koruna","paras":["Vezměte si slovo koruna a podívejte se, jak jedno slovo dokáže otevřít celý svět.","Koruna je to, co nosí na hlavě král nebo královna. Koruna je také česká měna, kterou platíte v obchodě. Koruna stromu je jeho horní část s větvemi a listy. Koruna hráze je její nejvyšší okraj, po kterém se dá projít. Zubař vám může nasadit korunku na zub. A koruna může znamenat i celé království, jako v Zemích Koruny české.","Jedno slovo, vrstvy, které jste v něm možná neviděli, a každá žije ve svém vlastním světě.","V Gadit najdete ke každé definici tři skutečné příklady. Věty, ve kterých slovo funguje v praxi, ne v teorii. Tak vidíte nejen, co slovo znamená, ale i jak zní, když se používá.","To je srdce Gadit. Jedno slovo, až do konce, ve všech jeho významech.","Doporučujeme vyhledat slovo koruna a možná ještě další slovo, o kterém si myslíte, že ho už dobře znáte. Možná vás překvapí."],"cta":"Vyhledejte slovo koruna","ps":"P.S. Když najdete překvapivý význam, je vedle něj tlačítko pro sdílení. Vyplatí se ho poslat někomu, kdo to ocení."},"etymology":{"subject":"Odkud slovo opravdu pochází","preheader":"Každé slovo má minulost a někdy vysvětluje přítomnost.","exampleWord":"koruna","paras":["Dostali jsme se k naší oblíbené části. Odkud slovo pochází.","Každé slovo má minulost. A někdy ta minulost vysvětluje přítomnost lépe než jakákoli definice.","Koruna je krásný příklad. Pochází z latinského corona, které znamenalo věnec. Ve starém Římě se věncem z vavřínu nebo z dubových listů odměňovali vítězové a hrdinové. Ze stejného latinského slova pochází i anglické crown a německé Krone.","Z věnce na hlavě se stala koruna panovníka, znamení moci. Odtud se slovo rozšířilo dál: na celé království, jako v Zemích Koruny české, na horní část stromu rozprostřenou nad kmenem, a nakonec i na peníze. Rakousko-Uhersko zavedlo korunu jako měnu v roce 1892 a nová československá měna si to jméno v roce 1919 ponechala.","Celá cesta v jednom slově. Od prostého věnce z listů k panovníkovi, k celé zemi a k penězům v peněžence.","Když to víte, slovo si nejen lépe zapamatujete. Pochopíte také, proč spolu všechny jeho významy souvisejí. Nežijí spolu náhodou.","V Gadit najdete pod definicemi každého slova část, která vysvětluje jeho původ. Historické pozadí, odkud se vzalo. Právě to mění slovník ze seznamu definic v příběh."],"cta":"Objevte původ dalšího slova"},"visual":{"subject":"Slovo ve výšce očí","preheader":"Dětský režim: každé slovo vysvětlené řečí dítěte, bez ztráty hloubky.","paras":["Jedna z nejčastějších žádostí, které jsme dostávali, byla jednoduchá. Dítě se zeptá, co nějaké slovo znamená, a oficiální definice je pro něj příliš složitá.","Proto má Gadit Dětský režim. Zapnete ho a každé slovo je vysvětlené řečí dítěte od pěti do deseti let. Stejná hloubka, jen bez těžkých slov.","Vezměte si slovo gravitace. V běžném režimu se mluví o silách a hmotnosti. V Dětském režimu je to něco, co dítě pochopí hned: to, kvůli čemu věci padají na podlahu, když je pustíte, a co nás drží na zemi.","A není to jen pro děti. Někdy, když je slovo opravdu těžké, je jednoduché vysvětlení přesně to, co potřebují i dospělí, aby ho pochopili.","Vedle Dětského režimu ukazuje Gadit také obrázek ke každému významu, aby dítě slovo nejen přečetlo, ale i vidělo. Porozumění přijde rychleji a vydrží déle.","Dětský režim je součástí tarifu Family, který je určený pro rodiny s dětmi. Obrázek ke každému významu je i v tarifu Individual.","Pokud máte poblíž dítě, sedněte si s ním na chvilku, zapněte Dětský režim, vyhledejte spolu slovo a podívejte se na jeho obrázek. Takhle vypadá chvíle, kdy porozumění přijde bez námahy."],"cta":"Poznejte Dětský režim"},"summary":{"subject":"Dva týdny, jedno slovo","preheader":"Cesta, kterou jsme ušli, a dvě možnosti, jak pokračovat.","paras":["Během posledních dvou týdnů jsme poznali různé stránky slova. Všechny jeho významy a jeho historii.","Spolu s tím jsme poznali funkce, díky kterým je Gadit nástrojem pro hlubší porozumění: Dětský režim a obrázek ke každému významu.","Některé z těchto funkcí jsou otevřené všem. Bezplatný účet zahrnuje 10 vyhledání denně a sešit až pro 30 slov.","Ostatní odemkne Individual: neomezené vyhledávání, obrázek ke každému významu, sešit, který uloží každé slovo, s chytrým procvičováním, hry a kvízy, Každé slovo (vyfoťte stránku a klepněte na libovolné slovo), Řekni to pro procvičování výslovnosti a skládání vět se zpětnou vazbou. Pokud se Gadit stal součástí vašeho dne, právě tyhle funkce dělají rozdíl.","Máte doma děti? Tarif <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> zahrnuje až 5 dětí, s Dětským režimem a rodičovským přehledem.","A máme také partnerský program: osobní odkaz, díky kterému získáte provizi z každé placené registrace, která přes něj přijde. Pohodlný způsob, jak sdílet něco, co máte rádi, a přitom si vydělat."],"cta":"Poznejte Individual","ps":"P.S. Vždy rádi uslyšíme, jaké funkce byste v Gadit chtěli vidět. Stačí odpovědět na tento e-mail."}},
  da: {"greetNamed":"Hej {name},","greetPlain":"Hej,","footerReason":"Du modtager denne e-mail, fordi du har tilmeldt dig Gadit.","unsubscribeLabel":"Afmeld","welcome":{"subject":"Velkommen til Gadit","preheader":"Én ordbog, én mission. At forstå et ord helt til bunds. Sådan kommer du i gang.","paras":["Velkommen til Gadit, og tak fordi du er med.","Gadit er en ordbog med én mission: at forstå et ord helt til bunds. Ikke en definition på én linje, ikke en tør oversættelse. Alle betydningerne, udtrykkene, ordets oprindelse og de måder, folk faktisk bruger det på i dag.","Din gratis konto giver dig 10 opslag om dagen og en notesbog med plads til op til 30 ord.","Når du forstår et ord helt, bliver idéen bag det klar, og med den også måden, du tænker, lærer og beslutter på.","Gadit er en levende platform, der hele tiden vokser. Hvis du finder en fejl i en definition, et eksempel eller noget andet, er der en rapportknap, som er værd at trykke på. Vores team læser alt og retter det.","Klar til at starte?"],"cta":"Slå dit første ord op","signOff":["Venlig hilsen,","Teamet bag Gadit"]},"meanings":{"subject":"Ét ord, lag du ikke havde set","preheader":"De fleste værktøjer stopper ved definitionen. Gadit fortsætter, til det sidder fast.","exampleWord":"ånd","paras":["Tag ordet ånd, og se hvordan ét ord kan åbne en hel verden.","Ånd er det inderste i noget, som i lovens ånd. Det er tanken og intellektet, som i åndsliv og åndsarbejde. Det er et væsen uden krop, en ond ånd eller ånden i flasken. Det er den stemning, der præger en tid eller en gruppe, som i tidsånden eller holdånden. Og det kan være et menneske, når vi taler om en af tidens store ånder.","Ét ord, lag du ikke havde set i det, og hvert lag lever i sin egen verden.","I Gadit finder du tre rigtige eksempler på hver definition. Sætninger, hvor ordet virker i praksis, ikke i teorien. Så ser du ikke kun, hvad ordet siger, men også hvordan det lyder, når det bruges.","Det er hjertet i Gadit. Ét ord, hele vejen igennem, på tværs af alle dets definitioner.","Vi foreslår, at du slår ånd op, og måske også et ord, du tror, du allerede forstår. Du bliver måske overrasket."],"cta":"Slå ånd op og se alle siderne","ps":"PS. Når du finder en overraskende betydning, er der en deleknap lige ved siden af. Den er værd at sende til en, der vil sætte pris på den."},"etymology":{"subject":"Hvor et ord egentlig kommer fra","preheader":"Hvert ord har en fortid, og nogle gange forklarer den nutiden.","exampleWord":"ånd","paras":["Nu er vi nået til vores yndlingsdel. Hvor ordet kommer fra.","Hvert ord har en fortid. Og nogle gange forklarer den fortid nutiden bedre end nogen definition.","Ånd er et smukt eksempel. Det kommer fra oldnordisk andi, som betød ånde, den luft du trækker ind og puster ud. Det er den samme rod, du finder i ånde, åndedræt og åndenød. Alle handler de i bund og grund om vejret.","Fra den fysiske ånde voksede idéen om livskraften i os, den ånde, der gør en krop levende. Og fra den voksede noget mere abstrakt: menneskets ånd, det inderste i en person.","En hel rejse i ét ord. Fra det mest fysiske, vejret, til det mindst fysiske, et menneskes ånd. Alt sammen i ét ord, der har fulgt os i over tusind år.","Når du ved det, husker du ikke bare ordet bedre. Du forstår også, hvorfor alle dets betydninger hænger sammen. De bor ikke sammen ved et tilfælde.","I Gadit er der under definitionerne af hvert ord et afsnit, der forklarer ordets oprindelse. Den historiske baggrund, hvor det kom fra. Det er det, der gør en ordbog fra en liste af definitioner til en fortælling."],"cta":"Opdag oprindelsen af det næste ord"},"visual":{"subject":"Et ord i øjenhøjde","preheader":"Børnetilstand: hvert ord forklaret på et barns sprog, uden at miste dybden.","paras":["En af de ting, vi oftest er blevet spurgt om, var enkel. Et barn spørger, hvad et ord betyder, og den officielle definition er for svær for det.","Derfor har Gadit Børnetilstand. Slå den til, og hvert ord bliver forklaret på sproget for et barn på fem til ti år. Den samme dybde, uden de store ord.","Tag ånd. I almindelig tilstand bliver det forklaret i flere lag. I Børnetilstand bliver det noget, et barn forstår med det samme, som holdånd: følelsen af at høre til et hold og ville gøre det godt sammen.","Og det er ikke kun for børn. Nogle gange, når et ord er virkelig svært, er den enkle forklaring præcis det, voksne også har brug for for at forstå det.","Ved siden af Børnetilstand viser Gadit også et billede til hver betydning, så et barn kan se ordet og ikke kun læse det. Forståelsen kommer hurtigere og bliver længere.","Børnetilstand er en del af Family-abonnementet, der er lavet til familier med børn. Et billede til hver betydning følger også med Individual-abonnementet.","Er der et barn i nærheden, så sæt dig sammen med det et øjeblik, slå Børnetilstand til, slå et ord op sammen og se på billedet. Sådan ser et øjeblik af forståelse uden besvær ud."],"cta":"Se Børnetilstand"},"summary":{"subject":"To uger, ét ord","preheader":"Rejsen, og to måder at fortsætte på herfra.","paras":["I de sidste to uger har vi lært de forskellige sider af et ord at kende. Alle dets betydninger, og dets historie.","Samtidig har vi lært de funktioner at kende, der gør Gadit til et værktøj til dybere forståelse: Børnetilstand, og et billede til hver betydning.","Nogle af funktionerne er åbne for alle. En gratis konto giver 10 opslag om dagen og en notesbog med plads til op til 30 ord.","Resten låses op med Individual: ubegrænsede opslag, et billede til hver betydning, en notesbog, der gemmer hvert ord med smart øvelse, spil og quizzer, Hvert ord (tag et billede af en side, og tryk på et hvilket som helst ord), Sig det til at øve udtale, og at skrive en sætning og få feedback. Hvis Gadit er blevet en del af din hverdag, er det de funktioner, der gør forskellen.","Børn derhjemme? <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a>-abonnementet dækker op til 5 børn, med Børnetilstand og en forældreoversigt.","Og vi har også et partnerprogram: et personligt link, der giver dig provision for hver betalende tilmelding, der kommer igennem det. En nem måde at dele noget, du holder af, og tjene lidt undervejs."],"cta":"Mød Individual","ps":"PS. Vi hører altid gerne om funktioner, du kunne tænke dig at se i Gadit. Svar bare på denne e-mail."}},
  el: {"greetNamed":"Γεια σου {name},","greetPlain":"Γεια σου,","footerReason":"Λαμβάνεις αυτό το email επειδή εγγράφηκες στο Gadit.","unsubscribeLabel":"Απεγγραφή","welcome":{"subject":"Καλώς ήρθες στο Gadit","preheader":"Ένα λεξικό, μία αποστολή. Να καταλάβεις μια λέξη ως το τέλος. Δες πώς ξεκινάς.","paras":["Καλώς ήρθες στο Gadit, και ευχαριστούμε που έγινες μέλος.","Το Gadit είναι ένα λεξικό με μία αποστολή: να ξεκλειδώσει μια λέξη ως το τέλος. Όχι έναν ορισμό μιας γραμμής, όχι μια στεγνή μετάφραση. Όλες τις σημασίες, τις εκφράσεις, την προέλευση της λέξης και τους τρόπους που οι άνθρωποι τη χρησιμοποιούν πραγματικά σήμερα.","Ο δωρεάν λογαριασμός σου περιλαμβάνει 10 αναζητήσεις την ημέρα και ένα τετράδιο έως 30 λέξεων.","Όταν καταλαβαίνεις μια λέξη ολοκληρωτικά, η ιδέα πίσω της γίνεται καθαρή, και μαζί της ο τρόπος που σκέφτεσαι, μαθαίνεις και αποφασίζεις.","Το Gadit είναι μια ζωντανή πλατφόρμα που μεγαλώνει συνεχώς. Αν εντοπίσεις λάθος σε κάποιον ορισμό, σε κάποιο παράδειγμα ή σε οποιοδήποτε άλλο σημείο, υπάρχει ένα κουμπί αναφοράς που αξίζει να πατήσεις. Η ομάδα μας διαβάζει τα πάντα και τα διορθώνει.","Ξεκινάμε;"],"cta":"Αναζήτησε την πρώτη σου λέξη","signOff":["Με εκτίμηση,","Η ομάδα του Gadit"]},"meanings":{"subject":"Μία λέξη, στρώσεις που δεν είχες δει","preheader":"Τα περισσότερα εργαλεία σταματούν στον ορισμό. Το Gadit συνεχίζει μέχρι να μείνει.","exampleWord":"λόγος","paras":["Πάρε τη λέξη «λόγος» και δες πώς μία λέξη μπορεί να ανοίξει έναν ολόκληρο κόσμο.","Λόγος είναι η αιτία, όπως όταν ρωτάμε για ποιο λόγο έγινε κάτι. Λόγος είναι η ομιλία που εκφωνεί κάποιος, ένας λόγος σε μια τελετή. Λόγος είναι η υπόσχεση, όταν δίνεις τον λόγο σου. Λόγος είναι η ικανότητα του ανθρώπου να μιλά και να σκέφτεται. Στα μαθηματικά, λόγος είναι η σχέση δύο αριθμών, όπως ο λόγος ένα προς δύο. Και στη λογοτεχνία, πεζός λόγος είναι το κείμενο που δεν γράφεται σε στίχους.","Μία λέξη, στρώσεις που δεν είχες δει σε αυτήν, και η καθεμία ζει στον δικό της κόσμο.","Στο Gadit θα βρεις τρία πραγματικά παραδείγματα για κάθε ορισμό. Προτάσεις όπου η λέξη λειτουργεί στην πράξη, όχι στη θεωρία. Έτσι βλέπεις όχι μόνο τι λέει η λέξη, αλλά και πώς ακούγεται όταν χρησιμοποιείται.","Αυτή είναι η καρδιά του Gadit. Μία λέξη, ως το τέλος, σε όλους τους ορισμούς της.","Σου προτείνουμε να αναζητήσεις τη λέξη «λόγος», και ίσως μια ακόμη λέξη που νομίζεις ότι ήδη καταλαβαίνεις. Μπορεί να εκπλαγείς."],"cta":"Αναζήτησε τη λέξη «λόγος» και δες όλες τις όψεις της","ps":"Υ.Γ. Όταν βρεις μια σημασία που σε εκπλήσσει, υπάρχει δίπλα της ένα κουμπί κοινοποίησης. Αξίζει να τη στείλεις σε κάποιον που θα την εκτιμήσει."},"etymology":{"subject":"Από πού έρχεται πραγματικά μια λέξη","preheader":"Κάθε λέξη έχει ένα παρελθόν, και μερικές φορές αυτό εξηγεί το παρόν.","exampleWord":"λόγος","paras":["Φτάσαμε στο αγαπημένο μας κομμάτι. Από πού έρχεται η λέξη.","Κάθε λέξη έχει ένα παρελθόν. Και μερικές φορές αυτό το παρελθόν εξηγεί το παρόν καλύτερα από κάθε ορισμό.","Ο λόγος είναι ένα όμορφο παράδειγμα. Προέρχεται από το αρχαίο ρήμα «λέγω», που αρχικά σήμαινε μαζεύω, συλλέγω, διαλέγω. Αυτή η παλιά σημασία ζει ακόμη σε λέξεις όπως «συλλέγω», «συλλογή» και «διαλέγω». Από το να μαζεύεις και να βάζεις πράγματα σε σειρά, το ρήμα πέρασε στο να μετράς, και τελικά στο να λες.","Έτσι ο λόγος έγινε πρώτα αυτό που λέγεται, η ομιλία, αλλά και ο υπολογισμός. Και από εκεί κάτι πιο αφηρημένο: η σκέψη που βάζει τα πράγματα σε τάξη, η αιτία πίσω από κάτι. Από την ίδια ρίζα έχουμε τη «λογική», τον «διάλογο», τη «λέξη» και το «λεξικό», ενώ πολλές γλώσσες δανείστηκαν το ελληνικό -λογία για τις επιστήμες, όπως βιολογία και ψυχολογία.","Ένα ολόκληρο ταξίδι σε μία λέξη. Από την πιο απτή κίνηση, να μαζεύεις πράγματα με τα χέρια, ως το πιο άυλο, τη σκέψη του ανθρώπου. Όλα σε μία λέξη που μένει μαζί μας εδώ και χιλιάδες χρόνια.","Όταν το ξέρεις αυτό, δεν θυμάσαι μόνο καλύτερα τη λέξη. Καταλαβαίνεις και γιατί όλες οι σημασίες της συνδέονται. Δεν ζουν μαζί τυχαία.","Στο Gadit, κάτω από τους ορισμούς κάθε λέξης, υπάρχει μια ενότητα που εξηγεί την προέλευσή της. Το ιστορικό της υπόβαθρο, από πού ήρθε. Αυτό είναι που μετατρέπει ένα λεξικό από λίστα ορισμών σε ιστορία."],"cta":"Ανακάλυψε την προέλευση της επόμενης λέξης"},"visual":{"subject":"Μια λέξη στο ύψος των ματιών","preheader":"Λειτουργία για παιδιά: κάθε λέξη εξηγημένη στη γλώσσα ενός παιδιού, χωρίς να χάνει το βάθος της.","paras":["Ένα από τα πιο συχνά αιτήματα που λάβαμε ήταν απλό. Ένα παιδί ρωτά τι σημαίνει μια λέξη, και ο επίσημος ορισμός είναι πολύ περίπλοκος για εκείνο.","Γι' αυτό το Gadit έχει τη Λειτουργία για παιδιά. Την ενεργοποιείς και κάθε λέξη εξηγείται στη γλώσσα ενός παιδιού πέντε έως δέκα ετών. Το ίδιο βάθος, χωρίς τις δύσκολες λέξεις.","Πάρε τη λέξη «λόγος». Στην κανονική λειτουργία εξηγείται σε πολλές στρώσεις. Στη Λειτουργία για παιδιά γίνεται κάτι που ένα παιδί καταλαβαίνει αμέσως, όπως ότι «δίνω τον λόγο μου» σημαίνει υπόσχομαι ότι θα κάνω κάτι και το εννοώ.","Και δεν είναι μόνο για παιδιά. Μερικές φορές, όταν μια λέξη είναι πραγματικά δύσκολη, η απλή εξήγηση είναι ακριβώς αυτό που χρειάζονται και οι μεγάλοι για να την καταλάβουν.","Δίπλα στη Λειτουργία για παιδιά, το Gadit δείχνει επίσης μια εικόνα για κάθε σημασία, ώστε το παιδί να μπορεί να δει τη λέξη και όχι μόνο να τη διαβάσει. Η κατανόηση έρχεται πιο γρήγορα και μένει περισσότερο.","Η Λειτουργία για παιδιά είναι μέρος του Family, που φτιάχτηκε για οικογένειες με παιδιά. Η εικόνα για κάθε σημασία περιλαμβάνεται και στο Individual.","Αν υπάρχει ένα παιδί κοντά σου, κάτσε μαζί του για ένα λεπτό, ενεργοποιήστε τη Λειτουργία για παιδιά, αναζητήστε μαζί μια λέξη και κοιτάξτε την εικόνα της. Έτσι μοιάζει η στιγμή της κατανόησης χωρίς κόπο."],"cta":"Γνώρισε τη Λειτουργία για παιδιά"},"summary":{"subject":"Δύο εβδομάδες, μία λέξη","preheader":"Η διαδρομή, και δύο τρόποι να συνεχίσεις από εδώ.","paras":["Τις τελευταίες δύο εβδομάδες γνωρίσαμε τις διαφορετικές όψεις μιας λέξης. Όλες τις σημασίες της και την ιστορία της.","Μαζί με αυτό, γνωρίσαμε τις λειτουργίες που κάνουν το Gadit εργαλείο για βαθύτερη κατανόηση: τη Λειτουργία για παιδιά και μια εικόνα για κάθε σημασία.","Κάποιες από αυτές τις λειτουργίες είναι ανοιχτές σε κάθε χρήστη. Ένας δωρεάν λογαριασμός περιλαμβάνει 10 αναζητήσεις την ημέρα και ένα τετράδιο έως 30 λέξεων.","Οι υπόλοιπες ξεκλειδώνουν με το Individual: απεριόριστες αναζητήσεις, μια εικόνα για κάθε σημασία, ένα τετράδιο που κρατά κάθε λέξη με έξυπνη εξάσκηση, παιχνίδια και κουίζ, το «Κάθε λέξη» (φωτογράφισε μια σελίδα και πάτησε όποια λέξη θέλεις), το «Πες το» για εξάσκηση στην προφορά, και σύνθεση πρότασης με σχόλια. Αν το Gadit έχει γίνει μέρος της καθημερινότητάς σου, αυτές είναι οι λειτουργίες που κάνουν τη διαφορά.","Έχεις παιδιά στο σπίτι; Το <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> καλύπτει έως 5 παιδιά, με τη Λειτουργία για παιδιά και πίνακα γονέων.","Έχουμε επίσης ένα πρόγραμμα συνεργατών: έναν προσωπικό σύνδεσμο που σου αποφέρει προμήθεια για κάθε πληρωμένη εγγραφή που έρχεται μέσα από αυτόν. Ένας εύκολος τρόπος να μοιραστείς κάτι που αγαπάς και να κερδίσεις στην πορεία."],"cta":"Γνώρισε το Individual","ps":"Υ.Γ. Πάντα χαιρόμαστε να ακούμε ποιες λειτουργίες θα ήθελες να δεις στο Gadit. Απλώς απάντησε σε αυτό το email."}},
  fa: {"greetNamed":"سلام {name}،","greetPlain":"سلام،","footerReason":"این ایمیل را دریافت می‌کنید چون در Gadit ثبت‌نام کرده‌اید.","unsubscribeLabel":"لغو اشتراک","welcome":{"subject":"به Gadit خوش آمدید","preheader":"یک فرهنگ لغت، یک مأموریت. فهمیدن کامل یک واژه. از اینجا شروع کنید.","paras":["به Gadit خوش آمدید، و از اینکه به ما پیوستید سپاسگزاریم.","Gadit فرهنگ لغتی است با یک مأموریت: فهمیدن کامل یک واژه. نه یک تعریف یک‌خطی، نه یک ترجمهٔ خشک. همهٔ معناها، اصطلاح‌ها، ریشهٔ واژه و شیوه‌هایی که مردم امروز واقعاً آن را به کار می‌برند.","حساب رایگان شما شامل روزی ۱۰ جست‌وجو و دفترچه‌ای تا ۳۰ واژه است.","وقتی واژه‌ای را کامل بفهمید، ایدهٔ پشت آن روشن می‌شود، و همراه با آن، شیوهٔ فکر کردن، یاد گرفتن و تصمیم گرفتن شما.","Gadit پلتفرمی زنده است که پیوسته رشد می‌کند. اگر در هر تعریف، مثال یا بخش دیگری اشتباهی دیدید، دکمهٔ گزارشی هست که ارزش زدن دارد. تیم ما همه چیز را می‌خواند و اصلاح می‌کند.","آماده‌اید شروع کنیم؟"],"cta":"نخستین واژه‌تان را جست‌وجو کنید","signOff":["با احترام،","تیم Gadit"]},"meanings":{"subject":"یک واژه، لایه‌هایی که ندیده بودید","preheader":"بیشتر ابزارها در تعریف می‌مانند. Gadit ادامه می‌دهد تا واژه در ذهن بماند.","exampleWord":"دست","paras":["واژهٔ «دست» را در نظر بگیرید، و ببینید چگونه یک واژه می‌تواند دنیایی کامل را باز کند.","دست عضوی از بدن است که با آن می‌گیریم و می‌نویسیم. دست یعنی سمت و جهت، مثل دست راست و دست چپ. دست یعنی یک دور بازی، مثل یک دست شطرنج یا یک دست ورق. دست یعنی یک مجموعهٔ کامل، مثل یک دست لباس یا یک دست مبل. و دست نشانهٔ قدرت و اختیار هم هست، وقتی می‌گوییم کار در دست اوست.","یک واژه، لایه‌هایی که در آن ندیده بودید، و هر کدام در دنیای خودش زندگی می‌کند.","در Gadit برای هر تعریف سه مثال واقعی پیدا می‌کنید. جمله‌هایی که واژه در آن‌ها در عمل کار می‌کند، نه در نظریه. این‌گونه نه‌تنها می‌بینید واژه چه می‌گوید، بلکه می‌بینید هنگام کاربرد چطور به گوش می‌رسد.","این قلب Gadit است. یک واژه، تا آخر، در همهٔ تعریف‌هایش.","پیشنهاد می‌کنیم «دست» را جست‌وجو کنید، و شاید واژهٔ دیگری که فکر می‌کنید کاملاً می‌شناسید. شاید شگفت‌زده شوید."],"cta":"«دست» را جست‌وجو کنید و همهٔ چهره‌هایش را ببینید","ps":"پی‌نوشت: وقتی به معنای غافلگیرکننده‌ای رسیدید، کنارش دکمهٔ اشتراک‌گذاری هست. ارزش دارد آن را برای کسی بفرستید که قدرش را می‌داند."},"etymology":{"subject":"یک واژه واقعاً از کجا می‌آید","preheader":"هر واژه گذشته‌ای دارد، و گاهی همان گذشته اکنون را توضیح می‌دهد.","exampleWord":"دست","paras":["به بخش محبوب ما رسیدیم. اینکه واژه از کجا می‌آید.","هر واژه گذشته‌ای دارد. و گاهی این گذشته اکنون را بهتر از هر تعریفی توضیح می‌دهد.","«دست» نمونهٔ زیبایی است. این واژه از فارسی میانه «دست» و از فارسی باستان «دَستَ» به ما رسیده است، و در اوستایی به شکل «زَستَ» آمده است. خویشاوند آن در سانسکریت «هَستَ» است. در همهٔ این زبان‌ها معنای اصلی یکی است: دست، همان عضو بدن.","از همین واژه، واژه‌های زیادی در فارسی ساخته شده است: دستکش، دستمال، دستبند، دستگاه، و دسته که هم دستگیرهٔ چیزی است و هم گروهی از کسان. و از دستی که چیزی را می‌گیرد، معناهای انتزاعی‌تر رشد کرد: قدرت و اختیار، وقتی کاری در دست کسی است، و نقش داشتن، وقتی کسی در کاری دست دارد.","سفری کامل در یک واژه. از ملموس‌ترین چیز، دستی که لمس می‌کند، تا چیزی نادیدنی مثل قدرت و اختیار. همه در واژه‌ای که هزاران سال با ما مانده است.","وقتی این را بدانید، نه‌تنها واژه را بهتر به خاطر می‌سپارید، بلکه می‌فهمید چرا همهٔ معناهایش به هم پیوسته‌اند. آن‌ها تصادفی کنار هم نیستند.","در Gadit، زیر تعریف‌های هر واژه، بخشی هست که ریشهٔ آن را توضیح می‌دهد. پیشینهٔ تاریخی، اینکه از کجا آمده است. همین است که فرهنگ لغت را از فهرستی از تعریف‌ها به یک داستان تبدیل می‌کند."],"cta":"ریشهٔ واژهٔ بعدی را کشف کنید"},"visual":{"subject":"واژه‌ای هم‌قد کودک","preheader":"حالت کودکان: هر واژه به زبان یک کودک، بی‌آنکه عمقش را از دست بدهد.","paras":["یکی از رایج‌ترین درخواست‌هایی که به ما رسید ساده بود. کودک می‌پرسد معنای یک واژه چیست، و تعریف رسمی برایش زیادی پیچیده است.","برای همین Gadit حالت کودکان دارد. آن را روشن کنید، و هر واژه به زبان کودکی پنج تا ده ساله توضیح داده می‌شود. همان عمق، بدون واژه‌های سخت.","واژهٔ «دست» را در نظر بگیرید. در حالت معمولی در چند لایه توضیح داده می‌شود. در حالت کودکان چیزی می‌شود که کودک فوراً می‌فهمد، مثلاً اینکه یک دست بازی یعنی یک بار بازی از اول تا آخر، و یک دست لباس یعنی همهٔ تکه‌هایی که با هم پوشیده می‌شوند.","و این فقط برای کودکان نیست. گاهی وقتی واژه‌ای واقعاً سخت است، توضیح ساده دقیقاً همان چیزی است که بزرگ‌ترها هم برای فهمیدنش لازم دارند.","در کنار حالت کودکان، Gadit برای هر معنا یک تصویر هم نشان می‌دهد، تا کودک بتواند واژه را هم بخواند و هم ببیند. فهم زودتر می‌رسد و بیشتر می‌ماند.","حالت کودکان بخشی از طرح Family است که برای خانواده‌های بچه‌دار ساخته شده است. تصویر برای هر معنا در طرح Individual هم هست.","اگر کودکی نزدیک شماست، یک دقیقه کنارش بنشینید، حالت کودکان را روشن کنید، با هم واژه‌ای را جست‌وجو کنید و تصویرش را ببینید. لحظهٔ فهمیدنِ بی‌زحمت این‌گونه است."],"cta":"حالت کودکان را ببینید"},"summary":{"subject":"دو هفته، یک واژه","preheader":"مسیری که آمدیم، و دو راه برای ادامه از همین‌جا.","paras":["در دو هفتهٔ گذشته با چهره‌های مختلف یک واژه آشنا شدیم. همهٔ معناهایش، و تاریخش.","در کنار آن، با ویژگی‌هایی آشنا شدیم که Gadit را ابزاری برای فهم عمیق‌تر می‌کنند: حالت کودکان، و یک تصویر برای هر معنا.","برخی از این ویژگی‌ها برای همهٔ کاربران باز است. حساب رایگان شامل روزی ۱۰ جست‌وجو و دفترچه‌ای تا ۳۰ واژه است.","بقیه با Individual باز می‌شوند: جست‌وجوی نامحدود، یک تصویر برای هر معنا، دفترچه‌ای که هر واژه را با تمرین هوشمند نگه می‌دارد، بازی‌ها و آزمونک‌ها، «هر واژه» (از یک صفحه عکس بگیرید و روی هر واژه بزنید)، «بگو» برای تمرین تلفظ، و ساختن یک جمله با بازخورد. اگر Gadit بخشی از روز شما شده است، همین ویژگی‌ها تفاوت را می‌سازند.","در خانه بچه دارید؟ طرح <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> تا ۵ کودک را در بر می‌گیرد، با حالت کودکان و صفحهٔ والدین.","و یک برنامهٔ همکاری هم داریم: پیوندی شخصی که از هر ثبت‌نام پولی که از طریق آن بیاید، به شما پورسانت می‌دهد. راهی راحت برای به اشتراک گذاشتن چیزی که دوستش دارید، و کسب درآمد در همین مسیر."],"cta":"با Individual آشنا شوید","ps":"پی‌نوشت: همیشه خوشحال می‌شویم بشنویم دوست دارید چه قابلیت‌هایی را در Gadit ببینید. کافی است به همین ایمیل پاسخ دهید."}},
  fil: {"greetNamed":"Kumusta {name},","greetPlain":"Kumusta,","footerReason":"Natanggap mo ang email na ito dahil nag-sign up ka sa Gadit.","unsubscribeLabel":"Mag-unsubscribe","welcome":{"subject":"Maligayang pagdating sa Gadit","preheader":"Isang diksyunaryo, isang misyon. Unawain ang isang salita hanggang dulo. Ganito magsimula.","paras":["Maligayang pagdating sa Gadit, at salamat sa pagsali.","Ang Gadit ay isang diksyunaryo na may iisang misyon: unawain ang isang salita hanggang dulo. Hindi isang linyang depinisyon, hindi isang tuyong salin. Lahat ng kahulugan, ang mga idyoma, ang pinagmulan ng salita, at kung paano talaga ito ginagamit ng mga tao ngayon.","Kasama sa libre mong account ang 10 paghahanap kada araw at isang kwaderno na hanggang 30 salita.","Kapag lubos mong naunawaan ang isang salita, lumilinaw ang ideya sa likod nito, at kasama nito ang paraan ng pag-iisip mo, pag-aaral mo at pagpapasya mo.","Ang Gadit ay isang buhay na plataporma na patuloy na lumalago. Kung may makita kang mali sa kahit anong depinisyon, halimbawa o ibang bahagi, may report button na sulit pindutin. Binabasa ng team namin ang lahat at inaayos ito.","Handa ka na bang magsimula?"],"cta":"Hanapin ang una mong salita","signOff":["Hanggang sa muli,","Ang team ng Gadit"]},"meanings":{"subject":"Isang salita, mga layer na hindi mo pa napapansin","preheader":"Karamihan ng tool ay humihinto sa depinisyon. Tuloy-tuloy ang Gadit hanggang tumatak ito.","exampleWord":"bayan","paras":["Kunin natin ang salitang \"bayan\", at tingnan kung paano nakapagbubukas ng isang buong mundo ang iisang salita.","Ang bayan ay isang lugar na tinitirhan ng mga tao, isang bayan sa probinsya na may sariling mayor. Ito rin ang sentro ng lugar na iyon, kaya \"pupunta sa bayan\" ang sinasabi kapag mamamalengke. Ito ang buong bansa, ang Inang Bayan. Ito ang mga tao mismo, gaya ng \"paglilingkod sa bayan\". At ito ang lugar na pinagmulan mo, ang sarili mong bayan na lagi mong binabalikan.","Isang salita, mga layer na hindi mo pa napapansin, at bawat isa ay nabubuhay sa sarili nitong mundo.","Sa Gadit makakakita ka ng tatlong totoong halimbawa para sa bawat depinisyon. Mga pangungusap kung saan gumagana ang salita sa totoong buhay, hindi lang sa teorya. Sa ganoon, nakikita mo hindi lang kung ano ang ibig sabihin ng salita, kundi kung paano ito tumutunog kapag ginagamit.","Ito ang puso ng Gadit. Isang salita, hanggang dulo, sa lahat ng depinisyon nito.","Iminumungkahi naming hanapin ang \"bayan\", at baka isa pang salitang akala mo ay kilala mo na. Baka magulat ka."],"cta":"Hanapin ang \"bayan\" at tingnan ang lahat ng mukha nito","ps":"P.S. Kapag nakakita ka ng nakakagulat na kahulugan, may share button sa tabi nito. Sulit itong ipadala sa taong maa-appreciate ito."},"etymology":{"subject":"Saan talaga nagmumula ang isang salita","preheader":"Bawat salita ay may nakaraan, at minsan ipinapaliwanag nito ang kasalukuyan.","exampleWord":"bayan","paras":["Narating na natin ang paborito naming bahagi. Kung saan nagmula ang salita.","Bawat salita ay may nakaraan. At minsan, mas naipapaliwanag ng nakaraang iyon ang kasalukuyan kaysa sa kahit anong depinisyon.","Magandang halimbawa ang bayan. Napakatanda ng salitang ito. Galing ito sa salitang ginamit ng mga ninuno ng mga wikang Austronesian, na muling binuo ng mga linggwista bilang *banua. Ang ibig sabihin nito ay lupang tinitirhan ng mga tao, isang pamayanan.","Kaya may mga kamag-anak ang bayan sa malalayong lugar sa karagatan. Sa Malay, ang benua ay kontinente. Sa wikang Māori ng New Zealand, ang whenua ay lupa. Sa Fiji, ang vanua ay ang lupa at ang mga taong nakatira rito. Iisang salita, na dinala ng mga manlalayag sa dagat sa loob ng libu-libong taon.","Mula sa bayan din tumubo ang mga salitang kilala natin. Ang kababayan, taong galing sa iisang bayan. Ang mamamayan, taong kabilang sa bayan.","Isang buong paglalakbay sa iisang salita. Mula sa lupang tinatapakan, hanggang sa mga taong magkakasama rito, at sa isang buong bansa. Lahat sa iisang salita na kasama natin sa loob ng libu-libong taon.","Kapag alam mo ito, hindi lang mas madali mong maaalala ang salita. Naiintindihan mo rin kung bakit magkakaugnay ang lahat ng kahulugan nito. Hindi sila nagkasama nang nagkataon lang.","Sa Gadit, sa ilalim ng mga depinisyon ng bawat salita, may seksyong nagpapaliwanag ng pinagmulan nito. Ang kasaysayan, kung saan ito nanggaling. Iyon ang nagpapabago sa isang diksyunaryo mula sa listahan ng mga depinisyon tungo sa isang kuwento."],"cta":"Tuklasin ang pinagmulan ng susunod na salita"},"visual":{"subject":"Isang salita na kapantay ng mata","preheader":"Kids Mode: bawat salita ipinaliliwanag sa wika ng bata, nang hindi nawawala ang lalim.","paras":["Isa sa mga pinakamadalas na hiling na natanggap namin ay simple. Nagtatanong ang isang bata kung ano ang ibig sabihin ng isang salita, at masyadong komplikado para sa kanya ang opisyal na depinisyon.","Kaya may Kids Mode ang Gadit. I-on ito, at bawat salita ay ipinapaliwanag sa wika ng batang lima hanggang sampung taong gulang. Parehong lalim, walang malalaking salita.","Kunin ang \"bayan\". Sa regular na mode, ipinapaliwanag ito sa ilang layer. Sa Kids Mode, nagiging bagay ito na agad naiintindihan ng bata, gaya ng lugar kung saan nakatira ka, ang pamilya mo at ang mga kapitbahay mo.","At hindi lang ito para sa mga bata. Minsan, kapag talagang mahirap ang isang salita, ang simpleng paliwanag ang mismong kailangan din ng matatanda para maunawaan ito.","Kasabay ng Kids Mode, nagpapakita rin ang Gadit ng larawan para sa bawat kahulugan, para makita rin ng bata ang salita at hindi lang mabasa. Mas mabilis dumarating ang pag-unawa at mas tumatagal ito.","Bahagi ang Kids Mode ng Family plan, na ginawa para sa mga pamilyang may mga anak. Kasama rin ang larawan para sa bawat kahulugan sa Individual plan.","Kung may bata sa paligid, umupo kayo nang sandali, i-on ang Kids Mode, maghanap ng salita nang magkasama at tingnan ang larawan nito. Ganito ang itsura ng sandali ng madaling pag-unawa."],"cta":"Tingnan ang Kids Mode"},"summary":{"subject":"Dalawang linggo, isang salita","preheader":"Ang paglalakbay, at dalawang paraan para magpatuloy mula rito.","paras":["Sa nakalipas na dalawang linggo, nakilala natin ang iba't ibang panig ng isang salita. Lahat ng kahulugan nito, at ang kasaysayan nito.","Kasabay nito, nakilala natin ang mga feature na ginagawang tool ang Gadit para sa mas malalim na pag-unawa: ang Kids Mode, at isang larawan para sa bawat kahulugan.","Bukas sa bawat user ang ilan sa mga feature na ito. Kasama sa libreng account ang 10 paghahanap kada araw at isang kwaderno na hanggang 30 salita.","Nabubuksan ang iba gamit ang Individual: walang limitasyong paghahanap, isang larawan para sa bawat kahulugan, isang kwadernong nagse-save ng bawat salita na may smart practice, mga laro at quiz, Bawat Salita (kunan ng litrato ang isang pahina at i-tap ang kahit anong salita), Sabihin mo para sa pagsasanay sa pagbigkas, at pagbuo ng pangungusap na may feedback. Kung naging bahagi na ng araw-araw mo ang Gadit, ito ang mga feature na gumagawa ng pagkakaiba.","May mga anak sa bahay? Ang <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> plan ay para sa hanggang 5 bata, may Kids Mode at dashboard ng magulang.","At may partner program din kami: isang personal na link na nagbibigay sa iyo ng komisyon sa bawat bayad na sign-up na dumaan dito. Isang madaling paraan para ibahagi ang isang bagay na gusto mo, at kumita habang ginagawa ito."],"cta":"Kilalanin ang Individual","ps":"P.S. Lagi naming ikinatutuwang marinig kung anong mga feature ang gusto mong makita sa Gadit. Mag-reply ka lang sa email na ito."}},
  hi: {"greetNamed":"नमस्ते {name},","greetPlain":"नमस्ते,","footerReason":"आपको यह ईमेल इसलिए मिला है क्योंकि आपने Gadit पर साइन अप किया है।","unsubscribeLabel":"सदस्यता रद्द करें","welcome":{"subject":"Gadit में आपका स्वागत है","preheader":"एक शब्दकोश, एक मिशन। किसी शब्द को पूरी तरह समझना। ऐसे शुरू करें।","paras":["Gadit में आपका स्वागत है, और जुड़ने के लिए धन्यवाद।","Gadit एक ऐसा शब्दकोश है जिसका एक ही मिशन है: किसी शब्द को पूरी तरह समझना। एक लाइन की परिभाषा नहीं, सूखा अनुवाद नहीं। सभी अर्थ, मुहावरे, शब्द की उत्पत्ति, और वे तरीके जिनसे लोग आज सच में उसका इस्तेमाल करते हैं।","आपके मुफ़्त अकाउंट में रोज़ 10 खोजें और 30 शब्दों तक की नोटबुक मिलती है।","जब आप किसी शब्द को पूरी तरह समझ लेते हैं, तो उसके पीछे का विचार साफ़ हो जाता है, और उसके साथ आपके सोचने, सीखने और फ़ैसले लेने का तरीका भी।","Gadit एक जीवंत प्लेटफ़ॉर्म है जो लगातार बढ़ रहा है। अगर आपको किसी परिभाषा, उदाहरण या किसी और हिस्से में कोई गलती दिखे, तो रिपोर्ट का बटन ज़रूर दबाएँ। हमारी टीम सब कुछ पढ़ती है और उसे ठीक करती है।","शुरू करने के लिए तैयार हैं?"],"cta":"अपना पहला शब्द खोजें","signOff":["शुभकामनाओं सहित,","Gadit टीम"]},"meanings":{"subject":"एक शब्द, कई परतें जो आपने अब तक नहीं देखीं","preheader":"ज़्यादातर टूल परिभाषा पर रुक जाते हैं। Gadit तब तक चलता है जब तक बात याद न रह जाए।","exampleWord":"रस","paras":["“रस” शब्द को लीजिए, और देखिए कि एक शब्द कैसे पूरी दुनिया खोल सकता है।","रस फल या पौधे से निकला तरल है, आम का रस, गन्ने का रस। रस स्वाद है, मीठा, खट्टा, कड़वा। रस आनंद और रुचि है, जैसे जब हम कहते हैं कि बातों में रस आ रहा है। रस किसी चीज़ का सार है, जीवन का रस। और काव्य और नाटक में रस वह भाव है जो पाठक या दर्शक के मन में जागता है, जैसे शृंगार, करुण या हास्य रस।","एक शब्द, कई परतें जो आपने उसमें नहीं देखी थीं, हर एक अपनी अलग दुनिया में।","Gadit में आपको हर परिभाषा के लिए तीन असली उदाहरण मिलते हैं। ऐसे वाक्य जिनमें शब्द व्यवहार में काम करता है, सिर्फ़ सिद्धांत में नहीं। इस तरह आप सिर्फ़ यह नहीं देखते कि शब्द क्या कहता है, बल्कि यह भी कि इस्तेमाल में वह कैसा सुनाई देता है।","यही Gadit का दिल है। एक शब्द, शुरू से आख़िर तक, उसकी सभी परिभाषाओं के साथ।","हमारा सुझाव है कि आप “रस” खोजें, और शायद एक और शब्द भी जिसे आप सोचते हैं कि पहले से पूरी तरह समझते हैं। हो सकता है आप हैरान रह जाएँ।"],"cta":"“रस” खोजें और उसके सभी रूप देखें","ps":"पुनश्च: जब आपको कोई चौंकाने वाला अर्थ मिले, तो उसके पास एक शेयर बटन है। किसी ऐसे व्यक्ति को भेजने लायक जो इसकी कद्र करे।"},"etymology":{"subject":"एक शब्द असल में कहाँ से आता है","preheader":"हर शब्द का एक अतीत होता है, और कभी-कभी वह वर्तमान को समझा देता है।","exampleWord":"रस","paras":["अब हम अपने पसंदीदा हिस्से पर आ गए हैं। शब्द कहाँ से आता है।","हर शब्द का एक अतीत होता है। और कभी-कभी वह अतीत वर्तमान को किसी भी परिभाषा से बेहतर समझाता है।","रस इसका एक सुंदर उदाहरण है। यह संस्कृत का शब्द है, और इसका सबसे पुराना अर्थ था पौधों का रस, फलों का रस, कोई भी तरल। यानी एक बहुत ठोस चीज़, जिसे छुआ और चखा जा सकता है। रसीला, सरस और नीरस जैसे शब्दों में आज भी यही शब्द छिपा है।","तरल से अर्थ बढ़कर स्वाद तक पहुँचा, क्योंकि रस को चखा जाता है। स्वाद से आनंद तक, और आनंद से सार तक। फिर भरत मुनि के नाट्यशास्त्र ने रस को कला के केंद्र में रख दिया: वह भाव जिसका “स्वाद” दर्शक नाटक या कविता से लेता है।","एक शब्द में पूरी यात्रा। सबसे ठोस चीज़, पौधे के रस, से सबसे अमूर्त चीज़ तक, कला से जागने वाले भाव तक। सब एक ऐसे शब्द में जो हज़ारों साल से हमारे साथ है।","यह जान लेने के बाद आप शब्द को सिर्फ़ बेहतर याद नहीं रखते। आप यह भी समझते हैं कि उसके सभी अर्थ आपस में क्यों जुड़े हैं। वे संयोग से साथ नहीं रहते।","Gadit में हर शब्द की परिभाषाओं के नीचे एक हिस्सा होता है जो उसकी उत्पत्ति समझाता है। ऐतिहासिक पृष्ठभूमि, वह कहाँ से आया। यही एक शब्दकोश को परिभाषाओं की सूची से एक कहानी में बदल देता है।"],"cta":"अगले शब्द की उत्पत्ति जानें"},"visual":{"subject":"बच्चे की नज़र से एक शब्द","preheader":"Kids Mode: हर शब्द बच्चे की भाषा में समझाया हुआ, गहराई खोए बिना।","paras":["हमें मिलने वाले सबसे आम अनुरोधों में से एक बहुत सीधा था। बच्चा पूछता है कि किसी शब्द का क्या मतलब है, और आधिकारिक परिभाषा उसके लिए बहुत मुश्किल होती है।","इसीलिए Gadit में Kids Mode है। इसे चालू करें, और हर शब्द पाँच से दस साल के बच्चे की भाषा में समझाया जाता है। वही गहराई, बिना भारी शब्दों के।","“गुरुत्वाकर्षण” को लीजिए। सामान्य मोड में इसे भौतिकी और द्रव्यमान के आकर्षण से समझाया जाता है। Kids Mode में यह कुछ ऐसा बन जाता है जिसे बच्चा तुरंत समझ ले: एक अदृश्य खिंचाव जो हर चीज़ को ज़मीन की ओर खींचता है, इसीलिए ऊपर उछाली गई गेंद हमेशा नीचे आती है।","और यह सिर्फ़ बच्चों के लिए नहीं है। कभी-कभी, जब कोई शब्द सच में कठिन होता है, तो आसान व्याख्या ही वह चीज़ होती है जिससे बड़े भी उसे समझ पाते हैं।","Kids Mode के साथ Gadit हर अर्थ के लिए एक तस्वीर भी दिखाता है, ताकि बच्चा शब्द को पढ़ने के साथ-साथ देख भी सके। समझ जल्दी आती है और देर तक टिकती है।","Kids Mode, Family प्लान का हिस्सा है, जो बच्चों वाले परिवारों के लिए बना है। हर अर्थ के लिए तस्वीर Individual प्लान में भी मिलती है।","अगर आसपास कोई बच्चा है, तो एक मिनट उसके साथ बैठें, Kids Mode चालू करें, साथ मिलकर कोई शब्द खोजें और उसकी तस्वीर देखें। बिना मेहनत के समझ आने का पल ऐसा ही दिखता है।"],"cta":"Kids Mode देखें"},"summary":{"subject":"दो हफ़्ते, एक शब्द","preheader":"अब तक का सफ़र, और यहाँ से आगे बढ़ने के दो रास्ते।","paras":["पिछले दो हफ़्तों में हमने एक शब्द के अलग-अलग पहलुओं को जाना। उसके सभी अर्थ, और उसका इतिहास।","इसके साथ हमने उन फ़ीचर्स को भी जाना जो Gadit को गहरी समझ का टूल बनाते हैं: Kids Mode, और हर अर्थ के लिए एक तस्वीर।","इनमें से कुछ फ़ीचर हर यूज़र के लिए खुले हैं। मुफ़्त अकाउंट में रोज़ 10 खोजें और 30 शब्दों तक की नोटबुक मिलती है।","बाकी Individual से खुलते हैं: असीमित खोजें, हर अर्थ के लिए एक तस्वीर, एक नोटबुक जो हर शब्द को स्मार्ट अभ्यास के साथ सेव करती है, गेम और क्विज़, “हर शब्द” (पन्ने की फ़ोटो लें और किसी भी शब्द पर टैप करें), उच्चारण अभ्यास के लिए Say it, और फ़ीडबैक के साथ वाक्य बनाना। अगर Gadit आपकी रोज़ की आदत बन गया है, तो यही फ़ीचर फ़र्क लाते हैं।","घर में बच्चे हैं? <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> प्लान में 5 बच्चों तक शामिल हैं, Kids Mode और पैरेंट बोर्ड के साथ।","और हमारा एक पार्टनर प्रोग्राम भी है: एक निजी लिंक, जिससे आने वाले हर पेड साइन अप पर आपको कमीशन मिलता है। अपनी पसंद की चीज़ शेयर करने और साथ में कमाने का एक आसान तरीका।"],"cta":"Individual के बारे में जानें","ps":"पुनश्च: हमें यह जानना हमेशा अच्छा लगता है कि आप Gadit में कौन से फ़ीचर देखना चाहेंगे। बस इस ईमेल का जवाब दीजिए।"}},
  hu: {"greetNamed":"Szia {name},","greetPlain":"Szia,","footerReason":"Azért kapod ezt az e-mailt, mert regisztráltál a Gaditon.","unsubscribeLabel":"Leiratkozás","welcome":{"subject":"Üdvözlünk a Gaditon","preheader":"Egy szótár, egy küldetés. Egy szót egészen a végéig megérteni. Így kezdj hozzá.","paras":["Üdvözlünk a Gaditon, és köszönjük, hogy csatlakoztál.","A Gadit egy szótár egyetlen küldetéssel: egy szót egészen a végéig megérteni. Nem egysoros meghatározás, nem száraz fordítás. Minden jelentés, a szólások, a szó eredete, és az, ahogyan az emberek ma valóban használják.","Az ingyenes fiókod napi 10 keresést és egy legfeljebb 30 szavas füzetet tartalmaz.","Ha egy szót teljesen megértesz, a mögötte álló gondolat is világossá válik, és vele együtt az is, ahogyan gondolkodsz, tanulsz és döntesz.","A Gadit élő platform, amely folyamatosan fejlődik. Ha hibát találsz egy meghatározásban, egy példában vagy bárhol máshol, érdemes megnyomni a hibajelentés gombot. A csapatunk mindent elolvas és kijavít.","Kezdhetjük?"],"cta":"Keresd meg az első szavadat","signOff":["Barátsággal,","A Gadit csapata"]},"meanings":{"subject":"Egy szó, rétegek, amelyeket még nem láttál","preheader":"A legtöbb eszköz megáll a meghatározásnál. A Gadit addig megy, amíg meg nem marad.","exampleWord":"levél","paras":["Vegyük a levél szót, és nézd meg, hogyan nyithat meg egyetlen szó egy egész világot.","A levél a fa zöld levele, amely ősszel lehullik. A levél az is, amit megírsz és elküldesz valakinek, papíron vagy e-mailben. Egy levél tabletta a gyógyszeres doboz egy csíkja. A leveles tészta vékony rétegekből áll, ebből készül a leveles pogácsa. A levéltár pedig az a hely, ahol a régi iratokat őrzik.","Egy szó, rétegek, amelyeket eddig nem láttál benne, és mindegyik a saját világában él.","A Gaditban minden meghatározáshoz három valódi példát találsz. Mondatokat, amelyekben a szó a gyakorlatban működik, nem csak elméletben. Így nemcsak azt látod, mit jelent a szó, hanem azt is, hogyan hangzik használat közben.","Ez a Gadit szíve. Egy szó, végig, az összes jelentésén át.","Javasoljuk, hogy keress rá a levél szóra, és talán egy másikra is, amelyről azt hiszed, már teljesen érted. Lehet, hogy meglepődsz."],"cta":"Keresd meg a levél szót","ps":"Ui. Ha meglepő jelentésre bukkansz, mellette találsz egy megosztás gombot. Érdemes elküldeni valakinek, aki értékelni fogja."},"etymology":{"subject":"Honnan jön valójában egy szó","preheader":"Minden szónak van múltja, és néha ez magyarázza meg a jelenét.","exampleWord":"levél","paras":["Elérkeztünk a kedvenc részünkhöz. Ahhoz, hogy honnan jön a szó.","Minden szónak van múltja. És ez a múlt néha jobban megmagyarázza a jelent, mint bármilyen meghatározás.","A levél szép példa erre. Ősi, finnugor eredetű szavunk, rokona a finn lehti, amely szintén a fa levelét jelenti. A finnben ráadásul a lehti újságot és folyóiratot is jelent.","A fa levelétől vezetett az út a lapig, a vékony, lapos dologig, amelyre írni lehet. A megírt lapból pedig az a levél lett, amelyet elküldünk valakinek. A leveles tészta és a levél tabletta is ugyanazt a képet őrzi: valami vékonyat és laposat, ami rétegekben vagy lapokban jön.","Egy egész utazás egyetlen szóban. A fa ágán zöldellő levéltől a postaládában váró levélig. Mindez egy szóban, amely évezredek óta velünk van.","Ha ezt tudod, nemcsak jobban emlékszel a szóra. Azt is megérted, miért kapcsolódik össze minden jelentése. Nem véletlenül élnek együtt.","A Gaditban minden szó meghatározásai alatt találsz egy részt, amely elmagyarázza az eredetét. A történeti hátteret, azt, hogy honnan jött. Ettől lesz a szótár a meghatározások listája helyett egy történet."],"cta":"Fedezd fel a következő szó eredetét"},"visual":{"subject":"Egy szó szemmagasságban","preheader":"Gyerek mód: minden szó egy gyerek nyelvén elmagyarázva, a mélységből semmit sem veszítve.","paras":["Az egyik leggyakoribb kérés, amelyet kaptunk, egyszerű volt. Egy gyerek megkérdezi, mit jelent egy szó, és a hivatalos meghatározás túl bonyolult neki.","Ezért van a Gaditban Gyerek mód. Kapcsold be, és minden szót egy öt és tíz év közötti gyerek nyelvén magyarázunk el. Ugyanaz a mélység, nehéz szavak nélkül.","Vegyük a gravitáció szót. Normál módban fizika és képletek. Gyerek módban valami, amit egy gyerek azonnal megért: az, ami miatt a labda mindig visszaesik, amikor feldobod, és ami a lábunkat a földön tartja.","És ez nem csak gyerekeknek szól. Néha, amikor egy szó tényleg nehéz, a felnőtteknek is pont az egyszerű magyarázat kell ahhoz, hogy megértsék.","A Gyerek mód mellett a Gadit minden jelentéshez képet is mutat, így a gyerek nemcsak olvassa, hanem látja is a szót. A megértés gyorsabban jön, és tovább marad.","A Gyerek mód a Family csomag része, amelyet gyerekes családoknak terveztünk. A kép minden jelentéshez az Individual csomagban is jár.","Ha van a közeledben egy gyerek, ülj le vele egy percre, kapcsoljátok be a Gyerek módot, keressetek rá együtt egy szóra, és nézzétek meg a képét. Így néz ki az erőfeszítés nélküli megértés pillanata."],"cta":"Ismerd meg a Gyerek módot"},"summary":{"subject":"Két hét, egy szó","preheader":"Az út eddig, és két lehetőség a folytatásra.","paras":["Az elmúlt két hétben megismertük egy szó különböző oldalait. Minden jelentését és a történetét.","Emellett megismertük azokat a funkciókat, amelyektől a Gadit a mélyebb megértés eszköze lesz: a Gyerek módot és a képet minden jelentéshez.","Ezek közül néhány minden felhasználó számára nyitva áll. Az ingyenes fiók napi 10 keresést és egy legfeljebb 30 szavas füzetet tartalmaz.","A többit az Individual nyitja meg: korlátlan keresés, kép minden jelentéshez, füzet, amely minden szót elment, okos gyakorlással, játékok és kvízek, Minden szó (fotózz le egy oldalt, és koppints bármelyik szóra), Mondd ki a kiejtés gyakorlásához, és mondatírás visszajelzéssel. Ha a Gadit már a mindennapjaid része lett, ezek a funkciók jelentik a különbséget.","Gyerekek vannak otthon? A <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> csomag legfeljebb 5 gyereknek szól, Gyerek móddal és szülői irányítópulttal.","És van partnerprogramunk is: egy személyes link, amellyel jutalékot kapsz minden fizetős regisztráció után, amely rajta keresztül érkezik. Kényelmes módja annak, hogy megossz valamit, amit szeretsz, és közben keress is vele."],"cta":"Ismerd meg az Individual csomagot","ps":"Ui. Mindig örömmel halljuk, milyen funkciókat látnál szívesen a Gaditban. Csak válaszolj erre az e-mailre."}},
  id: {"greetNamed":"Halo {name},","greetPlain":"Halo,","footerReason":"Kamu menerima email ini karena kamu mendaftar di Gadit.","unsubscribeLabel":"Berhenti berlangganan","welcome":{"subject":"Selamat datang di Gadit","preheader":"Satu kamus, satu misi. Memahami sebuah kata sampai tuntas. Begini cara memulainya.","paras":["Selamat datang di Gadit, dan terima kasih sudah bergabung.","Gadit adalah kamus dengan satu misi: memahami sebuah kata sampai tuntas. Bukan definisi satu baris, bukan terjemahan yang kering. Semua artinya, ungkapannya, asal-usul katanya, dan cara orang benar-benar memakainya hari ini.","Akun gratismu mencakup 10 pencarian per hari dan buku catatan berisi hingga 30 kata.","Saat kamu memahami sebuah kata sepenuhnya, gagasan di baliknya menjadi jelas, dan bersamanya juga cara kamu berpikir, belajar, dan mengambil keputusan.","Gadit adalah platform hidup yang terus berkembang. Kalau kamu menemukan kesalahan di definisi, contoh, atau bagian lain, ada tombol laporkan yang layak ditekan. Tim kami membaca semuanya dan memperbaikinya.","Siap memulai?"],"cta":"Cari kata pertamamu","signOff":["Salam hangat,","Tim Gadit"]},"meanings":{"subject":"Satu kata, lapisan yang belum pernah kamu lihat","preheader":"Kebanyakan alat berhenti di definisi. Gadit terus berjalan sampai katanya melekat.","exampleWord":"kepala","paras":["Ambil kata kepala, dan lihat bagaimana satu kata bisa membuka satu dunia utuh.","Kepala adalah bagian tubuh di atas leher, tempat mata, telinga, dan otak kita. Kepala juga orang yang memimpin, seperti kepala sekolah, kepala desa, atau kepala keluarga. Kepala adalah bagian paling depan atau paling atas dari sesuatu, seperti kepala paku atau kepala surat. Kepala adalah pikiran, saat kita bilang pusing kepala atau tetap berkepala dingin. Orang yang keras kepala sulit diubah pendapatnya. Dan kepala bisa menjadi hitungan orang, seperti biaya per kepala.","Satu kata, lapisan yang belum kamu lihat di dalamnya, masing-masing hidup di dunianya sendiri.","Di Gadit kamu menemukan tiga contoh nyata untuk setiap definisi. Kalimat tempat kata itu bekerja dalam praktik, bukan dalam teori. Dengan begitu kamu melihat bukan hanya apa arti kata itu, tetapi juga bagaimana bunyinya saat dipakai.","Inilah inti Gadit. Satu kata, sampai tuntas, melalui semua definisinya.","Kami sarankan mencari kepala, dan mungkin juga kata lain yang menurutmu sudah kamu pahami. Kamu mungkin akan terkejut."],"cta":"Cari kata kepala dan lihat semua sisinya","ps":"P.S. Saat kamu menemukan arti yang mengejutkan, ada tombol bagikan di sebelahnya. Layak dikirim ke seseorang yang akan menghargainya."},"etymology":{"subject":"Dari mana sebuah kata benar-benar berasal","preheader":"Setiap kata punya masa lalu, dan kadang masa lalu itu menjelaskan masa kini.","exampleWord":"kepala","paras":["Kita sampai di bagian favorit kami. Dari mana kata itu berasal.","Setiap kata punya masa lalu. Dan kadang masa lalu itu menjelaskan masa kini lebih baik daripada definisi mana pun.","Kepala adalah contoh yang indah. Kata ini berasal dari bahasa Sanskerta kapāla, yang berarti tengkorak, tulang keras yang melindungi otak. Dalam bahasa Sanskerta, kata yang sama juga dipakai untuk mangkuk, karena bentuknya yang bulat dan cekung.","Dari tengkorak, bagian tubuh yang paling keras dan nyata, lahir arti kepala sebagai bagian atas tubuh. Lalu dari bagian yang berada paling atas itu tumbuh sesuatu yang lebih abstrak: orang yang berada di atas, yang memimpin. Kepala sekolah, kepala desa, kepala keluarga.","Satu perjalanan utuh dalam satu kata. Dari tulang yang bisa disentuh tangan, sampai gagasan tentang memimpin. Semuanya dalam satu kata yang sudah bersama kita selama berabad-abad.","Setelah tahu ini, kamu tidak hanya lebih mudah mengingat katanya. Kamu juga mengerti mengapa semua artinya saling terhubung. Arti-arti itu tidak hidup bersama secara kebetulan.","Di Gadit, di bawah definisi setiap kata, ada bagian yang menjelaskan asal-usulnya. Latar belakang sejarahnya, dari mana kata itu datang. Itulah yang mengubah kamus dari daftar definisi menjadi sebuah cerita."],"cta":"Temukan asal-usul kata berikutnya"},"visual":{"subject":"Kata yang sejajar dengan mata anak","preheader":"Mode Anak: setiap kata dijelaskan dalam bahasa anak, tanpa kehilangan kedalamannya.","paras":["Salah satu permintaan yang paling sering kami terima itu sederhana. Seorang anak bertanya apa arti sebuah kata, dan definisi resminya terlalu rumit untuknya.","Karena itulah Gadit punya Mode Anak. Nyalakan, dan setiap kata dijelaskan dalam bahasa anak berusia lima sampai sepuluh tahun. Kedalaman yang sama, tanpa kata-kata sulit.","Ambil kata kepala. Dalam mode biasa, kata ini dijelaskan dalam beberapa lapisan. Dalam Mode Anak, kata ini menjadi sesuatu yang langsung dipahami anak, seperti kepala sekolah: orang yang menjaga seluruh sekolah dan membantu semua orang di dalamnya.","Dan ini bukan hanya untuk anak-anak. Kadang, saat sebuah kata benar-benar sulit, penjelasan sederhana justru yang dibutuhkan orang dewasa untuk memahaminya juga.","Selain Mode Anak, Gadit juga menampilkan gambar untuk setiap arti, sehingga anak bisa melihat katanya, bukan hanya membacanya. Pemahaman datang lebih cepat dan bertahan lebih lama.","Mode Anak adalah bagian dari paket Family, yang dibuat untuk keluarga dengan anak. Gambar untuk setiap arti juga tersedia di paket Individual.","Kalau ada anak di dekatmu, duduklah bersamanya sebentar, nyalakan Mode Anak, cari satu kata bersama, dan lihat gambarnya. Seperti inilah momen memahami tanpa susah payah."],"cta":"Lihat Mode Anak"},"summary":{"subject":"Dua minggu, satu kata","preheader":"Perjalanannya, dan dua cara untuk melanjutkan dari sini.","paras":["Selama dua minggu terakhir, kita sudah mengenal berbagai sisi sebuah kata. Semua artinya, dan sejarahnya.","Bersamaan dengan itu, kita juga mengenal fitur yang menjadikan Gadit alat untuk pemahaman yang lebih dalam: Mode Anak, dan gambar untuk setiap arti.","Sebagian fitur ini terbuka untuk semua pengguna. Akun gratis mencakup 10 pencarian per hari dan buku catatan berisi hingga 30 kata.","Sisanya terbuka dengan Individual: pencarian tanpa batas, gambar untuk setiap arti, buku catatan yang menyimpan setiap kata dengan latihan pintar, permainan dan kuis, Setiap kata (foto sebuah halaman dan ketuk kata mana pun), Ucapkan untuk latihan pelafalan, dan menyusun kalimat lalu mendapat umpan balik. Kalau Gadit sudah menjadi bagian dari rutinitas harianmu, fitur-fitur inilah yang membuat perbedaan.","Ada anak di rumah? Paket <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> mencakup hingga 5 anak, dengan Mode Anak dan dasbor orang tua.","Kami juga punya program mitra: tautan pribadi yang memberimu komisi untuk setiap pendaftaran berbayar yang datang melaluinya. Cara yang mudah untuk berbagi sesuatu yang kamu sukai, sambil mendapat penghasilan."],"cta":"Kenali Individual","ps":"P.S. Kami selalu senang mendengar fitur apa yang ingin kamu lihat di Gadit. Cukup balas email ini."}},
  it: {"greetNamed":"Ciao {name},","greetPlain":"Ciao,","footerReason":"Ricevi questa email perché hai creato un account su Gadit.","unsubscribeLabel":"Annulla l'iscrizione","welcome":{"subject":"Ti diamo il benvenuto su Gadit","preheader":"Un dizionario, una missione. Capire una parola fino in fondo. Ecco come iniziare.","paras":["Ti diamo il benvenuto su Gadit, e grazie di essere qui.","Gadit è un dizionario con una sola missione: capire una parola fino in fondo. Non una definizione di una riga, non una traduzione secca. Tutti i significati, i modi di dire, l'origine della parola e il modo in cui la gente la usa davvero oggi.","Il tuo account gratuito include 10 ricerche al giorno e un quaderno fino a 30 parole.","Quando afferri una parola fino in fondo, l'idea che c'è dietro diventa chiara, e con lei il modo in cui pensi, impari e decidi.","Gadit è una piattaforma viva che continua a crescere. Se trovi un errore in una definizione, in un esempio o in qualsiasi altra parte, c'è un pulsante per segnalarlo che vale la pena premere. Il nostro team legge tutto e lo corregge.","Cominciamo?"],"cta":"Cerca la tua prima parola","signOff":["Un caro saluto,","Il team di Gadit"]},"meanings":{"subject":"Una parola, strati che non avevi visto","preheader":"La maggior parte degli strumenti si ferma alla definizione. Gadit va avanti finché la parola ti resta.","exampleWord":"penna","paras":["Prendi la parola penna, e guarda come una sola parola può aprire un mondo intero.","La penna è quella con cui scrivi, la penna a sfera o la stilografica. È anche la piuma di un uccello, come le penne del pavone. È la penna nera sul cappello degli alpini. Al plurale diventa un formato di pasta, le penne all'arrabbiata. E la penna è perfino chi scrive: una grande penna del giornalismo è un grande giornalista.","Una parola, strati che non avevi visto, ognuno nel suo mondo.","In Gadit trovi tre esempi reali per ogni definizione. Frasi in cui la parola funziona nella pratica, non in teoria. Così vedi non solo cosa dice la parola, ma come suona quando la si usa.","Questo è il cuore di Gadit. Una parola, fino in fondo, in tutte le sue definizioni.","Ti proponiamo di cercare penna, e magari un'altra parola che pensi di conoscere già bene. Potresti sorprenderti."],"cta":"Cerca la parola penna","ps":"P.S. Quando trovi un significato sorprendente, accanto c'è un pulsante per condividerlo. Vale la pena mandarlo a qualcuno che lo apprezzerà."},"etymology":{"subject":"Da dove viene davvero una parola","preheader":"Ogni parola ha un passato, e a volte spiega il presente.","exampleWord":"penna","paras":["Siamo arrivati alla nostra parte preferita. Da dove viene la parola.","Ogni parola ha un passato. E a volte quel passato spiega il presente meglio di qualsiasi definizione.","Penna è un bell'esempio. Viene dal latino penna, che significava piuma, e anche ala. Dalla stessa parola vengono pennuto, cioè un uccello, e pennacchio, il ciuffo di piume su un elmo o su un cappello.","Il salto alla scrittura è semplice e bellissimo. Per secoli si è scritto con una piuma d'oca, tagliata a punta e intinta nell'inchiostro. La piuma era lo strumento per scrivere, e il suo nome è rimasto anche quando sono arrivati il pennino di metallo, la stilografica e la penna a sfera. E la pasta? Le penne si chiamano così perché sono tagliate in diagonale, come la punta di una penna d'oca.","Un viaggio intero in una sola parola. Dalla piuma di un uccello allo strumento con cui scrivi, fino a chi scrive per mestiere.","Quando lo sai, non ricordi solo meglio la parola. Capisci anche perché tutti i suoi significati sono collegati. Non stanno insieme per caso.","In Gadit, sotto le definizioni di ogni parola, c'è una sezione che ne spiega l'origine. Lo sfondo storico, da dove viene. È questo che trasforma un dizionario da un elenco di definizioni in una storia."],"cta":"Scopri l'origine della prossima parola"},"visual":{"subject":"Una parola all'altezza degli occhi","preheader":"Modalità Bambini: ogni parola spiegata nella lingua di un bambino, senza perdere la profondità.","paras":["Una delle richieste più comuni che abbiamo ricevuto era semplice. Un bambino chiede cosa significa una parola, e la definizione ufficiale è troppo complicata per lui.","Per questo Gadit ha la Modalità Bambini. La attivi, e ogni parola viene spiegata nella lingua di un bambino dai cinque ai dieci anni. La stessa profondità, senza le parole difficili.","Prendi gravità. Nella modalità normale si parla di forze e di masse. Nella Modalità Bambini diventa qualcosa che un bambino capisce subito: è quello che fa cadere le cose per terra quando le lasci andare, e che ci tiene con i piedi per terra.","E non è solo per i bambini. A volte, quando una parola è davvero difficile, la spiegazione semplice è proprio quello che serve anche agli adulti per capirla.","Insieme alla Modalità Bambini, Gadit mostra anche un'immagine per ogni significato, così un bambino può vedere la parola oltre a leggerla. La comprensione arriva prima e dura di più.","La Modalità Bambini fa parte del piano Family, pensato per le famiglie con bambini. Un'immagine per ogni significato è inclusa anche nel piano Individual.","Se hai un bambino vicino, siediti con lui un minuto, attiva la Modalità Bambini, cercate insieme una parola e guardate la sua immagine. Ecco com'è il momento in cui si capisce senza fatica."],"cta":"Scopri la Modalità Bambini"},"summary":{"subject":"Due settimane, una parola","preheader":"Il percorso, e due modi per andare avanti da qui.","paras":["In queste due settimane abbiamo conosciuto i diversi lati di una parola. Tutti i suoi significati, e la sua storia.","Insieme a questo, abbiamo conosciuto le funzioni che fanno di Gadit uno strumento per capire più a fondo: la Modalità Bambini e un'immagine per ogni significato.","Alcune di queste funzioni sono aperte a tutti. Un account gratuito include 10 ricerche al giorno e un quaderno fino a 30 parole.","Le altre si sbloccano con Individual: ricerche illimitate, un'immagine per ogni significato, un quaderno che salva ogni parola con esercizi intelligenti, giochi e quiz, Ogni parola (fotografa una pagina e tocca qualsiasi parola), Dillo per esercitarti con la pronuncia, e la possibilità di scrivere una frase e ricevere un commento. Se Gadit è diventato parte della tua giornata, sono queste le funzioni che fanno la differenza.","Hai bambini in casa? Il piano <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> include fino a 5 bambini, con la Modalità Bambini e una bacheca per i genitori.","E abbiamo anche un programma partner: un link personale che ti fa guadagnare una commissione su ogni iscrizione a pagamento che arriva da lì. Un modo comodo per condividere qualcosa che ami, e guadagnare strada facendo."],"cta":"Scopri Individual","ps":"P.S. Ci fa sempre piacere sapere quali funzioni vorresti vedere in Gadit. Basta rispondere a questa email."}},
  ja: {"greetNamed":"{name}さん、こんにちは。","greetPlain":"こんにちは。","footerReason":"このメールは、Gaditにご登録いただいた方にお送りしています。","unsubscribeLabel":"配信停止","welcome":{"subject":"Gaditへようこそ","preheader":"ひとつの辞書、ひとつの使命。ひとつの単語を最後まで理解すること。始め方はこちらです。","paras":["Gaditへようこそ。ご参加いただき、ありがとうございます。","Gaditは、ひとつの使命をもった辞書です。それは、ひとつの単語を最後まで理解すること。一行だけの定義でも、そっけない翻訳でもありません。すべての意味、慣用句、単語の語源、そして今の人たちが実際にどう使っているかまでお届けします。","無料アカウントでは、1日10回まで検索でき、ノートには30語まで保存できます。","ひとつの単語を完全に理解すると、その奥にある考えがはっきり見えてきます。そしてそれとともに、考え方、学び方、決め方も変わっていきます。","Gaditは成長し続ける、生きたプラットフォームです。定義や例文、そのほかの部分に間違いを見つけたら、ぜひ報告ボタンを押してください。私たちのチームがすべてに目を通し、修正します。","さあ、始めましょうか？"],"cta":"最初の単語を調べる","signOff":["これからもよろしくお願いします。","Gaditチーム"]},"meanings":{"subject":"ひとつの単語に、まだ見ていない層がある","preheader":"多くのツールは定義で止まります。Gaditは、単語が身につくまで先へ進みます。","exampleWord":"手","paras":["「手」という単語を例に、ひとつの単語がどれほど広い世界を開くのか見てみましょう。","手は、まず体の一部です。手をつなぐ、手を洗う。でも、それだけではありません。「いい手がある」と言えば方法のこと、「打つ手がない」と言えば、もう打てる策がないこと。将棋や囲碁では、一つひとつの指し方や打ち方も手と呼びます。「人手が足りない」の手は働く人、「行く手」の手は進む方向、「この手の話」の手は種類です。","ひとつの単語に、これまで気づかなかった層があり、それぞれが自分の世界で生きています。","Gaditでは、どの定義にも実際の例文が3つついています。理屈ではなく、単語が実際に使われている文です。だから、単語が何を意味するかだけでなく、使われたときにどう響くのかもわかります。","これがGaditの核心です。ひとつの単語を、すべての定義にわたって、最後まで。","ぜひ「手」を調べてみてください。そのあとで、もう十分わかっていると思う別の単語も。きっと驚くはずです。"],"cta":"「手」を調べて、すべての顔を見る","ps":"追伸：意外な意味を見つけたら、そのすぐ横に共有ボタンがあります。面白がってくれそうな人に送ってみてください。"},"etymology":{"subject":"単語は本当はどこから来たのか","preheader":"どの単語にも過去があり、ときにその過去が今を説明してくれます。","exampleWord":"手","paras":["いよいよ、私たちのいちばん好きなところです。単語がどこから来たのか。","どの単語にも過去があります。そしてその過去が、どんな定義よりもうまく今を説明してくれることがあります。","「手」はそのよい例です。手は中国から入ってきた言葉ではなく、昔から日本で使われてきた和語です。古い日本語では、ほかの言葉と結びつくとき「た」という形になりました。その形は今も残っています。手綱（たづな）は手に持つ綱、手繰る（たぐる）は手で引き寄せること、そして掌（たなごころ）は「手の心」、つまり手のひらのことです。","体の一部としての手から、手でする仕事、そのやり方、そしてそれをする人へと、意味が広がっていきました。働き手、聞き手、書き手の「手」は、その人のことです。","ひとつの単語の中に、まるごと旅が詰まっています。いちばん身近な体の一部から、方法や人という目に見えない考えまで。そのすべてが、千年以上も私たちとともにある、ひとつの単語の中にあります。","これを知ると、単語を覚えやすくなるだけではありません。なぜすべての意味がつながっているのかもわかります。たまたま一緒にいるわけではないのです。","Gaditでは、どの単語でも定義の下に、その語源を説明するセクションがあります。歴史的な背景、どこから来たのか。それが、辞書を定義のリストから物語に変えてくれます。"],"cta":"次の単語の語源を見つける"},"visual":{"subject":"目の高さで見る単語","preheader":"キッズモード：どの単語も子どもの言葉で、深さはそのままに説明します。","paras":["これまでいちばん多くいただいたご要望のひとつは、とてもシンプルなものでした。子どもが単語の意味をたずねても、正式な定義は子どもには難しすぎる、というものです。","だからGaditにはキッズモードがあります。オンにすると、どの単語も5歳から10歳の子どもの言葉で説明されます。深さはそのまま、難しい言葉はなしで。","たとえば「重力」。ふつうのモードでは物理や公式の話になります。キッズモードでは、子どもがすぐにわかるものになります。ボールを上に投げても必ず下に落ちてくるのはなぜか、私たちが地面にちゃんと立っていられるのはなぜか、その答えです。","そして、これは子どもだけのものではありません。本当に難しい単語のときは、大人にとっても、やさしい説明こそが理解に必要なものだったりします。","キッズモードに加えて、Gaditは意味ごとに画像も表示します。子どもは単語を読むだけでなく、目で見ることもできます。理解が早く訪れ、長く残ります。","キッズモードは、お子さまのいるご家庭のためのFamilyプランに含まれます。意味ごとの画像は、Individualプランにもついています。","近くにお子さまがいたら、少しだけ一緒に座って、キッズモードをオンにし、一緒に単語を調べて、その画像を見てみてください。無理なく理解できる瞬間とは、こういうものです。"],"cta":"キッズモードを見てみる"},"summary":{"subject":"2週間、ひとつの単語","preheader":"ここまでの道のりと、ここから先の2つの道。","paras":["この2週間で、ひとつの単語のさまざまな面を知ってきました。すべての意味、そしてその歴史。","それと同時に、Gaditを深い理解のための道具にしている機能も知ってきました。キッズモードと、意味ごとの画像です。","これらの機能の一部は、すべての方に開かれています。無料アカウントでは、1日10回まで検索でき、ノートには30語まで保存できます。","そのほかはIndividualで使えるようになります。検索し放題、意味ごとの画像、すべての単語を保存してスマート練習ができるノート、ゲームとクイズ、「すべての単語」（ページを撮影して、どの単語でもタップ）、発音練習ができる「言ってみて」、そして文を作ってフィードバックをもらう機能です。Gaditが毎日の習慣になっているなら、違いを生むのはこれらの機能です。","お子さまがいるご家庭ですか？<a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a>プランなら子ども最大5人まで使え、キッズモードと保護者ボードもついています。","パートナープログラムもあります。あなた専用のリンクから有料登録があるたびに、紹介料をお支払いします。好きなものをシェアしながら報酬も得られる、便利な方法です。"],"cta":"Individualを見てみる","ps":"追伸：Gadit にあったらいいなと思う機能があれば、いつでもぜひお聞かせください。このメールに返信していただくだけで大丈夫です。"}},
  ko: {"greetNamed":"{name}님, 안녕하세요.","greetPlain":"안녕하세요.","footerReason":"Gadit에 가입하셔서 이 이메일을 받으셨어요.","unsubscribeLabel":"수신 거부","welcome":{"subject":"Gadit에 오신 것을 환영해요","preheader":"하나의 사전, 하나의 사명. 단어 하나를 끝까지 이해하는 것. 이렇게 시작해 보세요.","paras":["Gadit에 오신 것을 환영해요. 함께해 주셔서 고마워요.","Gadit는 단 하나의 사명을 가진 사전이에요. 단어 하나를 끝까지 이해하는 것이죠. 한 줄짜리 정의도, 딱딱한 번역도 아니에요. 모든 뜻, 관용구, 단어의 유래, 그리고 사람들이 오늘날 실제로 쓰는 방식까지 담았어요.","무료 계정으로는 하루 10번 찾아볼 수 있고, 단어장에 30개 단어까지 저장할 수 있어요.","단어 하나를 완전히 이해하면 그 뒤에 있는 생각이 선명해지고, 그와 함께 생각하고 배우고 결정하는 방식도 달라져요.","Gadit는 계속 자라는 살아 있는 플랫폼이에요. 정의나 예문, 그 밖의 어느 부분에서든 오류를 발견하면 신고 버튼을 꼭 눌러 주세요. 저희 팀이 모두 읽고 고쳐요.","시작해 볼까요?"],"cta":"첫 단어 찾아보기","signOff":["감사합니다,","Gadit 팀 드림"]},"meanings":{"subject":"단어 하나에 숨은, 아직 못 본 층","preheader":"대부분의 도구는 정의에서 멈춰요. Gadit는 단어가 머리에 남을 때까지 계속 가요.","exampleWord":"길","paras":["'길'이라는 단어를 보세요. 단어 하나가 어떻게 하나의 세상을 여는지 알 수 있어요.","길은 사람이나 차가 다니는 땅 위의 길이에요. 길을 건너다, 길을 잃다. 어디론가 가는 여정이기도 해요. 학교 가는 길, 집에 오는 길. 방법이나 수단이기도 하죠. 다른 길이 없다, 살 길을 찾다. 삶이 나아가는 방향이기도 해요. 교사의 길, 자기만의 길을 걷다. 그리고 무언가를 하는 도중이라는 뜻도 있어요. 퇴근하는 길에 들렀어요.","단어 하나에 미처 보지 못한 층들이 있고, 그 층마다 자기만의 세상에서 살아가요.","Gadit에서는 모든 정의마다 실제 예문 세 개를 볼 수 있어요. 이론이 아니라 단어가 실제로 쓰이는 문장이에요. 그래서 단어가 무엇을 뜻하는지뿐 아니라, 쓰일 때 어떻게 들리는지도 알게 돼요.","이것이 Gadit의 핵심이에요. 단어 하나를, 모든 정의에 걸쳐, 끝까지.","'길'을 찾아보시고, 이미 다 안다고 생각하는 다른 단어도 하나 찾아보세요. 놀라실지도 몰라요."],"cta":"'길'을 찾아 모든 얼굴 보기","ps":"추신. 뜻밖의 뜻을 발견하면 바로 옆에 공유 버튼이 있어요. 재미있어할 사람에게 보내 보세요."},"etymology":{"subject":"단어는 정말 어디에서 왔을까","preheader":"모든 단어에는 과거가 있고, 때로는 그 과거가 지금을 설명해 줘요.","exampleWord":"길","paras":["드디어 저희가 가장 좋아하는 부분이에요. 단어가 어디에서 왔는지예요.","모든 단어에는 과거가 있어요. 그리고 그 과거가 어떤 정의보다도 지금을 더 잘 설명해 줄 때가 있어요.","'길'은 아름다운 예예요. 길은 한자에서 온 말이 아니라, 아주 오래전부터 써 온 우리 고유어예요. 한글이 만들어진 15세기의 옛 문헌에도 이미 나와요. 처음 뜻은 아주 구체적이었어요. 사람이 발로 걸어 다니는 땅 위의 길이었죠.","발로 걷는 길에서, 목표에 이르는 방법이라는 생각이 자라났어요. 그리고 거기서 더 추상적인 것, 한 사람이 살아가는 삶의 방향이라는 뜻이 생겼어요. 그래서 우리는 '살 길'을 찾고, '자기만의 길'을 걸어요. 재미있게도 같은 뜻의 한자 道(도)도 똑같은 길을 걸었어요. 사람이 다니는 길에서 방법으로, 그리고 사람이 지켜야 할 도리로 뜻이 넓어졌죠.","단어 하나에 담긴 여행 전체예요. 가장 눈에 보이는 것, 땅 위의 길에서, 가장 보이지 않는 것, 한 사람의 삶의 길까지. 그 모든 것이 오랜 세월 우리와 함께해 온 단어 하나에 담겨 있어요.","이걸 알고 나면 단어를 더 잘 기억할 뿐 아니라, 왜 모든 뜻이 서로 이어져 있는지도 이해하게 돼요. 우연히 함께 있는 게 아니에요.","Gadit에서는 각 단어의 정의 아래에 그 유래를 설명하는 부분이 있어요. 역사적 배경, 어디에서 왔는지. 그것이 사전을 정의 목록에서 하나의 이야기로 바꿔 줘요."],"cta":"다음 단어의 유래 알아보기"},"visual":{"subject":"눈높이에 맞춘 단어","preheader":"키즈 모드: 모든 단어를 아이의 말로, 깊이는 그대로 설명해요.","paras":["저희가 가장 많이 받은 요청 중 하나는 아주 단순했어요. 아이가 단어의 뜻을 물어보는데, 공식 정의는 아이에게 너무 어렵다는 거예요.","그래서 Gadit에는 키즈 모드가 있어요. 켜면 모든 단어가 다섯 살에서 열 살 아이의 말로 설명돼요. 깊이는 그대로, 어려운 말은 빼고요.","'중력'을 예로 들어 볼게요. 일반 모드에서는 물리와 공식 이야기가 돼요. 키즈 모드에서는 아이가 바로 알아듣는 말이 돼요. 공을 위로 던져도 늘 아래로 떨어지는 이유, 우리가 땅에 발을 딛고 서 있을 수 있는 이유예요.","그리고 이건 아이들만을 위한 게 아니에요. 정말 어려운 단어일 때는, 어른이 이해하는 데 필요한 것도 바로 쉬운 설명일 때가 있어요.","키즈 모드와 함께 Gadit는 뜻마다 그림도 보여 줘요. 그래서 아이는 단어를 읽을 뿐 아니라 눈으로 볼 수도 있어요. 이해는 더 빨리 오고, 더 오래 남아요.","키즈 모드는 아이가 있는 가정을 위한 Family 요금제에 포함돼요. 뜻마다 보이는 그림은 Individual 요금제에도 포함돼요.","곁에 아이가 있다면 잠깐 함께 앉아 키즈 모드를 켜고, 같이 단어를 찾아보고 그림을 보세요. 힘들이지 않고 이해하는 순간이 바로 이런 모습이에요."],"cta":"키즈 모드 알아보기"},"summary":{"subject":"2주, 단어 하나","preheader":"지금까지의 여정, 그리고 여기서 이어 갈 두 가지 길.","paras":["지난 2주 동안 저희는 단어 하나의 여러 얼굴을 알아봤어요. 모든 뜻, 그리고 그 역사까지요.","그와 함께 Gadit를 더 깊은 이해의 도구로 만드는 기능도 알아봤어요. 키즈 모드, 그리고 뜻마다 보이는 그림이에요.","이 기능 중 일부는 모든 사용자에게 열려 있어요. 무료 계정으로 하루 10번 찾아볼 수 있고, 단어장에 30개 단어까지 저장할 수 있어요.","나머지는 Individual로 열려요. 무제한 찾아보기, 뜻마다 보이는 그림, 모든 단어를 저장하고 스마트 연습까지 하는 단어장, 게임과 퀴즈, '모든 단어'(페이지를 찍고 아무 단어나 탭하기), 발음 연습을 위한 '말해 보기', 그리고 문장을 만들고 피드백 받기예요. Gadit가 이미 하루 일과의 일부가 되었다면, 차이를 만드는 건 바로 이 기능들이에요.","집에 아이가 있나요? <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> 요금제는 아이 최대 5명까지 쓸 수 있고, 키즈 모드와 부모 보드가 함께 제공돼요.","파트너 프로그램도 있어요. 나만의 링크를 통해 유료 가입이 생길 때마다 수수료를 받는 프로그램이에요. 좋아하는 것을 나누면서 수익도 얻을 수 있는 편리한 방법이에요."],"cta":"Individual 알아보기","ps":"추신. Gadit에 있었으면 하는 기능이 있다면 언제든 듣고 싶어요. 이 이메일에 답장만 해 주세요."}},
  nl: {"greetNamed":"Hallo {name},","greetPlain":"Hallo,","footerReason":"Je ontvangt deze e-mail omdat je je hebt aangemeld bij Gadit.","unsubscribeLabel":"Uitschrijven","welcome":{"subject":"Welkom bij Gadit","preheader":"Eén woordenboek, één missie. Een woord helemaal doorgronden. Zo begin je.","paras":["Welkom bij Gadit, en bedankt dat je erbij bent.","Gadit is een woordenboek met één missie: een woord helemaal doorgronden. Geen definitie van één regel, geen droge vertaling. Alle betekenissen, de uitdrukkingen, de herkomst van het woord en de manier waarop mensen het vandaag echt gebruiken.","Je gratis account bevat 10 zoekopdrachten per dag en een notitieboek voor maximaal 30 woorden.","Als je een woord volledig begrijpt, wordt het idee erachter helder, en daarmee ook hoe je denkt, leert en beslist.","Gadit is een levend platform dat steeds verder groeit. Zie je een fout in een definitie, een voorbeeld of een ander onderdeel? Er is een meldknop die het waard is om op te drukken. Ons team leest alles en verbetert het.","Klaar om te beginnen?"],"cta":"Zoek je eerste woord","signOff":["Hartelijke groet,","Het Gadit-team"]},"meanings":{"subject":"Eén woord, lagen die je nog niet zag","preheader":"De meeste tools stoppen bij de definitie. Gadit gaat door tot het blijft hangen.","exampleWord":"bank","paras":["Neem het woord bank, en zie hoe één woord een hele wereld kan openen.","Een bank is de zitbank in het park. Het is ook de bank in je woonkamer, waar je 's avonds op neerploft. Een bank is de plek waar je je geld bewaart. Het is een zandbank die bij eb boven water komt, en een mistbank die ineens over de weg hangt. Het is de reservebank langs het veld, waar spelers wachten tot ze erin mogen. En door de bank genomen betekent: over het geheel, gemiddeld.","Eén woord, lagen die je er nog niet in zag, elk in een eigen wereld.","In Gadit vind je bij elke definitie drie echte voorbeelden. Zinnen waarin het woord in de praktijk werkt, niet in theorie. Zo zie je niet alleen wat het woord zegt, maar ook hoe het klinkt als het gebruikt wordt.","Dit is het hart van Gadit. Eén woord, helemaal tot op de bodem, door al zijn definities heen.","We raden je aan om bank op te zoeken, en misschien nog een woord waarvan je denkt dat je het al helemaal begrijpt. Misschien word je verrast."],"cta":"Zoek bank op en zie alle kanten","ps":"PS Vind je een verrassende betekenis? Ernaast staat een deelknop. De moeite waard om naar iemand te sturen die het zal waarderen."},"etymology":{"subject":"Waar een woord echt vandaan komt","preheader":"Elk woord heeft een verleden, en soms verklaart dat het heden.","exampleWord":"bank","paras":["We zijn bij ons favoriete deel aangekomen. Waar het woord vandaan komt.","Elk woord heeft een verleden. En soms verklaart dat verleden het heden beter dan welke definitie ook.","Bank is een mooi voorbeeld. Het is een oud Germaans woord, in het Middelnederlands al banc, en het betekende een lange zitplaats, en ook een langgerekte verhoging, zoals een zandbank. Dezelfde basis zit in het Engelse bench en het Duitse Bank.","Het geld kwam later, via Italië. Daar deden geldwisselaars hun zaken aan een tafel, in het Italiaans banco. Die werkplek gaf zijn naam aan het hele bedrijf, en zo werd de bank een plek voor geld. Het Italiaanse woord kwam zelf uit het Germaans, dus het woord kwam via een omweg weer bij ons terug. Ook bankroet komt hiervandaan, van het Italiaanse banca rotta, letterlijk: gebroken bank.","Een hele reis in één woord. Van een houten zitplaats tot een instelling waar de wereld haar geld bewaart. Allemaal in één woord dat al eeuwen bij ons is.","Als je dit weet, onthoud je het woord niet alleen beter. Je begrijpt ook waarom al zijn betekenissen met elkaar verbonden zijn. Ze leven niet toevallig samen.","In Gadit staat onder de definities van elk woord een gedeelte dat de herkomst uitlegt. De historische achtergrond, waar het vandaan kwam. Dat maakt van een woordenboek met definities een verhaal."],"cta":"Ontdek de herkomst van het volgende woord"},"visual":{"subject":"Een woord op ooghoogte","preheader":"Kindermodus: elk woord uitgelegd in kindertaal, zonder de diepgang te verliezen.","paras":["Een van de vragen die we het vaakst kregen, was heel eenvoudig. Een kind vraagt wat een woord betekent, en de officiële definitie is te ingewikkeld.","Daarom heeft Gadit de Kindermodus. Zet hem aan, en elk woord wordt uitgelegd in de taal van een kind van vijf tot tien jaar. Dezelfde diepgang, zonder de moeilijke woorden.","Neem bank. In de gewone modus wordt het in verschillende lagen uitgelegd. In de Kindermodus wordt het iets wat een kind meteen snapt: een bank is iets waar je samen op kunt zitten, en ook een plek waar mensen hun geld veilig bewaren.","En het is niet alleen voor kinderen. Soms, als een woord echt moeilijk is, is de eenvoudige uitleg precies wat volwassenen ook nodig hebben om het te snappen.","Naast de Kindermodus toont Gadit ook een afbeelding bij elke betekenis, zodat een kind het woord kan zien en niet alleen lezen. Het begrip komt sneller en blijft langer.","De Kindermodus hoort bij het Family-abonnement, gemaakt voor gezinnen met kinderen. Een afbeelding bij elke betekenis krijg je ook met het Individual-abonnement.","Is er een kind in de buurt? Ga even samen zitten, zet de Kindermodus aan, zoek samen een woord op en bekijk de afbeelding. Zo ziet een moment van moeiteloos begrijpen eruit."],"cta":"Bekijk de Kindermodus"},"summary":{"subject":"Twee weken, één woord","preheader":"De reis, en twee manieren om vanaf hier verder te gaan.","paras":["De afgelopen twee weken hebben we de verschillende kanten van een woord leren kennen. Al zijn betekenissen, en zijn geschiedenis.","Daarnaast leerden we de functies kennen die van Gadit een hulpmiddel voor dieper begrip maken: de Kindermodus, en een afbeelding bij elke betekenis.","Een deel van deze functies staat open voor iedereen. Een gratis account bevat 10 zoekopdrachten per dag en een notitieboek voor maximaal 30 woorden.","De rest ontgrendel je met Individual: onbeperkt zoeken, een afbeelding bij elke betekenis, een notitieboek dat elk woord bewaart met slim oefenen, spellen en quizzen, Elk woord (fotografeer een pagina en tik op een woord), Zeg het om je uitspraak te oefenen, en zelf een zin maken met feedback. Is Gadit al een vast onderdeel van je dag? Dan maken juist deze functies het verschil.","Kinderen in huis? Het <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a>-abonnement is voor maximaal 5 kinderen, met de Kindermodus en een ouderdashboard.","En we hebben ook een partnerprogramma: een persoonlijke link waarmee je commissie verdient op elke betalende aanmelding die erdoor binnenkomt. Een handige manier om iets te delen waar je van houdt, en er onderweg iets aan te verdienen."],"cta":"Bekijk Individual","ps":"PS We horen altijd graag welke functies je in Gadit zou willen zien. Beantwoord gewoon deze e-mail."}},
  nr: {"greetNamed":"Lotjha {name},","greetPlain":"Lotjha,","footerReason":"Ufumana le-imeyili ngombana ubhalise ku-Gadit.","unsubscribeLabel":"Misa ama-imeyili","welcome":{"subject":"Wamukelekile ku-Gadit","preheader":"Isihlathululimezwi esisodwa, umnqopho munye. Ukuzwisisa ilizwi ngokupheleleko. Nansi indlela yokuthoma.","paras":["Wamukelekile ku-Gadit, begodu siyathokoza ngokuhlanganyela nathi.","I-Gadit isihlathululimezwi esinomnqopho munye: ukuzwisisa ilizwi ngokupheleleko. Akusiyo ihlathululo yomugqa munye, akusikutjhugulula kwaphela. Zoke iinhlathululo, izaga, umsuka welizwi, nendlela abantu abalisebenzisa ngayo namhlanjesi.","I-akhawunti yakho yamahala inokufuna okuli-10 ngelanga nebhuku lamezwi elifika emezwini ama-30.","Nawuzwisisa ilizwi ngokupheleleko, umqondo ongemva kwalo uyakhanya, begodu nendlela ocabanga ngayo, ofunda ngayo nothatha ngayo iinqunto.","I-Gadit yindawo ephilako eragela phambili ikhula. Nawubona isiphoso ehlathululweni nanyana ngiyiphi, esibonelweni namkha engcenyeni enye, kunenkinobho yokubika ekufanele uyithinte. Ithimba lethu lifunda koke begodu liyakulungisa.","Sewulungele ukuthoma?"],"cta":"Funa ilizwi lakho lokuthoma","signOff":["Ngethando,","Ithimba le-Gadit"]},"meanings":{"subject":"Ilizwi linye, iingcenye obungakaziboni","preheader":"Amathulusi amanengi ajama ehlathululweni. I-Gadit iyaragela phambili bekube ilizwi linamathele.","exampleWord":"ubuntu","paras":["Thatha ilizwi ubuntu, ubone bona ilizwi linye lingavula njani iphasi loke.","Ubuntu kukuba mumuntu, lokho esifana ngakho soke. Ubuntu kuba nomusa nehlonipho ebantwini: nasithi umuntu unobuntu, sitjho bona unomusa, uyasiza begodu uyahlonipha. Ubuntu kuziphatha kuhle, umuntu ongaziphathi kuhle sithi akanabuntu. Begodu ubuntu mqondo wokuphila ndawonye, ovela esagweni esithi: umuntu ngumuntu ngabantu.","Ilizwi linye, iingcenye obungakaziboni, ngayinye iphila ephasini layo.","Ku-Gadit ufumana izibonelo ezintathu zamambala zehlathululo ngayinye. Imitjho lapho ilizwi lisebenza khona ngamambala, ingasi ngomqondo kwaphela. Ngalokho awuboni kwaphela lokho ilizwi elikutjhoko, kodwana nendlela elizwakala ngayo nalisetjenziswa.","Le yihliziyo ye-Gadit. Ilizwi linye, ngokupheleleko, kizo zoke iinhlathululo zalo.","Sikukhuthaza bona ufune ubuntu, begodu mhlamunye nelinye ilizwi ocabanga bona sele ulizwisisa. Kungakumangaza."],"cta":"Funa ubuntu ubone iingcenye zoke","ps":"P.S. Nawufumana ihlathululo ekumangazako, kunenkinobho yokwabelana eceleni kwayo. Kufanele uyithumele kumuntu ozoyithabela."},"etymology":{"subject":"Lapho ilizwi livela khona ngamambala","preheader":"Ilizwi ngalinye linomlando walo, begodu ngesinye isikhathi uhlathulula namhlanjesi.","exampleWord":"ubuntu","paras":["Sifikile engcenyeni esiyithanda khulu. Lapho ilizwi livela khona.","Ilizwi ngalinye linomlando. Begodu ngesinye isikhathi umlando loyo uhlathulula namhlanjesi ngcono kunehlathululo nanyana ngiyiphi.","Ubuntu sibonelo esihle. Umsuka walo ngu-ntu, umsuka ofanako newelizwi umuntu nabantu. Nawufaka u-ubu- phambili, ilizwi elitjho umuntu liba lilizwi elitjho lokho okukuba mumuntu.","Umsuka lo mdala khulu, begodu wabelwana ngamakhulu wamalimi we-Afrika. NgesiSuthu ngu-motho no-botho, ngesiTsonga ngu-munhu, ngesiSwahili ngu-mtu. Nebizo lomndeni woke walamalimi, amalimi wesiBantu, livela elizwini leli: ekhulwini le-19 leminyaka, isazi samalimi sathatha ilizwi elithi bantu sabiza ngalo umndeni lo woke.","Ikhambo loke elizwini linye. Ukusuka kumuntu munye, ukuya endleleni esiphatha ngayo abanye, bekube semqondweni wokuphila ndawonye.","Nawukwazi lokhu, akusikuthi ulikhumbula kwaphela ilizwi kuhle. Uyazwisisa nokuthi kubayini zoke iinhlathululo zalo zihlobene. Azihlangananga ngengozi.","Ku-Gadit, ngaphasi kweenhlathululo zelizwi ngalinye, kunengcenye ehlathulula umsuka walo. Umlando walo, lapho livela khona. Yilokho okutjhugulula isihlathululimezwi sisuke ekubeni luhlu lweenhlathululo sibe yindaba."],"cta":"Fumana umsuka welizwi elilandelako"},"visual":{"subject":"Ilizwi ngamehlo womntwana","preheader":"Imodi yabantwana: ilizwi ngalinye lihlathululwa ngelimi lomntwana, ngaphandle kokulahlekelwa yihlathululo epheleleko.","paras":["Esinye sezibawo esizifumana kanengi besilula. Umntwana ubuza bona ilizwi litjho ini, kodwana ihlathululo esemthethweni ibudisi khulu kuye.","Kungalokho i-Gadit inayo i-Imodi yabantwana. Uyayivula, bese ilizwi ngalinye lihlathululwa ngelimi lomntwana oneminyaka emihlanu ukuya kwelitjhumi. Ihlathululo efanako epheleleko, ngaphandle kwamezwi amakhulu.","Thatha ubuntu. Emodini ejayelekileko buhlathululwa ngeengcenye ezinengi. Emodini yabantwana buba yinto umntwana ayizwisisa msinyana: kukuba nomusa ebantwini, ubasize begodu ubahloniphe, ngombana soke siyatlhogana.","Begodu lokhu akusi kwabantwana kwaphela. Ngesinye isikhathi, nalilizwi libudisi ngamambala, ihlathululo elula ngiyo nabantu abadala abayitlhogako bona balizwisise.","Eceleni kwe-Imodi yabantwana, i-Gadit itjengisa nesithombe sehlathululo ngayinye, bona umntwana abone ilizwi, angalifundi kwaphela. Ukuzwisisa kufika msinyana begodu kuhlala isikhathi eside.","I-Imodi yabantwana iyingcenye yehlelo le-Family, elenzelwe imindeni enabantwana. Isithombe sehlathululo ngayinye sifika nehlelo le-Individual.","Nangabe kunomntwana eduze, hlala naye umzuzwana, uvule i-Imodi yabantwana, nifune ilizwi ndawonye bese niqala isithombe salo. Le yindlela ukuzwisisa okufika ngayo kalula."],"cta":"Bona i-Imodi yabantwana"},"summary":{"subject":"Iimveke ezimbili, ilizwi linye","preheader":"Ikhambo, neendlela ezimbili zokuragela phambili ukusuka lapha.","paras":["Eemvekeni ezimbili ezidlulileko sibone amahlangothi ahlukahlukeneko welizwi. Zoke iinhlathululo zalo, nomlando walo.","Ngaphezu kwalokho, sibone amathulusi enza i-Gadit ibe lithulusi lokuzwisisa ngokupheleleko: i-Imodi yabantwana, nesithombe sehlathululo ngayinye.","Amanye walamathulusi avulekele woke umsebenzisi. I-akhawunti yamahala inokufuna okuli-10 ngelanga nebhuku lamezwi elifika emezwini ama-30.","Asalako avulwa yi-<strong>Individual</strong>: ukufuna ngaphandle komkhawulo, isithombe sehlathululo ngayinye, ibhuku lamezwi elibulunga ilizwi ngalinye nokuzilolonga okuhlakaniphileko, imidlalo neenkhwizi, Ilizwi ngalinye (thatha isithombe sekhasi bese uthinta ilizwi nanyana ngiliphi), Kutjho ukuzilolonga ukuphimisa, nokutlola umutjho bese uthola amazwana. Nangabe i-Gadit sele iyingcenye yelanga lakho, la mathulusi enza umehluko.","Unabantwana ekhaya? Ihlelo le-<a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> lifaka abantwana abafika ku-5, ne-Imodi yabantwana nedeshibhodi yababelethi.","Begodu sinehlelo lababambisani: ilinki yakho ekunikela ikhomitjhini ngomuntu ngamunye obhalisa abhadele ngayo. Yindlela elula yokwabelana ngalokho okuthandako, uthole nemali."],"cta":"Azi i-Individual","ps":"P.S. Sihlala sithabela ukuzwa ngamathulusi ongathanda ukuwabona ku-Gadit. Phendula le-imeyili kwaphela."}},
  nso: {"greetNamed":"Dumela {name},","greetPlain":"Dumela,","footerReason":"O amogela imeile ye ka gobane o ingwadišitše go Gadit.","unsubscribeLabel":"Emiša diimeile","welcome":{"subject":"Re a go amogela go Gadit","preheader":"Pukuntšu e tee, nepo e tee. Go kwešiša lentšu go fihla mafelelong. Thoma ka tsela ye.","paras":["Re a go amogela go Gadit, gomme re a leboga go tsenela.","Gadit ke pukuntšu ye e nago le nepo e tee: go kwešiša lentšu go fihla mafelelong. E sego tlhalošo ya mothaladi o tee, e sego phetolelo ye e omilego. Ditlhalošo ka moka, dika, mothopo wa lentšu, le ditsela tšeo batho ba le šomišago ka tšona lehono.","Akhaonto ya gago ya mahala e akaretša dinyakišišo tše 10 ka letšatši le puku ya mantšu ya go fihla go mantšu a 30.","Ge o kwešiša lentšu ka botlalo, kgopolo ye e lego ka morago ga lona e a hlaka, gomme le yona tsela yeo o naganago, o ithutago le o phethago ka yona.","Gadit ke sethala se se phelago seo se tšwelago pele go gola. Ge o bona phošo tlhalošong efe goba efe, mohlaleng goba karolong ye nngwe, go na le konope ya go bega yeo e swanetšego go kgotlwa. Sehlopha sa rena se bala tšohle gomme se a di lokiša.","O itokišeditše go thoma?"],"cta":"Nyaka lentšu la gago la mathomo","signOff":["Ka tlhompho,","Sehlopha sa Gadit"]},"meanings":{"subject":"Lentšu le tee, dikarolo tšeo o sego wa di bona","preheader":"Didirišwa tše dintši di emela tlhalošong. Gadit e tšwela pele go fihlela lentšu le dula.","exampleWord":"moya","paras":["Tšea lentšu \"moya\", o bone ka moo lentšu le tee le ka bulago lefase ka moka ka gona.","Moya ke seo se fokago mehlareng, moya o tonya wa marega. Ke moya wo re o hemago, moya o hlwekilego. Ke moya wa motho ka gare, pelo le semelo sa gagwe. Ke moya wo o lego gare ga batho, bjalo ka moya wo mobotse ka lapeng goba ka sehlopheng. Gomme kerekeng, ke Moya o Mokgethwa.","Lentšu le tee, dikarolo tšeo o sego wa di bona go lona, e nngwe le e nngwe e phela lefaseng la yona.","Go Gadit o tla hwetša mehlala ye meraro ya nnete ya tlhalošo ye nngwe le ye nngwe. Mafoko ao lentšu le šomago go ona bophelong, e sego ka teori fela. Ka tsela ye o bona e sego feela seo lentšu le se rago, eupša le ka moo le kwagalago ka gona ge le šomišwa.","Ye ke pelo ya Gadit. Lentšu le tee, go fihla mafelelong, ditlhalošong ka moka tša lona.","Re go šišinya gore o nyake \"moya\", mohlomongwe le lentšu le lengwe leo o naganago gore o šetše o le tseba gabotse. O ka makala."],"cta":"Nyaka lentšu \"moya\"","ps":"P.S. Ge o hwetša tlhalošo ye e go makatšago, go na le konope ya go abelana kgauswi le yona. Go bohlokwa go e romela go motho yo a tla e thabelago."},"etymology":{"subject":"Lentšu le tšwa kae ka nnete","preheader":"Lentšu le lengwe le le lengwe le na le histori, gomme ka dinako tše dingwe e hlaloša lehono.","exampleWord":"moya","paras":["Re fihlile karolong ye re e ratago kudu. Moo lentšu le tšwago gona.","Lentšu le lengwe le le lengwe le na le histori. Gomme ka dinako tše dingwe histori yeo e hlaloša lehono kaone go feta tlhalošo efe goba efe.","Moya ke mohlala o mobotse. Lentšu le ga se la Sepedi fela. Ka Sesotho le lona ke moya, gomme ka isiZulu le ka isiXhosa ke umoya. Ge dipolelo tša leloko le tee di na le lentšu le le swanago ka tsela ye, se se bontšha gore le tšwa go mogologolo wa tšona o tee wa kgale, pele dipolelo tše di arogana.","Gomme bona ka moo ditlhalošo tša lona di kgokaganego ka gona. Ka moka ke selo seo o ka se kego wa se bona ka mahlo eupša o a se kwa: moya sefahlegong sa gago, moya maswafong a gago, moya wo o phedišago motho. Go tloga moo, go bonolo go bona ka moo lentšu le fihlelelago gape seo se sa bonagalego ka gare ga motho, moya wa gagwe, le moya wo o lego gare ga batho.","Ge Beibele e fetolelwa go Sepedi, bafetoledi ba šomišitše lentšu le go bitša Moya o Mokgethwa.","Leeto ka moka ka lentšung le tee. Go tloga selong seo o se kwago letlalong la gago, moya wo o fokago, go ya go selo se se sa bonagalego go feta tšohle, moya wa motho.","Ge o šetše o tseba se, ga o gopole fela lentšu kaone. O kwešiša gape gore ke ka lebaka la eng ditlhalošo tša lona ka moka di kgokagane. Ga di dule mmogo ka sewelo.","Go Gadit, ka tlase ga ditlhalošo tša lentšu le lengwe le le lengwe, go na le karolo ye e hlalošago mothopo wa lona. Histori ya lona, moo le tšwago gona. Ke seo se fetošago pukuntšu go tloga lenaneong la ditlhalošo go ba kanegelo."],"cta":"Utolla mothopo wa lentšu le le latelago"},"visual":{"subject":"Lentšu go ya ka mahlo a ngwana","preheader":"Mokgwa wa bana: lentšu le lengwe le le lengwe le hlalošwa ka polelo ya ngwana, ntle le go lahlegelwa ke botebo.","paras":["Kgopelo ye nngwe ye re e hweditšego gantši e be e le bonolo. Ngwana o botšiša gore lentšu le ra eng, gomme tlhalošo ya semmušo e thata kudu go yena.","Ke ka lebaka leo Gadit e nago le Mokgwa wa bana. O bule, gomme lentšu le lengwe le le lengwe le hlalošwa ka polelo ya ngwana wa mengwaga ye mehlano go ya go ye lesome. Botebo bjo bo swanago, ntle le mantšu a magolo.","Tšea lentšu \"moya\". Mokgweng wa ka mehla, le hlalošwa ka dikarolo tše mmalwa. Mokgweng wa bana, le fetoga selo seo ngwana a se kwešišago ka pela, bjalo ka seo o se kwago sefahlegong sa gago ge mehlare e šikinyega, le moya wo o tsenago le go tšwa ge o hema.","Gomme se ga se sa bana fela. Ka dinako tše dingwe, ge lentšu le le thata kudu, tlhalošo ye bonolo ke yona seo le batho ba bagolo ba se hlokago go le kwešiša.","Kgauswi le Mokgwa wa bana, Gadit e bontšha gape seswantšho sa tlhalošo ye nngwe le ye nngwe, gore ngwana a bone lentšu gape a le bale. Kwešišo e fihla ka pela gomme e dula nako ye telele.","Mokgwa wa bana ke karolo ya leano la Family, leo le diretšwego malapa ao a nago le bana. Seswantšho sa tlhalošo ye nngwe le ye nngwe se tla gape le leano la Individual.","Ge go na le ngwana kgauswi, dula le yena motsotswana, o bule Mokgwa wa bana, le nyake lentšu mmogo gomme le lebelele seswantšho sa lona. Ke ka moo motsotso wa kwešišo ye bonolo o bonagalago ka gona."],"cta":"Bona Mokgwa wa bana"},"summary":{"subject":"Dibeke tše pedi, lentšu le tee","preheader":"Leeto, le ditsela tše pedi tša go tšwela pele go tloga mo.","paras":["Dibekeng tše pedi tše di fetilego re tsebile mahlakore a fapanego a lentšu. Ditlhalošo ka moka tša lona, le histori ya lona.","Kgauswi le seo, re tsebile dikarolo tšeo di dirago Gadit sedirišwa sa kwešišo ye e tseneletšego: Mokgwa wa bana, le seswantšho sa tlhalošo ye nngwe le ye nngwe.","Tše dingwe tša dikarolo tše di bulegetše modiriši yo mongwe le yo mongwe. Akhaonto ya mahala e akaretša dinyakišišo tše 10 ka letšatši le puku ya mantšu ya go fihla go mantšu a 30.","Tše dingwe di bulwa ka Individual: dinyakišišo tše di sa felego, seswantšho sa tlhalošo ye nngwe le ye nngwe, puku ya mantšu ye e bolokago lentšu le lengwe le le lengwe ka tlwaetšo ye bohlale, dipapadi le ditlhahlobo, Lentšu le lengwe le le lengwe (tšea seswantšho sa letlakala o kgotle lentšu lefe goba lefe), E bolele go itlwaetša go bitša mantšu, le go bopa lefoko o hwetše dikarabelo. Ge Gadit e šetše e le karolo ya bophelo bja gago bja letšatši le letšatši, tše ke dikarolo tšeo di dirago phapano.","O na le bana gae? Leano la <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> le akaretša go fihla go bana ba 5, ka Mokgwa wa bana le letlakala la taolo la motswadi.","Gomme re na le lenaneo la balekane: linki ya gago ya motho ka noši ye e go fago khomišene go ngwadišo ye nngwe le ye nngwe ye e lefelwago yeo e tlago ka yona. Tsela ye bonolo ya go abelana ka selo seo o se ratago, gomme o hole tseleng."],"cta":"Tseba Individual","ps":"P.S. Re dula re thabela go kwa ka didirišwa tšeo o ka ratago go di bona go Gadit. Araba fela imeile ye."}},
  pl: {"greetNamed":"Cześć {name},","greetPlain":"Cześć,","footerReason":"Otrzymujesz tę wiadomość, ponieważ masz konto w Gadit.","unsubscribeLabel":"Wypisz się","welcome":{"subject":"Witamy w Gadit","preheader":"Jeden słownik, jedna misja. Zrozumieć słowo do końca. Oto jak zacząć.","paras":["Witamy w Gadit i dziękujemy, że jesteś z nami.","Gadit to słownik z jedną misją: zrozumieć słowo do końca. Nie jednolinijkowa definicja, nie suche tłumaczenie. Wszystkie znaczenia, idiomy, pochodzenie słowa i to, jak ludzie naprawdę używają go dzisiaj.","Twoje darmowe konto obejmuje 10 wyszukiwań dziennie i notatnik na maksymalnie 30 słów.","Kiedy rozumiesz słowo w pełni, jasna staje się też idea, która za nim stoi, a razem z nią to, jak myślisz, uczysz się i podejmujesz decyzje.","Gadit to żywa platforma, która ciągle się rozwija. Jeśli zauważysz błąd w definicji, w przykładzie albo w innym miejscu, jest przycisk do zgłaszania błędów i warto go nacisnąć. Nasz zespół czyta wszystko i poprawia.","Zaczynamy?"],"cta":"Wyszukaj swoje pierwsze słowo","signOff":["Serdecznie pozdrawiamy,","Zespół Gadit"]},"meanings":{"subject":"Jedno słowo i jego ukryte warstwy","preheader":"Większość narzędzi kończy na definicji. Gadit idzie dalej, aż słowo zostanie w pamięci.","exampleWord":"zamek","paras":["Weź słowo zamek i zobacz, jak jedno słowo potrafi otworzyć cały świat.","Zamek to budowla z murami i wieżami, w której mieszkali królowie i rycerze. Zamek to też mechanizm w drzwiach, do którego wkładasz klucz. Zamek błyskawiczny zapina kurtkę. Zamek w karabinie zamyka komorę z nabojem. A dzieci na plaży budują zamki z piasku.","Jedno słowo, a w nim ukryte warstwy, z których każda żyje we własnym świecie.","W Gadit do każdej definicji znajdziesz trzy prawdziwe przykłady. Zdania, w których słowo działa w praktyce, a nie w teorii. Dzięki temu widzisz nie tylko, co słowo znaczy, ale też jak brzmi w użyciu.","To jest serce Gadit. Jedno słowo, do samego końca, we wszystkich jego znaczeniach.","Proponujemy wyszukać zamek, a potem może jeszcze jedno słowo, które wydaje ci się dobrze znane. Możesz się zaskoczyć."],"cta":"Wyszukaj słowo zamek","ps":"P.S. Kiedy trafisz na zaskakujące znaczenie, obok jest przycisk udostępniania. Warto wysłać je komuś, kto to doceni."},"etymology":{"subject":"Skąd naprawdę pochodzi słowo","preheader":"Każde słowo ma przeszłość, a czasem ona wyjaśnia teraźniejszość.","exampleWord":"zamek","paras":["Dotarliśmy do naszej ulubionej części. Skąd pochodzi słowo.","Każde słowo ma przeszłość. I czasem ta przeszłość wyjaśnia teraźniejszość lepiej niż jakakolwiek definicja.","Zamek to piękny przykład. Pochodzi od czasownika zamykać i należy do tej samej rodziny co zamknąć i zamknięcie. U podstaw leży więc jedna prosta czynność: zamknięcie czegoś tak, żeby nikt niepowołany nie dostał się do środka.","Z tej czynności wyrosły oba główne znaczenia. Zamek w drzwiach to urządzenie, które zamyka. Zamek na wzgórzu to miejsce zamknięte murami, warownia, do której wróg nie miał wstępu. Później to samo słowo nazwało zamek błyskawiczny i zamek w broni, bo one też coś zamykają. Ciekawe, że podobnie jest w niemieckim: Schloss oznacza zarówno zamek w drzwiach, jak i zamek, w którym mieszkał władca.","Cała podróż w jednym słowie. Od prostego ruchu ręki, zamknięcia drzwi, do potężnej budowli z wieżami.","Kiedy to wiesz, nie tylko lepiej zapamiętujesz słowo. Rozumiesz też, dlaczego wszystkie jego znaczenia są ze sobą połączone. Nie żyją razem przypadkiem.","W Gadit pod definicjami każdego słowa jest sekcja, która wyjaśnia jego pochodzenie. Tło historyczne, skąd się wzięło. To właśnie zmienia słownik z listy definicji w opowieść."],"cta":"Odkryj pochodzenie następnego słowa"},"visual":{"subject":"Słowo na wysokości oczu","preheader":"Tryb dla dzieci: każde słowo wyjaśnione językiem dziecka, bez utraty głębi.","paras":["Jedna z najczęstszych próśb, jakie dostawaliśmy, była prosta. Dziecko pyta, co znaczy jakieś słowo, a oficjalna definicja jest dla niego za trudna.","Dlatego Gadit ma Tryb dla dzieci. Włączasz go i każde słowo jest wyjaśnione językiem dziecka w wieku od pięciu do dziesięciu lat. Ta sama głębia, bez trudnych słów.","Weź słowo grawitacja. W zwykłym trybie mowa jest o siłach i masach. W Trybie dla dzieci to coś, co dziecko rozumie od razu: to, przez co rzeczy spadają na podłogę, kiedy je puścisz, i co trzyma nas na ziemi.","I to nie tylko dla dzieci. Czasem, kiedy słowo jest naprawdę trudne, proste wyjaśnienie jest dokładnie tym, czego potrzebują też dorośli, żeby je zrozumieć.","Obok Trybu dla dzieci Gadit pokazuje też obrazek do każdego znaczenia, żeby dziecko mogło słowo nie tylko przeczytać, ale i zobaczyć. Zrozumienie przychodzi szybciej i zostaje na dłużej.","Tryb dla dzieci jest częścią planu Family, stworzonego dla rodzin z dziećmi. Obrazek do każdego znaczenia jest też w planie Individual.","Jeśli masz obok dziecko, usiądź z nim na chwilę, włącz Tryb dla dzieci, wyszukajcie razem słowo i obejrzyjcie jego obrazek. Tak wygląda chwila, w której zrozumienie przychodzi bez wysiłku."],"cta":"Poznaj Tryb dla dzieci"},"summary":{"subject":"Dwa tygodnie, jedno słowo","preheader":"Droga, którą przeszliśmy, i dwa sposoby, by iść dalej.","paras":["Przez ostatnie dwa tygodnie poznaliśmy różne strony słowa. Wszystkie jego znaczenia i jego historię.","Poznaliśmy też funkcje, dzięki którym Gadit jest narzędziem do głębszego rozumienia: Tryb dla dzieci i obrazek do każdego znaczenia.","Część tych funkcji jest dostępna dla wszystkich. Darmowe konto obejmuje 10 wyszukiwań dziennie i notatnik na maksymalnie 30 słów.","Reszta odblokowuje się z Individual: nielimitowane wyszukiwanie, obrazek do każdego znaczenia, notatnik, który zapisuje każde słowo, z inteligentnymi ćwiczeniami, gry i quizy, Każde słowo (zrób zdjęcie strony i stuknij dowolne słowo), Powiedz to do ćwiczenia wymowy oraz układanie zdań z informacją zwrotną. Jeśli Gadit stał się częścią twojego dnia, to właśnie te funkcje robią różnicę.","Masz dzieci w domu? Plan <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> obejmuje do 5 dzieci, z Trybem dla dzieci i panelem rodzica.","Mamy też program partnerski: osobisty link, dzięki któremu dostajesz prowizję od każdej płatnej rejestracji, która przez niego przyjdzie. Wygodny sposób, by dzielić się czymś, co lubisz, i przy okazji zarobić."],"cta":"Poznaj Individual","ps":"P.S. Zawsze chętnie usłyszymy, jakie funkcje chcesz zobaczyć w Gadit. Wystarczy odpowiedzieć na tę wiadomość."}},
  ru: {"greetNamed":"Здравствуйте, {name},","greetPlain":"Здравствуйте,","footerReason":"Вы получили это письмо, потому что зарегистрировались в Gadit.","unsubscribeLabel":"Отписаться","welcome":{"subject":"Добро пожаловать в Gadit","preheader":"Один словарь, одна миссия. Понять слово до конца. Вот с чего начать.","paras":["Добро пожаловать в Gadit, и спасибо, что вы с нами.","У Gadit одна миссия: понять слово до конца. Не определение в одну строку и не сухой перевод. Все значения, устойчивые выражения, происхождение слова и то, как люди на самом деле употребляют его сегодня.","В вашем бесплатном аккаунте 10 поисков в день и тетрадь до 30 слов.","Когда вы понимаете слово полностью, становится ясной и идея, которая за ним стоит, а вместе с ней то, как вы думаете, учитесь и принимаете решения.","Gadit живёт и постоянно растёт. Если вы заметите ошибку в определении, в примере или где-то ещё, есть кнопка, чтобы сообщить о ней, и её стоит нажать. Наша команда читает всё и исправляет.","Готовы начать?"],"cta":"Найдите своё первое слово","signOff":["С теплом,","Команда Gadit"]},"meanings":{"subject":"Одно слово, слои, которых вы не замечали","preheader":"Большинство словарей останавливаются на определении. Gadit идёт дальше, пока слово не запомнится.","exampleWord":"язык","paras":["Возьмите слово «язык» и посмотрите, как одно слово может открыть целый мир.","Прежде всего язык живёт у нас во рту: им мы чувствуем вкус и говорим. Но язык ещё и речь целого народа: русский язык, английский язык. Бывает язык пламени и язык колокола, тот металлический стержень внутри, который ударяет по стенкам. Бывает язык программирования. А на войне «взять языка» значит захватить пленного, который расскажет о противнике.","Одно слово, слои, которых вы в нём не замечали, и каждый живёт в своём мире.","В Gadit для каждого значения есть три настоящих примера. Предложения, в которых слово работает на практике, а не в теории. Так вы видите не только то, что слово значит, но и то, как оно звучит в речи.","В этом сердце Gadit. Одно слово, до самого конца, во всех его значениях.","Предлагаем найти слово «язык», а потом, может быть, ещё одно, которое вы, как вам кажется, уже хорошо знаете. Возможно, оно вас удивит."],"cta":"Найти слово «язык»","ps":"P.S. Когда вы найдёте неожиданное значение, рядом с ним будет кнопка, чтобы им поделиться. Его стоит отправить тому, кто это оценит."},"etymology":{"subject":"Откуда на самом деле приходит слово","preheader":"У каждого слова есть прошлое, и иногда оно объясняет настоящее.","exampleWord":"язык","paras":["Мы дошли до нашей любимой части. Откуда пришло слово.","У каждого слова есть прошлое. И иногда это прошлое объясняет настоящее лучше любого определения.","Язык служит прекрасным примером. Это очень древнее слово, оно восходит к праславянскому языку. Сначала оно называло орган во рту, тот самый, которым мы говорим. Отсюда и язычок, и выражение «держать язык за зубами».","Потом значение выросло: от органа речи к самой речи. Тем, чем говорят, стали называть и то, как говорят. Так язык стал речью целого народа. А в старославянском языке, на котором читали Библию, «языками» называли сами народы. Отсюда и слово «язычники»: так в древних текстах называли другие народы, людей иной веры.","Целое путешествие в одном слове. От самого телесного, органа во рту, к речи, а от речи к целому народу.","Когда вы это знаете, слово не только лучше запоминается. Вы ещё и понимаете, почему все его значения связаны. Они живут вместе не случайно.","В Gadit под определениями каждого слова есть раздел о его происхождении. Историческая основа, откуда оно пришло. Именно это превращает словарь из списка определений в историю."],"cta":"Узнать происхождение следующего слова"},"visual":{"subject":"Слово на уровне глаз","preheader":"Детский режим: каждое слово объяснено языком ребёнка, без потери глубины.","paras":["Одна из самых частых просьб, которые мы получали, была простой. Ребёнок спрашивает, что значит слово, а официальное определение для него слишком сложное.","Поэтому в Gadit есть детский режим. Включите его, и каждое слово будет объяснено языком ребёнка от пяти до десяти лет. Та же глубина, только без сложных слов.","Возьмём слово «гравитация». В обычном режиме речь идёт о силах и массах. В детском режиме это то, что ребёнок понимает сразу: то, из-за чего вещи падают на пол, когда их отпускаешь, и что держит нас на земле.","И это не только для детей. Иногда, когда слово действительно трудное, простое объяснение как раз то, что нужно и взрослым, чтобы его понять.","Вместе с детским режимом Gadit показывает картинку для каждого значения, чтобы ребёнок мог не только прочитать слово, но и увидеть его. Понимание приходит быстрее и остаётся надольше.","Детский режим входит в тариф Family, созданный для семей с детьми. Картинка для каждого значения есть и в тарифе Individual.","Если рядом ребёнок, посидите с ним минутку, включите детский режим, найдите вместе слово и посмотрите на его картинку. Вот так выглядит момент, когда понимание приходит без усилий."],"cta":"Посмотреть детский режим"},"summary":{"subject":"Две недели, одно слово","preheader":"Пройденный путь и два способа идти дальше.","paras":["За эти две недели мы познакомились с разными сторонами слова. Со всеми его значениями и с его историей.","А ещё с возможностями, которые делают Gadit инструментом для более глубокого понимания: с детским режимом и картинкой для каждого значения.","Некоторые из них открыты всем. В бесплатном аккаунте 10 поисков в день и тетрадь до 30 слов.","Остальное открывается с Individual: неограниченный поиск, картинка для каждого значения, тетрадь, которая сохраняет каждое слово и предлагает умную тренировку, игры и тесты, «Каждое слово» (сфотографируйте страницу и нажмите на любое слово), «Скажи это» для тренировки произношения, а ещё можно составить предложение и получить отзыв. Если Gadit уже стал частью вашего дня, именно эти возможности меняют всё.","Дома есть дети? Тариф <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> включает до 5 детей, с детским режимом и панелью для родителей.","А ещё у нас есть партнёрская программа: личная ссылка, по которой вы получаете комиссию за каждую платную регистрацию. Удобный способ поделиться тем, что вам нравится, и заработать."],"cta":"Узнать об Individual","ps":"P.S. Нам всегда интересно узнать, какие функции вы хотели бы видеть в Gadit. Просто ответьте на это письмо."}},
  sk: {"greetNamed":"Dobrý deň, {name},","greetPlain":"Dobrý deň,","footerReason":"Tento e-mail dostávate, pretože ste sa zaregistrovali do Gadit.","unsubscribeLabel":"Odhlásiť sa z odberu","welcome":{"subject":"Vitajte v Gadit","preheader":"Jeden slovník, jedno poslanie. Pochopiť slovo do hĺbky. Takto môžete začať.","paras":["Vitajte v Gadit a ďakujeme, že ste sa k nám pridali.","Gadit je slovník s jediným poslaním: pochopiť slovo úplne. Nie jednoriadková definícia, nie suchý preklad. Všetky významy, ustálené spojenia, pôvod slova a spôsoby, akými ho ľudia dnes naozaj používajú.","Váš bezplatný účet zahŕňa 10 vyhľadaní denne a zošit až na 30 slov.","Keď slovo pochopíte úplne, ujasní sa aj myšlienka, ktorá za ním stojí, a s ňou aj to, ako premýšľate, ako sa učíte a ako sa rozhodujete.","Gadit je živá platforma, ktorá stále rastie. Ak nájdete chybu v definícii, v príklade alebo kdekoľvek inde, je tam tlačidlo na nahlásenie, ktoré sa oplatí stlačiť. Náš tím všetko číta a opravuje.","Môžeme začať?"],"cta":"Vyhľadajte svoje prvé slovo","signOff":["S pozdravom,","Tím Gadit"]},"meanings":{"subject":"Jedno slovo, vrstvy, ktoré ste ešte nevideli","preheader":"Väčšina nástrojov sa zastaví pri definícii. Gadit pokračuje, kým vám slovo neutkvie v pamäti.","exampleWord":"koruna","paras":["Vezmite si slovo „koruna“ a pozrite sa, ako jedno slovo dokáže otvoriť celý svet.","Koruna je ozdoba na hlave kráľa či kráľovnej, znak ich moci. Koruna je aj horná časť stromu, jeho konáre a listy. Koruna je mena, ktorou sa na Slovensku platilo až do konca roka 2008 a v Česku sa ňou platí dodnes. Koruna je aj najvyššia časť stavby, napríklad koruna hrádze. A keď vám zubár opravuje zub, môže vám naň nasadiť korunku.","Jedno slovo, vrstvy, ktoré ste v ňom nevideli, a každá žije vo vlastnom svete.","V Gadit nájdete ku každej definícii tri skutočné príklady. Vety, v ktorých slovo funguje v praxi, nie v teórii. Tak vidíte nielen to, čo slovo znamená, ale aj to, ako znie, keď sa používa.","Toto je srdce Gadit. Jedno slovo, až do konca, naprieč všetkými jeho definíciami.","Odporúčame vyhľadať slovo „koruna“ a možno aj ďalšie slovo, o ktorom si myslíte, že mu už rozumiete. Možno vás prekvapí."],"cta":"Vyhľadajte slovo „koruna“","ps":"P.S. Keď narazíte na prekvapivý význam, hneď vedľa neho je tlačidlo na zdieľanie. Oplatí sa ho poslať niekomu, kto to ocení."},"etymology":{"subject":"Odkiaľ slovo naozaj pochádza","preheader":"Každé slovo má minulosť a niekedy práve ona vysvetľuje prítomnosť.","exampleWord":"koruna","paras":["Dostali sme sa k našej obľúbenej časti. Odkiaľ slovo pochádza.","Každé slovo má minulosť. A niekedy táto minulosť vysvetľuje prítomnosť lepšie než akákoľvek definícia.","Koruna je krásny príklad. Pochádza z latinského slova „corona“, ktoré znamenalo veniec, kruh z kvetov alebo listov. Latinčina ho prevzala z gréčtiny, kde „korónē“ označovalo niečo zahnuté, ohnuté do oblúka. Z toho istého latinského slova pochádza aj anglické „crown“ a slovo „koróna“, svetelný kruh okolo Slnka.","Najprv to bol jednoduchý veniec, ktorý sa kládol na hlavu víťazom a hrdinom. Z venca sa stal symbol moci panovníka. A odtiaľ sa slovo rozšírilo ďalej: na všetko, čo tvorí vrchol, ako koruna stromu alebo koruna hrádze, a aj na menu, ktorá nesie meno panovníckej koruny.","Celá cesta v jednom slove. Od venca z listov na hlave víťaza až po peniaze v peňaženke. To všetko v jednom slove, ktoré je s nami už stáročia.","Keď to viete, slovo si nielen lepšie zapamätáte. Pochopíte aj to, prečo sú všetky jeho významy prepojené. Nežijú spolu náhodou.","V Gadit nájdete pod definíciami každého slova časť, ktorá vysvetľuje jeho pôvod. Historické pozadie, odkiaľ slovo prišlo. Práve to robí zo slovníka namiesto zoznamu definícií príbeh."],"cta":"Objavte pôvod ďalšieho slova"},"visual":{"subject":"Slovo vo výške očí","preheader":"Detský režim: každé slovo vysvetlené jazykom dieťaťa, bez straty hĺbky.","paras":["Jedna z najčastejších prosieb, ktoré sme dostávali, bola jednoduchá. Dieťa sa spýta, čo slovo znamená, a oficiálna definícia je preň príliš zložitá.","Preto má Gadit Detský režim. Zapnete ho a každé slovo je vysvetlené jazykom dieťaťa vo veku päť až desať rokov. Rovnaká hĺbka, bez ťažkých slov.","Vezmite si slovo „koruna“. V bežnom režime je vysvetlené v niekoľkých vrstvách. V Detskom režime sa z neho stane niečo, čo dieťa pochopí hneď, napríklad zlatá ozdoba, ktorú nosí kráľ na hlave, alebo zelená čiapka z listov na vrchu stromu.","A nie je to len pre deti. Keď je slovo naozaj ťažké, jednoduché vysvetlenie je niekedy presne to, čo potrebujú aj dospelí, aby mu porozumeli.","Popri Detskom režime Gadit ukazuje aj obrázok ku každému významu, takže dieťa môže slovo nielen čítať, ale aj vidieť. Porozumenie príde rýchlejšie a vydrží dlhšie.","Detský režim je súčasťou tarifu Family, ktorý je určený pre rodiny s deťmi. Obrázok ku každému významu je aj v tarife Individual.","Ak máte nablízku dieťa, sadnite si s ním na chvíľu, zapnite Detský režim, vyhľadajte spolu slovo a pozrite sa na jeho obrázok. Takto vyzerá chvíľa, keď porozumenie príde bez námahy."],"cta":"Pozrite si Detský režim"},"summary":{"subject":"Dva týždne, jedno slovo","preheader":"Cesta, ktorou sme prešli, a dva spôsoby, ako pokračovať.","paras":["Za posledné dva týždne sme spoznali rôzne stránky slova. Všetky jeho významy a jeho históriu.","Popri tom sme spoznali funkcie, vďaka ktorým je Gadit nástrojom hlbšieho porozumenia: Detský režim a obrázok ku každému významu.","Niektoré z týchto funkcií sú otvorené každému používateľovi. Bezplatný účet zahŕňa 10 vyhľadaní denne a zošit až na 30 slov.","Ostatné odomkne Individual: neobmedzené vyhľadávanie, obrázok ku každému významu, zošit, ktorý uloží každé slovo, s inteligentným precvičovaním, hry a kvízy, Každé slovo (odfoťte stránku a ťuknite na ľubovoľné slovo), Povedz to na precvičovanie výslovnosti a zostavenie vety so spätnou väzbou. Ak sa Gadit stal súčasťou vášho dňa, práve tieto funkcie robia rozdiel.","Máte doma deti? Tarif <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> zahŕňa až 5 detí, s Detským režimom a rodičovským prehľadom.","A máme aj partnerský program: osobný odkaz, ktorý vám prinesie províziu z každej platenej registrácie, ktorá cezeň príde. Pohodlný spôsob, ako zdieľať niečo, čo máte radi, a popri tom zarobiť."],"cta":"Spoznajte Individual","ps":"P.S. Vždy radi počujeme, aké funkcie by ste chceli vidieť v Gadit. Stačí odpovedať na tento e-mail."}},
  ss: {"greetNamed":"Sawubona {name},","greetPlain":"Sawubona,","footerReason":"Utfola le-imeyili ngobe ubhalise ku-Gadit.","unsubscribeLabel":"Yekela kutfola ema-imeyili","welcome":{"subject":"Wamukelekile ku-Gadit","preheader":"Sichazamagama sinye, inhloso yinye. Kucondzisisa ligama ngalokugcwele. Nayi indlela yekucala.","paras":["Wamukelekile ku-Gadit, futsi siyabonga ngekuhlanganyela natsi.","Gadit sichazamagama lesinenhloso yinye: kucondzisisa ligama ngalokugcwele. Akusiyo inchazelo yemugca munye, akusikuhumusha nje. Tonkhe tinchazelo, tisho, imvelaphi yeligama, nendlela bantfu labalisebentisa ngayo lamuhla.","I-akhawunti yakho yamahhala inekusesha lokungu-10 ngelilanga nencwadzi yemagama lefika emagameni langu-30.","Nawucondzisisa ligama ngalokugcwele, umcondvo losemuva walo uyacaca, futsi kanye nawo indlela locabanga ngayo, lofundza ngayo nalotsatsa ngayo tincumo.","Gadit yindzawo lephilako lechubeka ikhula. Nawubona liphutsa kunobe nguyiphi inchazelo, sibonelo nobe lenye incenye, kukhona inkinobho yekubika lekufanele uyicindzetele. Licembu letfu lifundza konkhe futsi liyakulungisa.","Sewukulungele kucala?"],"cta":"Sesha ligama lakho lekucala","signOff":["Ngelutsandvo,","Licembu le-Gadit"]},"meanings":{"subject":"Ligama linye, tingcenye bewungakatiboni","preheader":"Emathulusi lamanyenti ema enchazelweni. Gadit iyachubeka kuze ligama libambeke.","exampleWord":"umoya","paras":["Tsatsa ligama umoya, ubone kutsi ligama linye lingavula njani live lonkhe.","Umoya yintfo lehamba ngaphandle, loyiva ebusweni bakho kodvwa ungayiboni. Ngiloko lesikuphefumulako kute siphile. Ngumoya wemuntfu, indlela lativa ngayo, njengalapho sitsi umuntfu unemoya lomuhle. Ngumoya lovakala endzaweni, nangabe bantfu bajabulile ndzawonye. Futsi eBhayibhelini ngumoya longabonakali, uMoya waNkulunkulu.","Ligama linye, tingcenye bewungakatiboni, ngayinye iphila emhlabeni wayo.","Ku-Gadit utfola tibonelo letintsatfu tangempela kunobe nguyiphi inchazelo. Imisho lapho ligama lisebenta khona ngempela, hhayi ngemcabango nje. Ngaleyondlela awuboni kuphela loko ligama lelikushoko, kodvwa nendlela lelivakala ngayo nalisetjentiswa.","Lena yinhlitiyo ye-Gadit. Ligama linye, ngalokugcwele, kuto tonkhe tinchazelo talo.","Sikukhutsata kutsi usesha umoya, futsi mhlawumbe nalelinye ligama locabanga kutsi sewulicondza. Ungamangala."],"cta":"Sesha umoya ubone tonkhe tingcenye","ps":"P.S. Nawutfola inchazelo lekumangalisako, kukhona inkinobho yekwabelana eceleni kwayo. Kufanele uyitfumele kumuntfu lotawuyitsandza."},"etymology":{"subject":"Lapho ligama livela khona ngempela","preheader":"Onkhe ligama linemlandvo, futsi ngalesinye sikhatsi uchaza lamuhla.","exampleWord":"umoya","paras":["Sesifike encenyeni lesiyitsandza kakhulu. Lapho ligama livela khona.","Onkhe ligama linemlandvo. Futsi ngalesinye sikhatsi lowo mlandvo uchaza lamuhla kancono kunanobe nguyiphi inchazelo.","Umoya sibonelo lesihle. Ligama lelidzala kakhulu, futsi litfolakala nakuletinye tilwimi teNingizimu ne-Afrika: ngesiZulu nesiXhosa ngu-umoya, ngeSesotho nangeXitsonga ngu-moya. Kuto tonkhe letilwimi lisho kokubili umoya lohamba ngaphandle nemoya wemuntfu.","Umoya lesiwuphefumulako ukhombisa kutsi umuntfu uyaphila. Ngaleyo ndlela ligama lelisho umoya lohamba ngaphandle lafika ekuchazeni loko lokusekhatsi kwemuntfu, indlela lativa ngayo. Kwatsi nakuhunyushwa iBhayibheli, bahumushi bakhetsa lelo ligama kuchaza uMoya waNkulunkulu, ngobe nasesiHebheru nasesiGriki ligama lelisho uMoya lisho nemoya lohamba ngaphandle.","Luhambo lonkhe egameni linye. Kusuka entfweni longeke uyibone kodvwa uyive, kuya entfweni lesekhatsi kwemuntfu.","Nawukwati loku, awulikhumbuli kuphela ligama kahle. Uyacondza nekutsi kungani tonkhe tinchazelo talo tihlangene. Atihlangananga ngengoti.","Ku-Gadit, ngaphansi kwetinchazelo telo lonkhe ligama, kukhona incenye lechaza imvelaphi yalo. Umlandvo walo, lapho livela khona. Yiloko lokuguculela sichazamagama kusuka ohlwini lwetinchazelo kube yindzaba."],"cta":"Tfola imvelaphi yeligama lelilandzelako"},"visual":{"subject":"Ligama ngemehlo emntfwana","preheader":"Simo sebantfwana: onkhe ligama lichazwa ngelulwimi lwemntfwana, ngaphandle kwekulahlekelwa kujula.","paras":["Lesinye seticelo lesitfola kakhulu besilula. Umntfwana ubuta kutsi ligama lisho kutsini, kodvwa inchazelo lesemtsetfweni ilukhuni kakhulu kuye.","Kungako Gadit inaSimo sebantfwana. Uyasivula, bese onkhe ligama lichazwa ngelulwimi lwemntfwana loneminyaka lesihlanu kuya kulishumi. Kujula lokufanako, ngaphandle kwemagama lamakhulu.","Tsatsa umoya. Esimeni lesijwayelekile uchazwa ngetingcenye letimbalwa. ESimeni sebantfwana uba yintfo umntfwana layicondza masinyane: yintfo longayiboni kodvwa uyive ebusweni bakho, futsi siyayiphefumula kute siphile.","Futsi loku akusiko kwebantfwana kuphela. Ngalesinye sikhatsi, nangabe ligama lilukhuni ngempela, inchazelo lelula iyiyo bantfu labadzala labayidzingako kute balicondze.","Eceleni kweSimo sebantfwana, Gadit ikhombisa nesitfombe sanobe nguyiphi inchazelo, kuze umntfwana abone ligama, hhayi kulifundza nje. Kucondza kufika masinyane futsi kuhlala sikhatsi lesidze.","Simo sebantfwana siyincenye yelihlelo le-Family, lelentelwe imindeni lenebantfwana. Sitfombe sanobe nguyiphi inchazelo siyeta nelihlelo le-Individual.","Nangabe kukhona umntfwana eduze, hlala naye umzuzwana, uvule Simo sebantfwana, nisesha ligama ndzawonye bese nibuka sitfombe salo. Nguloku kucondza lokufika kalula."],"cta":"Bona Simo sebantfwana"},"summary":{"subject":"Emaviki lamabili, ligama linye","preheader":"Luhambo, netindlela letimbili tekuchubeka kusukela lapha.","paras":["Emavikini lamabili lendlulile sibone tinhlangotsi letehlukene teligama. Tonkhe tinchazelo talo, nemlandvo walo.","Kanye naloko, sibone emathulusi lenta Gadit ibe lithulusi lekucondza lokujulile: Simo sebantfwana, nesitfombe sanobe nguyiphi inchazelo.","Lamanye alamathulusi avulekele wonkhe umsebentisi. I-akhawunti yamahhala inekusesha lokungu-10 ngelilanga nencwadzi yemagama lefika emagameni langu-30.","Lasele avulwa yi-<strong>Individual</strong>: kusesha lokungenamkhawulo, sitfombe sanobe nguyiphi inchazelo, incwadzi yemagama legcina onkhe ligama nekuticecesha lokuhlakaniphile, imidlalo nemibuto, Onkhe emagama (tfwebula likhasi bese ucindzetela nobe nguliphi ligama), Kusho kuticecesha kuphimisa, nekubhala umusho bese utfola imibono. Nangabe Gadit seyiyincenye yelilanga lakho, lawa ngemathulusi lenta umehluko.","Unebantfwana ekhaya? Lihlelo le-<a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> lifaka kufika kubantfwana labangu-5, neSimo sebantfwana nelibhodi lemtali.","Futsi sinaluhlelo lwebalingani: lilinki lakho lelikunika ikhomishini ngamunye umuntfu lobhalisa akhokhe ngalo. Yindlela lelula yekwabelana ngalokutsandzako, ukhokhelwe nawe."],"cta":"Yati Individual","ps":"P.S. Sihlala sitsandza kuva ngemathulusi longatsandza kuwabona ku-Gadit. Mane uphendvule le-imeyili."}},
  st: {"greetNamed":"Dumela {name},","greetPlain":"Dumela,","footerReason":"O fumana imeile ena hobane o ingodisitse ho Gadit.","unsubscribeLabel":"Emisa diimeile tsena","welcome":{"subject":"Rea o amohela ho Gadit","preheader":"Bukantswe e le nngwe, sepheo se le seng. Ho utlwisisa lentswe ho fihlela qetellong. Mona ke kamoo o qalang kateng.","paras":["Rea o amohela ho Gadit, mme re a leboha ha o re kenetse.","Gadit ke bukantswe e nang le sepheo se le seng: ho utlwisisa lentswe ka botlalo. Ha se tlhaloso ya mola o le mong, ha se phetolelo e omileng. Ke meelelo yohle, maele, tshimoloho ya lentswe, le kamoo batho ba le sebedisang kateng kajeno.","Akhaonte ya hao ya mahala e na le dipatlo tse 10 ka letsatsi le bukana ya mantswe a ka fihlang ho 30.","Ha o utlwisisa lentswe ka botlalo, mohopolo o ka morao ho lona o a hlaka, mme le wona kamoo o nahanang, o ithutang le o etsang diqeto kateng.","Gadit ke sethala se phelang se ntseng se hola. Ha o bona phoso tlhalosong efe kapa efe, mohlaleng kapa karolong e nngwe, ho na le konopo ya ho tlaleha eo ho leng bohlokwa ho e tobetsa. Sehlopha sa rona se bala tsohle mme se a di lokisa.","O se o loketse ho qala?"],"cta":"Batla lentswe la hao la pele","signOff":["Ka lerato,","Sehlopha sa Gadit"]},"meanings":{"subject":"Lentswe le le leng, dikarolo tseo o neng o sa di bone","preheader":"Disebediswa tse ngata di emisa tlhalosong. Gadit e tswela pele ho fihlela lentswe le dula.","exampleWord":"botho","paras":["Nka lentswe botho, mme o bone kamoo lentswe le le leng le ka bulang lefatshe lohle kateng.","Botho ke ho ba motho, seo re tshwanang ka sona kaofela. Ke mosa le tlhompho eo o e bontshang ba bang: ha re re motho o na le botho, re bolela hore o mosa, o a thusa, o a hlompha. Ke boitshwaro bo botle: motho ya sa itshwareng hantle, re re ha a na botho. Mme ke mohopolo wa ho phela mmoho, o hlahang maeleng a reng: motho ke motho ka batho.","Lentswe le le leng, dikarolo tseo o neng o sa di bone, e nngwe le e nngwe e phela lefatsheng la yona.","Ho Gadit o fumana mehlala e meraro ya nnete bakeng sa tlhaloso ka nngwe. Dipolelo tseo ho tsona lentswe le sebetsang ka nnete, e seng ka kgopolo feela. Kahoo ha o bone feela seo lentswe le se bolelang, empa le kamoo le utlwahalang kateng ha le sebediswa.","Ena ke pelo ya Gadit. Lentswe le le leng, ho fihlela qetellong, ditlhalosong tsohle tsa lona.","Re o kgothaletsa ho batla botho, mme mohlomong le lentswe le leng leo o nahanang hore o se o le utlwisisa. O ka makala."],"cta":"Batla botho mme o bone dikarolo tsohle","ps":"P.S. Ha o fumana moelelo o o makatsang, ho na le konopo ya ho arolelana pela wona. Ho bohlokwa ho o romella motho ya tla o thabela."},"etymology":{"subject":"Moo lentswe le tswang teng ka nnete","preheader":"Lentswe le leng le le leng le na le nalane, mme ka nako e nngwe e hlalosa kajeno.","exampleWord":"botho","paras":["Re fihlile karolong eo re e ratang ka ho fetisisa. Moo lentswe le tswang teng.","Lentswe le leng le le leng le na le nalane. Mme ka nako e nngwe nalane eo e hlalosa kajeno hantle ho feta tlhaloso efe kapa efe.","Botho ke mohlala o motle. Motso wa lona ke -tho, motso o tshwanang le wa motho le batho. Ha o kenya bo- ka pele, lentswe le bolelang motho le fetoha lentswe le bolelang seo ho ba motho ho leng sona.","Motso ona ke wa kgale haholo, mme o arolelanwa ke dipuo tse makgolo tsa Afrika. Ka Sezulu ke umuntu le ubuntu, ka Xitsonga ke munhu, ka Seswahili ke mtu. Le lebitso la lelapa lohle la dipuo tsena, dipuo tsa Bantu, le tswa motsong ona: lekgolong la bo19 la dilemo, setsebi sa dipuo se ile sa kgetha lentswe bantu, le bolelang batho, ho reha lelapa lena.","Leeto lohle ka lentswe le le leng. Ho tloha ho motho a le mong, ho ya kamoo re tshwarang ba bang kateng, ho fihla mohopolong wa ho phela mmoho.","Ha o tseba sena, ha o hopole feela lentswe hantle. O boetse o utlwisisa hore na hobaneng meelelo ya lona yohle e hokahane. Ha e a ba mmoho ka phoso.","Ho Gadit, ka tlasa ditlhaloso tsa lentswe le leng le le leng, ho na le karolo e hlalosang tshimoloho ya lona. Nalane ya lona, moo le tswang teng. Ke yona e fetolang bukantswe ho tloha lenaneng la ditlhaloso ho ba pale."],"cta":"Fumana tshimoloho ya lentswe le latelang"},"visual":{"subject":"Lentswe ka mahlo a ngwana","preheader":"Mokgwa wa bana: lentswe le leng le le leng le hlaloswa ka puo ya ngwana, ntle le ho lahlehelwa ke botebo.","paras":["E nngwe ya dikopo tseo re di fumanang haholo e ne e le bonolo. Ngwana o botsa hore lentswe le bolelang, mme tlhaloso ya semmuso e thata haholo ho yena.","Ke ka hona Gadit e nang le Mokgwa wa bana. O o bulela, mme lentswe le leng le le leng le hlaloswa ka puo ya ngwana wa dilemo tse hlano ho isa ho tse leshome. Botebo bo tshwanang, ntle le mantswe a maholo.","Nka botho. Mokgweng o tlwaelehileng bo hlaloswa ka dikarolo tse mmalwa. Mokgweng wa bana bo fetoha ntho eo ngwana a e utlwisisang hang: ke ha o le mosa ho batho, o ba thusa mme o ba hlompha, hobane re a hlokana kaofela.","Mme sena ha se sa bana feela. Ka nako e nngwe, ha lentswe le le thata ka nnete, tlhaloso e bonolo ke yona eo le batho ba baholo ba e hlokang ho le utlwisisa.","Pela Mokgwa wa bana, Gadit e boetse e bontsha setshwantsho bakeng sa moelelo o mong le o mong, e le hore ngwana a bone lentswe, eseng ho le bala feela. Kutlwisiso e fihla kapele mme e dula nako e telele.","Mokgwa wa bana ke karolo ya moralo wa Family, o etseditsweng malapa a nang le bana. Setshwantsho bakeng sa moelelo o mong le o mong se boetse se tla le moralo wa Individual.","Haeba ho na le ngwana haufi, dula le yena motsotso, bula Mokgwa wa bana, le batle lentswe mmoho mme le shebe setshwantsho sa lona. Ena ke kamoo kutlwisiso e tlang ntle le boima e shebahalang kateng."],"cta":"Bona Mokgwa wa bana"},"summary":{"subject":"Dibeke tse pedi, lentswe le le leng","preheader":"Leeto, le ditsela tse pedi tsa ho tswela pele ho tloha mona.","paras":["Dibekeng tse pedi tse fetileng re bone mahlakore a fapaneng a lentswe. Meelelo yohle ya lona, le nalane ya lona.","Hammoho le seo, re bone disebediswa tse etsang Gadit sesebediswa sa kutlwisiso e tebileng: Mokgwa wa bana, le setshwantsho bakeng sa moelelo o mong le o mong.","Tse ding tsa disebediswa tsena di bulehetse mosebedisi e mong le e mong. Akhaonte ya mahala e na le dipatlo tse 10 ka letsatsi le bukana ya mantswe a ka fihlang ho 30.","Tse ding kaofela di bulwa ke <strong>Individual</strong>: dipatlo tse se nang moeli, setshwantsho bakeng sa moelelo o mong le o mong, bukana e bolokang lentswe le leng le le leng ka boikwetliso bo bohlale, dipapadi le dikwisi, Lentswe ka leng (nka foto ya leqephe mme o tobetse lentswe lefe kapa lefe), E bue bakeng sa ho ikwetlisa ho bitsa mantswe, le ho ngola polelo mme o fumane maikutlo. Haeba Gadit e se e le karolo ya letsatsi la hao, tsena ke disebediswa tse etsang phapang.","Na o na le bana lapeng? Moralo wa <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> o akaretsa ho fihla ho bana ba 5, ka Mokgwa wa bana le leqephe la taolo la motswadi.","Mme re na le lenaneo la balekane: lehokela la hao le o fang komishene bakeng sa motho e mong le e mong ya ingodisang ka tefo ka lona. Tsela e bonolo ya ho arolelana seo o se ratang, mme o fumane le tjhelete."],"cta":"Tseba Individual","ps":"P.S. Re lakatsa ho utlwa ka disebediswa tseo o ka ratang ho di bona ho Gadit. Araba feela imeile ena."}},
  sw: {"greetNamed":"Habari {name},","greetPlain":"Habari,","footerReason":"Unapokea barua pepe hii kwa sababu ulijisajili kwenye Gadit.","unsubscribeLabel":"Jiondoe","welcome":{"subject":"Karibu Gadit","preheader":"Kamusi moja, lengo moja. Kuelewa neno hadi mwisho. Hivi ndivyo unavyoanza.","paras":["Karibu Gadit, na asante kwa kujiunga nasi.","Gadit ni kamusi yenye lengo moja: kuelewa neno hadi mwisho. Si maana ya mstari mmoja, si tafsiri kavu. Maana zake zote, nahau, asili ya neno, na jinsi watu wanavyolitumia kweli leo.","Akaunti yako ya bure inakupa utafutaji 10 kwa siku na daftari la hadi maneno 30.","Unapolielewa neno kikamilifu, wazo lililo nyuma yake linakuwa wazi, na pamoja nalo jinsi unavyofikiri, unavyojifunza na unavyofanya maamuzi.","Gadit ni jukwaa hai linaloendelea kukua. Ukiona kosa katika maana yoyote, mfano au sehemu nyingine, kuna kitufe cha kuripoti kinachostahili kubonyezwa. Timu yetu inasoma kila kitu na kukirekebisha.","Uko tayari kuanza?"],"cta":"Tafuta neno lako la kwanza","signOff":["Kila la heri,","Timu ya Gadit"]},"meanings":{"subject":"Neno moja, tabaka ambazo hujaziona","preheader":"Zana nyingi huishia kwenye maana. Gadit inaendelea hadi neno likae akilini.","exampleWord":"roho","paras":["Chukua neno roho, uone jinsi neno moja linavyoweza kufungua ulimwengu mzima.","Roho ni nafsi ya mtu, sehemu isiyoonekana inayomfanya awe hai. Roho ni uhai wenyewe, kama daktari anapookoa roho ya mgonjwa. Roho ni moyo na tabia ya mtu: mtu mwenye roho nzuri hupenda kusaidia, na mwenye roho mbaya huwaonea wengine wivu. Roho ni hali ya ndani, kama mtu anapokuwa na roho juu kwa wasiwasi. Na katika imani, ni Roho Mtakatifu.","Neno moja, tabaka ambazo hukuziona ndani yake, kila moja ikiishi katika ulimwengu wake.","Katika Gadit utapata mifano mitatu halisi kwa kila maana. Sentensi ambazo neno linafanya kazi katika maisha halisi, si kwa nadharia. Kwa njia hiyo unaona si tu neno linamaanisha nini, bali pia jinsi linavyosikika linapotumiwa.","Huu ndio moyo wa Gadit. Neno moja, hadi mwisho, katika maana zake zote.","Tunapendekeza utafute roho, na labda neno lingine unalofikiri tayari unalielewa. Huenda ukashangaa."],"cta":"Tafuta roho uone sura zake zote","ps":"P.S. Ukipata maana inayokushangaza, kuna kitufe cha kushiriki karibu nayo. Inafaa kumtumia mtu atakayeithamini."},"etymology":{"subject":"Neno linatoka wapi hasa","preheader":"Kila neno lina historia, na wakati mwingine historia hiyo inaeleza leo.","exampleWord":"roho","paras":["Tumefika kwenye sehemu tunayoipenda zaidi. Neno linatoka wapi.","Kila neno lina historia. Na wakati mwingine historia hiyo inaeleza hali ya leo vizuri kuliko maana yoyote.","Roho ni mfano mzuri. Neno hili liliingia katika Kiswahili kutoka Kiarabu, kutoka neno rūḥ, lenye maana ya roho na pumzi ya uhai. Katika Kiarabu, linatokana na mzizi uleule unaotoa neno rīḥ, yaani upepo. Kwa msingi wake, roho inahusu hewa inayotembea, yaani pumzi.","Kutoka kwenye pumzi halisi ilizaliwa dhana ya nguvu ya uhai iliyo ndani yetu, pumzi inayoufanya mwili uishi. Na kutoka hapo likakua jambo la kina zaidi: roho ya mtu, kiini chake cha ndani, moyo wake na tabia yake.","Safari nzima ndani ya neno moja. Kutoka kitu cha kimwili kabisa, pumzi, hadi kitu kisicho cha kimwili kabisa, roho ya mtu. Yote katika neno moja ambalo limekaa nasi kwa karne nyingi.","Ukishajua hili, hulikumbuki tu neno vizuri zaidi. Unaelewa pia kwa nini maana zake zote zimeunganika. Hazikukaa pamoja kwa bahati.","Katika Gadit, chini ya maana za kila neno, kuna sehemu inayoeleza asili yake. Historia yake, mahali lilipotoka. Hiyo ndiyo inayoigeuza kamusi kutoka orodha ya maana kuwa hadithi."],"cta":"Gundua asili ya neno linalofuata"},"visual":{"subject":"Neno kwa macho ya mtoto","preheader":"Hali ya Watoto: kila neno linaelezwa kwa lugha ya mtoto, bila kupoteza kina chake.","paras":["Moja ya maombi tuliyopokea mara nyingi zaidi lilikuwa rahisi. Mtoto anauliza neno linamaanisha nini, na maana rasmi ni ngumu mno kwake.","Ndiyo sababu Gadit ina Hali ya Watoto. Iwashe, na kila neno linaelezwa kwa lugha ya mtoto wa miaka mitano hadi kumi. Kina kilekile, bila maneno magumu.","Chukua neno roho. Katika hali ya kawaida, linaelezwa kwa tabaka kadhaa. Katika Hali ya Watoto, linakuwa kitu ambacho mtoto anakielewa mara moja, kama mtu mwenye roho nzuri: mtu anayependa kuwasaidia wengine na kuwatendea mema.","Na hii si kwa watoto tu. Wakati mwingine, neno linapokuwa gumu kweli, maelezo rahisi ndiyo hasa watu wazima wanayohitaji ili kulielewa pia.","Pamoja na Hali ya Watoto, Gadit pia inaonyesha picha kwa kila maana, ili mtoto aweze kuliona neno, si kulisoma tu. Uelewa unakuja haraka zaidi na unadumu muda mrefu zaidi.","Hali ya Watoto ni sehemu ya mpango wa Family, uliotengenezwa kwa ajili ya familia zenye watoto. Picha kwa kila maana inapatikana pia katika mpango wa Individual.","Kama kuna mtoto karibu nawe, keti naye kwa dakika moja, washa Hali ya Watoto, tafuteni neno pamoja na mtazame picha yake. Hivi ndivyo wakati wa kuelewa bila juhudi unavyoonekana."],"cta":"Tazama Hali ya Watoto"},"summary":{"subject":"Wiki mbili, neno moja","preheader":"Safari, na njia mbili za kuendelea kutoka hapa.","paras":["Katika wiki mbili zilizopita tumefahamu pande mbalimbali za neno. Maana zake zote, na historia yake.","Pamoja na hayo, tumefahamu vipengele vinavyoifanya Gadit kuwa zana ya kuelewa kwa kina zaidi: Hali ya Watoto, na picha kwa kila maana.","Baadhi ya vipengele hivi viko wazi kwa kila mtumiaji. Akaunti ya bure inakupa utafutaji 10 kwa siku na daftari la hadi maneno 30.","Vilivyobaki vinafunguliwa na Individual: utafutaji bila kikomo, picha kwa kila maana, daftari linalohifadhi kila neno pamoja na mazoezi mahiri, michezo na maswali, Kila neno (piga picha ya ukurasa na gusa neno lolote), Litamke kwa mazoezi ya matamshi, na kutunga sentensi na kupata maoni. Kama Gadit imekuwa sehemu ya siku zako, hivi ndivyo vipengele vinavyoleta tofauti.","Una watoto nyumbani? Mpango wa <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> unajumuisha hadi watoto 5, pamoja na Hali ya Watoto na ubao wa mzazi.","Pia tuna mpango wa washirika: kiungo binafsi kinachokuletea kamisheni kwa kila usajili wa kulipia unaokuja kupitia kiungo hicho. Njia rahisi ya kushiriki kitu unachokipenda, na kupata kipato njiani."],"cta":"Ifahamu Individual","ps":"P.S. Tunapenda kusikia kila wakati ni vipengele gani ungependa kuona katika Gadit. Jibu tu barua pepe hii."}},
  th: {"greetNamed":"สวัสดี {name},","greetPlain":"สวัสดี,","footerReason":"คุณได้รับอีเมลนี้เพราะคุณสมัครใช้งาน Gadit","unsubscribeLabel":"ยกเลิกการรับอีเมล","welcome":{"subject":"ยินดีต้อนรับสู่ Gadit","preheader":"พจนานุกรมหนึ่งเล่ม ภารกิจเดียว คือเข้าใจคำหนึ่งคำอย่างถ่องแท้ มาดูวิธีเริ่มต้นกัน","paras":["ยินดีต้อนรับสู่ Gadit และขอบคุณที่มาร่วมกับเรา","Gadit คือพจนานุกรมที่มีภารกิจเดียว คือเข้าใจคำหนึ่งคำอย่างถ่องแท้ ไม่ใช่คำนิยามสั้น ๆ บรรทัดเดียว และไม่ใช่คำแปลแห้ง ๆ แต่เป็นทุกความหมาย สำนวน ที่มาของคำ และวิธีที่ผู้คนใช้คำนั้นจริง ๆ ในทุกวันนี้","บัญชีฟรีของคุณค้นหาได้วันละ 10 ครั้ง และมีสมุดคำศัพท์ได้สูงสุด 30 คำ","เมื่อคุณเข้าใจคำหนึ่งคำอย่างครบถ้วน ความคิดที่อยู่เบื้องหลังคำนั้นก็จะชัดเจน และวิธีที่คุณคิด เรียนรู้ และตัดสินใจก็จะชัดเจนขึ้นไปด้วย","Gadit เป็นแพลตฟอร์มที่มีชีวิตและเติบโตอยู่เสมอ ถ้าคุณพบข้อผิดพลาดในคำนิยาม ตัวอย่าง หรือส่วนใดก็ตาม มีปุ่มแจ้งปัญหาที่ควรกด ทีมของเราอ่านทุกข้อความและแก้ไขให้","พร้อมเริ่มต้นหรือยัง?"],"cta":"ค้นหาคำแรกของคุณ","signOff":["ด้วยความปรารถนาดี,","ทีม Gadit"]},"meanings":{"subject":"คำเดียว หลายชั้นที่คุณยังไม่เคยเห็น","preheader":"เครื่องมือส่วนใหญ่หยุดอยู่ที่คำนิยาม Gadit ไปต่อจนคุณจำได้","exampleWord":"กรรม","paras":["ลองดูคำว่า “กรรม” แล้วคุณจะเห็นว่าคำเดียวเปิดโลกได้ทั้งใบ","กรรมคือการกระทำ ทั้งดีและไม่ดี อย่างในคำว่า กรรมดี และ กรรมชั่ว กรรมคือผลที่ตามมาจากการกระทำ อย่างที่เราพูดกันว่า ทำกรรมใดไว้ ย่อมได้รับผลนั้น กรรมคือคำอุทานเวลาเจอเรื่องไม่ดี อย่าง “กรรมจริง ๆ เลย” ในไวยากรณ์ กรรมคือสิ่งที่ถูกกระทำในประโยค เรียงเป็น ประธาน กริยา กรรม และในภาษาสุภาพ ถึงแก่กรรม หมายถึงเสียชีวิต","คำเดียว แต่มีหลายชั้นที่คุณอาจไม่เคยเห็นในคำนี้ แต่ละชั้นอยู่ในโลกของตัวเอง","ใน Gadit คุณจะได้ตัวอย่างจริงสามตัวอย่างสำหรับทุกคำนิยาม เป็นประโยคที่คำนั้นถูกใช้จริง ไม่ใช่แค่ในทฤษฎี คุณจึงไม่ได้เห็นแค่ว่าคำนั้นหมายถึงอะไร แต่ยังได้เห็นว่าเวลาใช้จริงคำนั้นฟังเป็นอย่างไร","นี่คือหัวใจของ Gadit คำหนึ่งคำ ลึกจนสุด ครบทุกความหมาย","เราขอชวนให้คุณลองค้นหาคำว่า “กรรม” และอาจลองอีกสักคำที่คุณคิดว่าเข้าใจดีอยู่แล้ว คุณอาจประหลาดใจ"],"cta":"ค้นหา “กรรม” แล้วดูทุกแง่มุม","ps":"ป.ล. เมื่อคุณเจอความหมายที่น่าประหลาดใจ จะมีปุ่มแชร์อยู่ข้าง ๆ ส่งต่อให้คนที่น่าจะชอบได้เลย"},"etymology":{"subject":"คำหนึ่งคำมาจากไหนกันแน่","preheader":"ทุกคำมีอดีต และบางครั้งอดีตนั้นก็อธิบายปัจจุบันได้","exampleWord":"กรรม","paras":["มาถึงส่วนที่เราชอบที่สุดแล้ว นั่นคือที่มาของคำ","ทุกคำมีอดีต และบางครั้งอดีตนั้นก็อธิบายปัจจุบันได้ดีกว่าคำนิยามใด ๆ","กรรมเป็นตัวอย่างที่งดงาม คำนี้มาจากภาษาสันสกฤต กรฺม (karman) ซึ่งแปลตรงตัวว่า การกระทำ มาจากรากศัพท์ที่แปลว่า ทำ ส่วนในภาษาบาลีคือ กมฺม ความหมายเดิมเรียบง่ายมาก คือสิ่งที่คนคนหนึ่งลงมือทำ ร่องรอยนี้ยังเห็นได้ในคำอย่าง กรรมกร ซึ่งก็คือผู้ทำงานใช้แรง","จากการกระทำธรรมดา ๆ ความหมายเติบโตไปสู่แนวคิดทางศาสนาว่า การกระทำทุกอย่างย่อมมีผลตามมา ส่วนในไวยากรณ์ คำนี้ใช้เรียกสิ่งที่ถูกกระทำในประโยค ซึ่งไวยากรณ์สันสกฤตโบราณก็ใช้คำนี้ในความหมายนี้มาก่อนแล้ว","การเดินทางทั้งหมดอยู่ในคำเดียว จากสิ่งที่จับต้องได้ที่สุด คือการลงมือทำ ไปสู่สิ่งที่เป็นนามธรรมที่สุด คือผลของการกระทำที่ติดตามชีวิตคน ทั้งหมดอยู่ในคำเดียวที่อยู่กับเรามานับพันปี","เมื่อรู้อย่างนี้แล้ว คุณไม่เพียงจำคำนี้ได้ดีขึ้น แต่ยังเข้าใจด้วยว่าทำไมทุกความหมายของคำนี้จึงเชื่อมโยงกัน ความหมายเหล่านี้ไม่ได้มาอยู่รวมกันโดยบังเอิญ","ใน Gadit ใต้คำนิยามของแต่ละคำ จะมีส่วนที่อธิบายที่มาของคำ ภูมิหลังทางประวัติศาสตร์ว่าคำนั้นมาจากไหน สิ่งนี้เองที่เปลี่ยนพจนานุกรมจากรายการคำนิยามให้กลายเป็นเรื่องเล่า"],"cta":"ค้นพบที่มาของคำถัดไป"},"visual":{"subject":"คำหนึ่งคำ ในระดับสายตาเด็ก","preheader":"โหมดเด็ก: ทุกคำอธิบายด้วยภาษาของเด็ก โดยไม่สูญเสียความลึก","paras":["หนึ่งในคำขอที่เราได้รับบ่อยที่สุดนั้นเรียบง่าย เด็กถามว่าคำนี้แปลว่าอะไร แต่คำนิยามทางการซับซ้อนเกินไปสำหรับเขา","นั่นคือเหตุผลที่ Gadit มีโหมดเด็ก เมื่อเปิดใช้ ทุกคำจะถูกอธิบายด้วยภาษาของเด็กอายุห้าถึงสิบขวบ ลึกเท่าเดิม แต่ไม่มีคำยาก","ลองดูคำว่า “แรงโน้มถ่วง” ในโหมดปกติ คำนี้อธิบายด้วยฟิสิกส์และแรงดึงดูดระหว่างมวล ในโหมดเด็ก คำนี้กลายเป็นสิ่งที่เด็กเข้าใจได้ทันที คือแรงที่มองไม่เห็นซึ่งดึงทุกอย่างลงสู่พื้น ลูกบอลที่โยนขึ้นไปจึงตกลงมาเสมอ","และไม่ใช่สำหรับเด็กเท่านั้น บางครั้งเมื่อคำหนึ่งยากจริง ๆ คำอธิบายง่าย ๆ ก็คือสิ่งที่ผู้ใหญ่ต้องการเพื่อเข้าใจคำนั้นเช่นกัน","นอกจากโหมดเด็ก Gadit ยังแสดงภาพสำหรับทุกความหมาย เด็กจึงได้เห็นคำนั้นด้วย ไม่ใช่แค่อ่าน ความเข้าใจมาถึงเร็วขึ้นและอยู่นานขึ้น","โหมดเด็กเป็นส่วนหนึ่งของแพ็กเกจ Family ที่ออกแบบมาสำหรับครอบครัวที่มีเด็ก ส่วนภาพสำหรับทุกความหมายมีในแพ็กเกจ Individual ด้วย","ถ้ามีเด็กอยู่ใกล้ ๆ ลองนั่งกับเขาสักนาที เปิดโหมดเด็ก ค้นหาคำด้วยกัน แล้วดูภาพของคำนั้น นี่แหละคือช่วงเวลาที่ความเข้าใจมาถึงอย่างง่ายดาย"],"cta":"ดูโหมดเด็ก"},"summary":{"subject":"สองสัปดาห์ คำหนึ่งคำ","preheader":"เส้นทางที่ผ่านมา และสองทางที่จะไปต่อจากนี้","paras":["ตลอดสองสัปดาห์ที่ผ่านมา เราได้ทำความรู้จักแง่มุมต่าง ๆ ของคำหนึ่งคำ ทั้งทุกความหมายและประวัติของคำนั้น","ควบคู่กันไป เราได้รู้จักฟีเจอร์ที่ทำให้ Gadit เป็นเครื่องมือสำหรับความเข้าใจที่ลึกขึ้น คือโหมดเด็ก และภาพสำหรับทุกความหมาย","บางฟีเจอร์เปิดให้ผู้ใช้ทุกคน บัญชีฟรีค้นหาได้วันละ 10 ครั้ง และมีสมุดคำศัพท์ได้สูงสุด 30 คำ","ฟีเจอร์ที่เหลือเปิดใช้ได้กับ Individual: ค้นหาไม่จำกัด ภาพสำหรับทุกความหมาย สมุดคำศัพท์ที่บันทึกทุกคำพร้อมการฝึกอัจฉริยะ เกมและแบบทดสอบ “ทุกคำ” (ถ่ายภาพหน้าเอกสาร แล้วแตะคำไหนก็ได้) “ลองพูด” สำหรับฝึกออกเสียง และการแต่งประโยคพร้อมคำแนะนำ ถ้า Gadit กลายเป็นส่วนหนึ่งของกิจวัตรประจำวันของคุณแล้ว ฟีเจอร์เหล่านี้คือสิ่งที่สร้างความแตกต่าง","มีเด็ก ๆ ที่บ้านใช่ไหม? แพ็กเกจ <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> รองรับเด็กได้สูงสุด 5 คน พร้อมโหมดเด็กและบอร์ดผู้ปกครอง","และเรายังมีโปรแกรมพาร์ทเนอร์ด้วย: ลิงก์ส่วนตัวที่ให้ค่าคอมมิชชันกับคุณทุกครั้งที่มีคนสมัครแบบชำระเงินผ่านลิงก์นั้น เป็นวิธีง่าย ๆ ในการแบ่งปันสิ่งที่คุณรัก และได้รายได้ไปพร้อมกัน"],"cta":"ทำความรู้จัก Individual","ps":"ป.ล. เรายินดีรับฟังเสมอว่าคุณอยากเห็นฟีเจอร์อะไรใน Gadit แค่ตอบกลับอีเมลนี้ได้เลย"}},
  tn: {"greetNamed":"Dumela {name},","greetPlain":"Dumela,","footerReason":"O amogela imeile e ka gonne o ikwadisitse mo Gadit.","unsubscribeLabel":"Emisa diimeile","welcome":{"subject":"Re a go amogela mo Gadit","preheader":"Thanodi e le nngwe, boikaelelo bo le bongwe. Go tlhaloganya lefoko go fitlha kwa bofelong. Simolola jaana.","paras":["Re a go amogela mo Gadit, mme re a leboga go tsena.","Gadit ke thanodi e e nang le boikaelelo bo le bongwe: go tlhaloganya lefoko go fitlha kwa bofelong. E seng tlhaloso ya mola o le mongwe, e seng phetolelo e e omileng. Ditlhaloso tsotlhe, diane, tshimologo ya lefoko, le ditsela tse batho ba le dirisang ka tsone gompieno.","Akhaonto ya gago ya mahala e akaretsa dipatlo di le 10 ka letsatsi le bukana ya go fitlha mafoko a le 30.","Fa o tlhaloganya lefoko ka botlalo, kakanyo e e kwa morago ga lone e a phepafala, mme le yone tsela e o akanyang, o ithutang le o tsayang ditshwetso ka yone.","Gadit ke polatefomo e e tshelang e e tswelelang go gola. Fa o bona phoso mo tlhalosong nngwe le nngwe, mo sekaing kgotsa mo karolong e nngwe, go na le konopo ya go bega e e tshwanetseng go tobediwa. Setlhopha sa rona se bala sengwe le sengwe mme se a se baakanya.","A o ipaakanyeditse go simolola?"],"cta":"Batla lefoko la gago la ntlha","signOff":["Ka tlotlo,","Setlhopha sa Gadit"]},"meanings":{"subject":"Lefoko le le lengwe, dikarolo tse o iseng o di bone","preheader":"Didiriswa di le dintsi di emela mo tlhalosong. Gadit e tswelela go fitlha lefoko le nna.","exampleWord":"mowa","paras":["Tsaya lefoko \"mowa\", mme o bone kafa lefoko le le lengwe le ka bulang lefatshe lotlhe ka teng.","Mowa ke se motho a se hemang, se se mo tshedisang. Ke mowa wa motho kwa teng, pelo le semelo sa gagwe. Ke mowa o o mo gare ga batho, jaaka mowa o o molemo mo lelapeng kgotsa mo setlhopheng. Mme kwa kerekeng, ke Mowa o o Boitshepo.","Lefoko le le lengwe, dikarolo tse o iseng o di bone mo go lone, nngwe le nngwe e tshela mo lefatsheng la yone.","Mo Gadit o tla bona dikai di le tharo tsa mmatota tsa tlhaloso nngwe le nngwe. Dipolelo tse lefoko le dirang mo go tsone mo botshelong, e seng mo thutong fela. Ka tsela e o bona e seng fela se lefoko le se rayang, mme le kafa le utlwalang ka teng fa le dirisiwa.","Se ke pelo ya Gadit. Lefoko le le lengwe, go fitlha kwa bofelong, mo ditlhalosong tsotlhe tsa lone.","Re go gakolola go batla \"mowa\", gongwe le lefoko le lengwe le o akanyang gore o setse o le itse sentle. O ka gakgamala."],"cta":"Batla lefoko \"mowa\"","ps":"P.S. Fa o bona tlhaloso e e go gakgamatsang, go na le konopo ya go abelana fa thoko ga yone. Go botlhokwa go e romela mongwe yo o tla e itumelelang."},"etymology":{"subject":"Lefoko le tswa kae tota","preheader":"Lefoko lengwe le lengwe le na le hisitori, mme ka dinako dingwe e tlhalosa gompieno.","exampleWord":"mowa","paras":["Re gorogile kwa karolong e re e ratang thata. Kwa lefoko le tswang teng.","Lefoko lengwe le lengwe le na le hisitori. Mme ka dinako dingwe hisitori eo e tlhalosa gompieno botoka go feta tlhaloso nngwe le nngwe.","Mowa ke sekai se se ntle. Lefoko le ga se la Setswana fela. Ka Sesotho le Sepedi ke moya, mme ka isiZulu le isiXhosa ke umoya. Mo dipuong tseo, lefoko le gape le raya phefo le se re se hemang. Fa dipuo tsa losika lo le lengwe di na le lefoko le le tshwanang ka tsela e, seo se bontsha gore le tswa kwa mogologolong wa tsone o le mongwe wa bogologolo, pele dipuo tseo di kgaogana.","Mme bona kafa ditlhaloso tsa lone di golaganeng ka teng. Tsotlhe ke selo se o sa kgoneng go se bona ka matlho mme o a se utlwa: se o se hemang, se se tshedisang motho. Go tswa foo, go bonolo go bona kafa lefoko le fitlhelelang le se se sa bonaleng mo teng ga motho, mowa wa gagwe, le mowa o o mo gare ga batho.","Setswana ke nngwe ya dipuo tsa ntlha tsa Aforika tse di nnileng le Baebele yotlhe, e e ranotsweng ke Robert Moffat mme ya gatisiwa kwa Kuruman ka 1857.","Leeto lotlhe mo lefokong le le lengwe. Go tswa mo seleng se se tsenang se bo se tswa mo makgwafong a gago, go ya kwa seleng se se sa bonaleng go gaisa tsotlhe, mowa wa motho.","Fa o setse o itse se, ga o gopole fela lefoko botoka. O tlhaloganya gape gore ke ka ntlha yang fa ditlhaloso tsotlhe tsa lone di golagane. Ga di a kopana fela ka kotsi.","Mo Gadit, ka fa tlase ga ditlhaloso tsa lefoko lengwe le lengwe, go na le karolo e e tlhalosang tshimologo ya lone. Hisitori ya lone, kwa le tswang teng. Ke sone se se fetolang thanodi go tswa mo lenaneong la ditlhaloso go nna kgang."],"cta":"Ribolola tshimologo ya lefoko le le latelang"},"visual":{"subject":"Lefoko ka matlho a ngwana","preheader":"Mokgwa wa bana: lefoko lengwe le lengwe le tlhalosiwa ka puo ya ngwana, kwa ntle ga go latlhegelwa ke boteng.","paras":["Nngwe ya dikopo tse re di amogetseng gantsi e ne e le bonolo. Ngwana o botsa gore lefoko le raya eng, mme tlhaloso ya semmuso e thata thata mo go ene.","Ke ka moo Gadit e nang le Mokgwa wa bana. O bule, mme lefoko lengwe le lengwe le tlhalosiwa ka puo ya ngwana wa dingwaga di le tlhano go ya go di le lesome. Boteng jo bo tshwanang, kwa ntle ga mafoko a magolo.","Tsaya lefoko \"mowa\". Mo mokgweng o o tlwaelegileng, le tlhalosiwa ka dikarolo di le mmalwa. Mo Mokgweng wa bana, le fetoga selo se ngwana a se tlhaloganyang ka bonako, jaaka se se tsenang se bo se tswa mo makgwafong a gago fa o hema.","Mme se ga se sa bana fela. Ka dinako dingwe, fa lefoko le le thata tota, tlhaloso e e bonolo ke yone e le batho ba bagolo ba e tlhokang go le tlhaloganya.","Fa thoko ga Mokgwa wa bana, Gadit e bontsha gape setshwantsho sa tlhaloso nngwe le nngwe, gore ngwana a bone lefoko a bo a le bala. Tlhaloganyo e tla ka bonako mme e nna lobaka lo loleele.","Mokgwa wa bana ke karolo ya leano la Family, le le diretsweng malapa a a nang le bana. Setshwantsho sa tlhaloso nngwe le nngwe se tla gape le leano la Individual.","Fa go na le ngwana gaufi, nna le ene motsotso, o bule Mokgwa wa bana, lo batle lefoko mmogo mme lo lebe setshwantsho sa lone. Ke kafa motsotso wa tlhaloganyo e e bonolo o lebegang ka teng."],"cta":"Bona Mokgwa wa bana"},"summary":{"subject":"Dibeke di le pedi, lefoko le le lengwe","preheader":"Leeto, le ditsela di le pedi tsa go tswelela go tswa fano.","paras":["Mo dibekeng di le pedi tse di fetileng re itsile mahlakore a a farologaneng a lefoko. Ditlhaloso tsotlhe tsa lone, le hisitori ya lone.","Fa thoko ga seo, re itsile dikarolo tse di dirang Gadit sedirisiwa sa tlhaloganyo e e tseneletseng: Mokgwa wa bana, le setshwantsho sa tlhaloso nngwe le nngwe.","Dingwe tsa dikarolo tse di buletswe modirisi mongwe le mongwe. Akhaonto ya mahala e akaretsa dipatlo di le 10 ka letsatsi le bukana ya go fitlha mafoko a le 30.","Tse dingwe di bulwa ka Individual: dipatlo kwa ntle ga selekanyo, setshwantsho sa tlhaloso nngwe le nngwe, bukana e e bolokang lefoko lengwe le lengwe ka boikatiso jo botlhale, metshameko le ditlhatlhobo, Lefoko Lengwe le Lengwe (tsaya setshwantsho sa tsebe mme o tobetse lefoko lefe kana lefe), E bue go ikatisa go bitsa mafoko, le go kwala polelo o amogele maikutlo. Fa Gadit e setse e le karolo ya botshelo jwa gago jwa letsatsi le letsatsi, tse ke dikarolo tse di dirang pharologano.","A go na le bana kwa gae? Leano la <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> le akaretsa bana go fitlha ba le 5, ka Mokgwa wa bana le lebota la motsadi.","Mme re na le lenaneo la balekane: linki ya gago ya botho e e go neelang khomishene mo kwadisong nngwe le nngwe e e duelelwang e e tlang ka yone. Tsela e e bonolo ya go abelana ka sengwe se o se ratang, mme o amogele madi mo tseleng."],"cta":"Itse Individual","ps":"P.S. Ka metlha re itumelela go utlwa ka didirisiwa tse o ka ratang go di bona mo Gadit. Araba fela imeile e."}},
  tr: {"greetNamed":"Merhaba {name},","greetPlain":"Merhaba,","footerReason":"Bu e-postayı Gadit'e kaydolduğun için alıyorsun.","unsubscribeLabel":"Abonelikten çık","welcome":{"subject":"Gadit'e hoş geldin","preheader":"Bir sözlük, bir görev. Bir kelimeyi sonuna kadar çözmek. İşte nasıl başlayacağın.","paras":["Gadit'e hoş geldin, aramıza katıldığın için teşekkür ederiz.","Gadit tek bir görevi olan bir sözlük: bir kelimeyi sonuna kadar çözmek. Tek satırlık bir tanım değil, kuru bir çeviri değil. Tüm anlamlar, deyimler, kelimenin kökeni ve insanların onu bugün gerçekte nasıl kullandığı.","Ücretsiz hesabında günde 10 arama ve en fazla 30 kelimelik bir defter var.","Bir kelimeyi bütünüyle kavradığında, arkasındaki fikir netleşir, onunla birlikte de düşünme, öğrenme ve karar verme biçimin.","Gadit sürekli büyüyen, yaşayan bir platform. Herhangi bir tanımda, örnekte ya da başka bir yerde bir hata görürsen, basmaya değer bir bildirme düğmesi var. Ekibimiz her şeyi okur ve düzeltir.","Başlamaya hazır mısın?"],"cta":"İlk kelimeni ara","signOff":["Sevgiyle,","Gadit ekibi"]},"meanings":{"subject":"Bir kelime, daha önce görmediğin katmanlar","preheader":"Çoğu araç tanımda durur. Gadit, kelime akılda kalana kadar devam eder.","exampleWord":"baş","paras":["“Baş” kelimesini al ve tek bir kelimenin nasıl koca bir dünyayı açabildiğine bak.","Baş, vücudumuzun en üstteki bölümü, yani kafa. Baş, bir topluluğu yöneten kişi, bir işin başındaki insan. Baş, bir şeyin ilk kısmı, yolun başı ya da yılın başı. Baş, bir yerin uç noktası, masanın başı ya da yatağın başı. Baş, bir sayma birimi de olur: bir baş soğan, iki baş sarımsak. Ve baş, en önemli, en büyük anlamına da gelir: başkent, başrol, başöğretmen.","Bir kelime, onda görmediğin katmanlar, her biri kendi dünyasında yaşıyor.","Gadit'te her tanım için üç gerçek örnek bulursun. Kelimenin teoride değil, pratikte çalıştığı cümleler. Böylece kelimenin yalnızca ne dediğini değil, kullanıldığında kulağa nasıl geldiğini de görürsün.","Gadit'in kalbi bu. Bir kelime, sonuna kadar, tüm tanımlarıyla.","“Baş” kelimesini aramanı öneririz, belki de zaten anladığını düşündüğün başka bir kelimeyi. Şaşırabilirsin."],"cta":"“Baş” kelimesini ara ve tüm yüzlerini gör","ps":"Not: Şaşırtıcı bir anlam bulduğunda, yanında bir paylaş düğmesi var. Bunu takdir edecek birine göndermeye değer."},"etymology":{"subject":"Bir kelime gerçekte nereden gelir","preheader":"Her kelimenin bir geçmişi var ve bazen o geçmiş bugünü açıklar.","exampleWord":"baş","paras":["En sevdiğimiz bölüme geldik. Kelimenin nereden geldiği.","Her kelimenin bir geçmişi var. Ve bazen o geçmiş, bugünü herhangi bir tanımdan daha iyi açıklar.","“Baş” güzel bir örnek. Türkçenin en eski kelimelerinden biri. 8. yüzyıldan kalan Orhun Yazıtları'nda bile geçer ve anlamı bugünkü gibi vücudun en üst kısmıdır. Aynı kelime başka Türk dillerinde de yaşıyor: Azericede baş, Özbekçede bosh, Kazakçada bas.","Vücudun en üstteki kısmından anlam genişledi: bir topluluğun en üstündeki kişi, bir şeyin ilk kısmı, en önemli olanı. Başlamak fiili de aynı kelimeden türemiştir, başkan, başkent, başlık ve başlangıç da.","Tek bir kelimede koca bir yolculuk. Elle tutulur bir şeyden, insanın başından, liderlik ve başlangıç gibi soyut fikirlere. Hepsi bin yılı aşkın süredir bizimle olan tek bir kelimede.","Bunu bildiğinde kelimeyi yalnızca daha iyi hatırlamazsın. Tüm anlamlarının neden birbirine bağlı olduğunu da anlarsın. Bir arada tesadüfen yaşamıyorlar.","Gadit'te her kelimenin tanımlarının altında kökenini açıklayan bir bölüm var. Tarihsel arka plan, nereden geldiği. Bir sözlüğü tanım listesinden bir hikâyeye dönüştüren de bu."],"cta":"Sıradaki kelimenin kökenini keşfet"},"visual":{"subject":"Göz hizasında bir kelime","preheader":"Çocuk Modu: her kelime bir çocuğun dilinde, derinliğini kaybetmeden.","paras":["Bize en sık gelen isteklerden biri basitti. Bir çocuk bir kelimenin ne anlama geldiğini sorar ve resmî tanım onun için fazla karmaşıktır.","Bu yüzden Gadit'te Çocuk Modu var. Onu açtığında her kelime beş ile on yaş arası bir çocuğun dilinde açıklanır. Aynı derinlik, zor kelimeler olmadan.","“Baş” kelimesini düşün. Normal modda birkaç katmanda açıklanır. Çocuk Modu'nda ise bir çocuğun hemen kavrayacağı bir şeye dönüşür, mesela sıranın başı, sırada en önde duran kişinin yeridir.","Ve bu yalnızca çocuklar için değil. Bazen bir kelime gerçekten zor olduğunda, basit açıklama yetişkinlerin de onu kavramak için tam ihtiyaç duyduğu şeydir.","Gadit, Çocuk Modu'nun yanında her anlam için bir resim de gösterir. Böylece çocuk kelimeyi okumakla kalmaz, görür de. Anlamak daha hızlı gelir ve daha uzun kalır.","Çocuk Modu, çocuklu aileler için hazırlanan Family planının bir parçası. Her anlam için bir resim Individual planında da var.","Yakınında bir çocuk varsa, bir dakika onunla otur, Çocuk Modu'nu açın, birlikte bir kelime arayın ve resmine bakın. Zahmetsiz anlamanın anı işte böyle görünür."],"cta":"Çocuk Modu'nu keşfet"},"summary":{"subject":"İki hafta, bir kelime","preheader":"Yolculuk ve buradan devam etmenin iki yolu.","paras":["Son iki haftada bir kelimenin farklı yüzlerini tanıdık. Tüm anlamlarını ve tarihini.","Bunun yanında Gadit'i daha derin bir anlama aracı yapan özellikleri tanıdık: Çocuk Modu ve her anlam için bir resim.","Bu özelliklerin bazıları her kullanıcıya açık. Ücretsiz hesapta günde 10 arama ve en fazla 30 kelimelik bir defter var.","Geri kalanlar Individual ile açılır: sınırsız arama, her anlam için bir resim, her kelimeyi akıllı pratikle saklayan bir defter, oyunlar ve testler, “Her kelime” (bir sayfanın fotoğrafını çek ve herhangi bir kelimeye dokun), telaffuz pratiği için “Söyle” ve geri bildirimle cümle kurma. Gadit günlük rutininin bir parçası olduysa, farkı yaratan özellikler bunlar.","Evde çocuk mu var? <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> planı, Çocuk Modu ve ebeveyn paneliyle birlikte 5 çocuğa kadar kapsar.","Bir de ortaklık programımız var: üzerinden gelen her ücretli kayıttan sana komisyon kazandıran kişisel bir bağlantı. Sevdiğin bir şeyi paylaşmanın ve bu arada kazanmanın rahat bir yolu."],"cta":"Individual'ı tanı","ps":"Not: Gadit'te görmek istediğin özellikleri duymaktan her zaman mutluluk duyarız. Bu e-postayı yanıtlaman yeterli."}},
  ts: {"greetNamed":"Xewani {name},","greetPlain":"Xewani,","footerReason":"Mi kuma imeyili leyi hikuva mi tsarisile eka Gadit.","unsubscribeLabel":"Yimisa timeyili leti","welcome":{"subject":"Mi amukeriwile eka Gadit","preheader":"Dikixinari yin'we, xikongomelo xin'we. Ku twisisa rito ku fikela emakumu. Hi leswi mi sungulaka ha swona.","paras":["Mi amukeriwile eka Gadit, naswona hi khensa leswi mi hlanganeke na hina.","Gadit i dikixinari leyi nga na xikongomelo xin'we: ku twisisa rito hi ku helela. A hi nhlamuselo ya layini yin'we, a hi ku hundzuluxela ntsena. I tinhlamuselo hinkwato, swivulavulelo, masungulo ya rito, na ndlela leyi vanhu va ri tirhisaka ha yona namuntlha.","Akhawunti ya n'wina ya mahala yi na ku lava ka 10 hi siku na buku ya marito yo fika eka marito ya 30.","Loko mi twisisa rito hi ku helela, mianakanyo leyi nga endzhaku ka rona ya basa, naswona na yona ndlela leyi mi anakanyaka, mi dyondzaka na ku teka swiboho ha yona.","Gadit i xitirhisiwa lexi hanyaka lexi yaka emahlweni xi kula. Loko mi vona xihoxo eka nhlamuselo, eka xikombiso kumbe eka xiphemu xin'wana, ku na buto yo xi vika leyi faneleke ku thintiwa. Ntlawa wa hina wu hlaya hinkwaswo naswona wu swi lulamisa.","Xana mi lunghekele ku sungula?"],"cta":"Lavani rito ra n'wina ro sungula","signOff":["Hi rirhandzu,","Ntlawa wa Gadit"]},"meanings":{"subject":"Rito rin'we, swiphemu leswi a mi nga swi voni","preheader":"Switirhisiwa swo tala swi yima eka nhlamuselo. Gadit yi ya emahlweni ku fikela rito ri tshama.","exampleWord":"ririmi","paras":["Tekani rito ririmi, mi vona ndlela leyi rito rin'we ri nga pfulaka misava hinkwayo ha yona.","Ririmi i xirho lexi nga enon'wini, lexi hi pfunaka ku dya na ku vulavula. Ririmi i ndlela ya ku vulavula ya vanhu: Xitsonga i ririmi, Xinghezi i ririmi. I ririmi ra le kaya, leri mi ri dyondzeke mi ri vana. Naswona hi ririmi hi hlanganisa vanhu, hikuva vanhu lava vulavulaka ririmi rin'we va twanana.","Rito rin'we, swiphemu leswi a mi nga swi voni, xin'wana na xin'wana xi hanya emisaveni ya xona.","Eka Gadit mi kuma swikombiso swinharhu swa xiviri eka nhlamuselo yin'wana na yin'wana. Swivulwa leswi rito ri tirhaka eka swona hakunene, ku nga ri hi mianakanyo ntsena. Hi ndlela yoleyo a mi voni ntsena leswi rito ri swi vulaka, kambe mi vona ni ndlela leyi ri twalaka ha yona loko ri tirhisiwa.","Leyi i mbilu ya Gadit. Rito rin'we, ku fikela emakumu, eka tinhlamuselo hinkwato ta rona.","Hi mi khutaza ku lava ririmi, naswona kumbexana ni rito rin'wana leri mi ehleketaka leswaku se mi ri twisisa. Mi nga hlamala."],"cta":"Lavani ririmi mi vona swiphemu hinkwaswo","ps":"P.S. Loko mi kuma nhlamuselo leyi mi hlamarisaka, ku na buto yo avelana etlhelo ka yona. Swi fanerile ku yi rhumela eka munhu loyi a nga ta yi tsakela."},"etymology":{"subject":"Laha rito ri humaka kona hakunene","preheader":"Rito rin'wana na rin'wana ri na matimu, naswona minkarhi yin'wana ma hlamusela namuntlha.","exampleWord":"ririmi","paras":["Hi fikile eka xiphemu lexi hi xi rhandzaka ngopfu. Laha rito ri humaka kona.","Rito rin'wana na rin'wana ri na matimu ya rona. Naswona minkarhi yin'wana matimu wolawo ma hlamusela namuntlha ku tlula nhlamuselo yin'wana na yin'wana.","Ririmi i xikombiso xo saseka. Ri huma eka rito ra khale swinene ra tindzimi ta Bantu, leri a ri vula xirho xa le nomu. Vativi va tindzimi va ri kumile hi ku pimanisa tindzimi to tala ta Afrika: hi Xizulu i ulimi, hi Xiswati i lulwimi, hi Xiswahili i ulimi. Hinkwawo ma huma eka rito rin'we.","Eku sunguleni, ririmi a ri ri xirho lexi hi vulavulaka ha xona. Hikuva hi vulavula hi ririmi, rito leri ri tlhele ri vula leswi hi swi vulaka: ririmi hinkwaro ra vanhu. Leswi swi humelela ni le ka tindzimi tin'wana ta misava: hi Xinghezi, tongue i xirho xa le nomu ni ririmi ra vanhu.","Riendzo hinkwaro eka rito rin'we. Ku suka eka xirho xa miri, ku ya eka ririmi leri vanhu hinkwavo va hanyaka ha rona.","Loko mi tiva leswi, a mi ri tsundzuki ntsena rito kahle. Mi tlhela mi twisisa leswaku hikwalaho ka yini tinhlamuselo ta rona ti hlanganile. A ti hlangananga hi xihoxo.","Eka Gadit, ehansi ka tinhlamuselo ta rito rin'wana na rin'wana, ku na xiphemu lexi hlamuselaka masungulo ya rona. Matimu ya rona, laha ri humaka kona. Hi swona leswi hundzulaka dikixinari ku suka eka nxaxamelo wa tinhlamuselo yi va xitori."],"cta":"Kumani masungulo ya rito leri landzelaka"},"visual":{"subject":"Rito hi mahlo ya n'wana","preheader":"Xiyimo xa vana: rito rin'wana na rin'wana ri hlamuseriwa hi ririmi ra n'wana, handle ko lahlekeriwa hi vuenti.","paras":["Xin'wana xa swikombelo leswi hi swi kumaka ngopfu a xi olova. N'wana u vutisa leswi rito ri swi vulaka, kambe nhlamuselo ya ximfumo yi tika ngopfu eka yena.","Hi yona mhaka Gadit yi nga na Xiyimo xa vana. Xi pfuleni, kutani rito rin'wana na rin'wana ri hlamuseriwa hi ririmi ra n'wana wa malembe ya ntlhanu ku ya eka khume. Vuenti byi fanaka, handle ka marito lamakulu.","Tekani ririmi. Eka xiyimo xa ntolovelo ri hlamuseriwa hi swiphemu swo hlayanyana. Eka Xiyimo xa vana ri va nchumu lowu n'wana a wu twisisaka hi ku hatlisa: i xirho xa le nomu lexi ku pfunaka ku dya na ku vulavula, naswona i marito lawa vanhu va vulavulaka ha wona.","Naswona leswi a hi swa vana ntsena. Minkarhi yin'wana, loko rito ri tika hakunene, nhlamuselo yo olova hi yona leyi ni vanhu lavakulu va yi lavaka ku ri twisisa.","Etlhelo ka Xiyimo xa vana, Gadit yi tlhela yi komba xifaniso eka nhlamuselo yin'wana na yin'wana, leswaku n'wana a vona rito, ku nga ri ku ri hlaya ntsena. Ku twisisa ku fika hi ku hatlisa naswona ku tshama nkarhi wo leha.","Xiyimo xa vana i xiphemu xa pulani ya Family, leyi endleriweke mindyangu leyi nga na vana. Xifaniso eka nhlamuselo yin'wana na yin'wana xi tlhela xi ta na pulani ya Individual.","Loko ku ri na n'wana ekusuhi, tshamani na yena nkarhinyana, mi pfula Xiyimo xa vana, mi lava rito swin'we kutani mi languta xifaniso xa rona. Hi leswi ku twisisa loku taka handle ka ku karhala ku langutekaka ha swona."],"cta":"Vonani Xiyimo xa vana"},"summary":{"subject":"Mavhiki mambirhi, rito rin'we","preheader":"Riendzo, na tindlela timbirhi to ya emahlweni ku suka laha.","paras":["Eka mavhiki mambirhi lama hundzeke hi vone matlhelo yo hambana ya rito. Tinhlamuselo ta rona hinkwato, na matimu ya rona.","Swin'we na sweswo, hi vone switirhisiwa leswi endlaka Gadit yi va xitirhisiwa xa ku twisisa hi vuenti: Xiyimo xa vana, na xifaniso eka nhlamuselo yin'wana na yin'wana.","Swin'wana swa switirhisiwa leswi swi pfulekele mutirhisi un'wana na un'wana. Akhawunti ya mahala yi na ku lava ka 10 hi siku na buku ya marito yo fika eka marito ya 30.","Leswi swi saleke swi pfuriwa hi <strong>Individual</strong>: ku lava handle ka ndzilakano, xifaniso eka nhlamuselo yin'wana na yin'wana, buku ya marito leyi hlayisaka rito rin'wana na rin'wana na ntoloveto wa vutlhari, mintlangu na mavutiso, Rito rin'wana na rin'wana (tekani xifaniso xa tluka mi thinta rito rin'wana na rin'wana), Swi vule ku titoloveta mpfumawulo, na ku tsala xivulwa mi kuma switsundzuxo. Loko Gadit se yi ri xiphemu xa siku ra n'wina, leswi hi swona switirhisiwa leswi endlaka ku hambana.","Xana mi na vana ekaya? Pulani ya <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> yi katsa ku fika eka vana va 5, swi ri na Xiyimo xa vana na dashibodo ya mutswari.","Naswona hi na nongonoko wa vatirhisani: linki leyi nga ya n'wina ntsena, leyi mi nyikaka khomixini eka munhu un'wana na un'wana loyi a tsarisaka a hakela ha yona. Ndlela yo olova yo avelana nchumu lowu mi wu rhandzaka, mi ri karhi mi kuma mali."],"cta":"Tivani Individual","ps":"P.S. Hi tsakela ku twa hi switirhisiwa leswi mi nga rhandzaka ku swi vona eka Gadit. Hlamulani ntsena imeyili leyi."}},
  uk: {"greetNamed":"Вітаємо, {name},","greetPlain":"Вітаємо,","footerReason":"Ви отримали цей лист, тому що зареєструвалися в Gadit.","unsubscribeLabel":"Відписатися","welcome":{"subject":"Ласкаво просимо до Gadit","preheader":"Один словник, одна місія. Зрозуміти слово до кінця. Ось із чого почати.","paras":["Ласкаво просимо до Gadit, і дякуємо, що ви з нами.","У Gadit одна місія: зрозуміти слово до кінця. Не визначення в один рядок і не сухий переклад. Усі значення, сталі вирази, походження слова й те, як люди насправді вживають його сьогодні.","У вашому безкоштовному акаунті 10 пошуків на день і зошит до 30 слів.","Коли ви розумієте слово повністю, стає зрозумілою й ідея, що стоїть за ним, а разом із нею те, як ви думаєте, навчаєтеся й ухвалюєте рішення.","Gadit живе й постійно росте. Якщо ви помітите помилку у визначенні, у прикладі чи деінде, є кнопка, щоб повідомити про неї, і її варто натиснути. Наша команда читає все й виправляє.","Готові почати?"],"cta":"Знайдіть своє перше слово","signOff":["З теплом,","Команда Gadit"]},"meanings":{"subject":"Одне слово, шари, яких ви не помічали","preheader":"Більшість словників зупиняються на визначенні. Gadit іде далі, доки слово не запам'ятається.","exampleWord":"світ","paras":["Візьміть слово «світ» і подивіться, як одне слово може відкрити цілий світ.","Насамперед світ означає все, що нас оточує: Землю, країни, людей. Можна подорожувати світом або побачити світ. Світ означає й людей загалом: «весь світ про це знає». Народитися означає «з'явитися на світ». Буває «вищий світ», тобто знать і вищі кола суспільства. А ще світ означає ранок: «встати до світу» значить прокинутися ще до світанку. Недарма кажуть «ні світ ні зоря», коли щось стається дуже рано.","Одне слово, шари, яких ви в ньому не помічали, і кожен живе у своєму світі.","У Gadit для кожного значення є три справжні приклади. Речення, у яких слово працює на практиці, а не в теорії. Так ви бачите не лише те, що слово означає, а й те, як воно звучить у мові.","У цьому серце Gadit. Одне слово, до самого кінця, в усіх його значеннях.","Пропонуємо знайти слово «світ», а потім, можливо, ще одне, яке ви, як вам здається, вже добре знаєте. Можливо, воно вас здивує."],"cta":"Знайти слово «світ»","ps":"P.S. Коли ви знайдете несподіване значення, поруч буде кнопка, щоб ним поділитися. Його варто надіслати тому, хто це оцінить."},"etymology":{"subject":"Звідки насправді походить слово","preheader":"Кожне слово має минуле, і часом воно пояснює теперішнє.","exampleWord":"світ","paras":["Ми дійшли до нашої улюбленої частини. Звідки походить слово.","Кожне слово має минуле. І часом це минуле пояснює теперішнє краще за будь-яке визначення.","Світ є чудовим прикладом. Його первісне значення: світло. Так було ще в праслов'янській мові, і в піснях та віршах «світ» досі часом означає світло. Від того самого кореня походять слова світло, світанок, світлиця і свічка. Цей корінь дуже давній: у санскриті є споріднене слово śveta, «білий, світлий».","Згодом значення розширилося: від світла до всього, що це світло освітлює. Світом стало те, що ми бачимо при денному світлі, тобто земля, люди, усе навколо. Звідси й «білий світ», і «з'явитися на світ», тобто вийти до світла. А «до світу» досі означає до того, як стане світло.","Ціла подорож в одному слові. Від світла, яке ми бачимо щоранку, до цілого світу з усіма його людьми.","Коли ви це знаєте, слово не лише краще запам'ятовується. Ви ще й розумієте, чому всі його значення пов'язані. Вони живуть разом не випадково.","У Gadit під визначеннями кожного слова є розділ про його походження. Історичне тло, звідки воно прийшло. Саме це перетворює словник зі списку визначень на історію."],"cta":"Дізнатися походження наступного слова"},"visual":{"subject":"Слово на рівні очей","preheader":"Дитячий режим: кожне слово пояснене мовою дитини, без втрати глибини.","paras":["Одне з найчастіших прохань, які ми отримували, було простим. Дитина питає, що означає слово, а офіційне визначення для неї надто складне.","Тому в Gadit є дитячий режим. Увімкніть його, і кожне слово буде пояснене мовою дитини від п'яти до десяти років. Та сама глибина, тільки без складних слів.","Візьмімо слово «гравітація». У звичайному режимі йдеться про сили й маси. У дитячому режимі це те, що дитина розуміє одразу: те, через що речі падають на підлогу, коли їх відпускаєш, і що тримає нас на землі.","І це не лише для дітей. Іноді, коли слово справді складне, просте пояснення якраз те, що потрібно й дорослим, щоб його зрозуміти.","Разом із дитячим режимом Gadit показує картинку для кожного значення, щоб дитина могла не лише прочитати слово, а й побачити його. Розуміння приходить швидше й залишається довше.","Дитячий режим входить до тарифу Family, створеного для родин із дітьми. Картинка для кожного значення є й у тарифі Individual.","Якщо поруч є дитина, посидьте з нею хвилинку, увімкніть дитячий режим, знайдіть разом слово й подивіться на його картинку. Ось так виглядає мить, коли розуміння приходить без зусиль."],"cta":"Побачити дитячий режим"},"summary":{"subject":"Два тижні, одне слово","preheader":"Пройдений шлях і два способи йти далі.","paras":["За ці два тижні ми познайомилися з різними сторонами слова. З усіма його значеннями та з його історією.","А ще з можливостями, які роблять Gadit інструментом для глибшого розуміння: з дитячим режимом і картинкою для кожного значення.","Деякі з них відкриті для всіх. У безкоштовному акаунті 10 пошуків на день і зошит до 30 слів.","Решта відкривається з Individual: необмежений пошук, картинка для кожного значення, зошит, який зберігає кожне слово й пропонує розумне тренування, ігри та тести, «Кожне слово» (сфотографуйте сторінку й натисніть на будь-яке слово), «Скажи це» для тренування вимови, а ще можна скласти речення й отримати відгук. Якщо Gadit уже став частиною вашого дня, саме ці можливості все змінюють.","Удома є діти? Тариф <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> охоплює до 5 дітей, із дитячим режимом і панеллю для батьків.","А ще в нас є партнерська програма: особисте посилання, за яким ви отримуєте комісію за кожну платну реєстрацію. Зручний спосіб поділитися тим, що вам подобається, і заробити."],"cta":"Дізнатися про Individual","ps":"P.S. Нам завжди цікаво дізнатися, які функції ви хотіли б бачити в Gadit. Просто дайте відповідь на цей лист."}},
  ve: {"greetNamed":"Ri a ni lumelisa {name},","greetPlain":"Ri a ni lumelisa,","footerReason":"Ni khou wana iyi imeiḽi ngauri no ḓiṅwalisa kha Gadit.","unsubscribeLabel":"Imisani u rumelwa imeiḽi","welcome":{"subject":"Ni a ṱanganedzwa kha Gadit","preheader":"Bugu ya maipfi nthihi, ndivho nthihi. U pfesesa ipfi u swika magumoni. Hei ndi nḓila ya u thoma.","paras":["Ni a ṱanganedzwa kha Gadit, nahone ri a livhuwa ngauri no ri ṱanganela.","Gadit ndi bugu ya maipfi ine ya vha na ndivho nthihi: u pfesesa ipfi zwoṱhe. A si ṱhalutshedzo ya mutalo muthihi, a si u pindulela fhedzi. Ndi ndeme dzoṱhe, mirero, vhubvo ha ipfi, na nḓila ine vhathu vha ḽi shumisa ngayo ṋamusi.","Akhaunthu yaṋu ya mahala i na u ṱoḓa lwa 10 nga ḓuvha na bugu ya maipfi u swika kha 30.","Musi ni tshi pfesesa ipfi zwoṱhe, muhumbulo u re murahu haḽo u a vhonala, nahone na nḓila ine na humbula, na guda na u dzhia tsheo ngayo.","Gadit ndi tshishumiswa tshi tshilaho tshine tsha bvela phanḓa tshi tshi aluwa. Arali na vhona vhukhakhi kha ṱhalutshedzo iṅwe na iṅwe, kha tsumbo kana kha tshiṅwe tshipiḓa, hu na buthoni ya u vhiga ine ya fanela u kwamiwa. Tshigwada tshashu tshi vhala zwoṱhe nahone tshi a zwi lugisa.","No ḓilugisela u thoma?"],"cta":"Ṱoḓani ipfi ḽaṋu ḽa u thoma","signOff":["Nga lufuno,","Tshigwada tsha Gadit"]},"meanings":{"subject":"Ipfi ḽithihi, zwipiḓa zwe na vha ni sa zwi vhoni","preheader":"Zwishumiswa zwinzhi zwi ima kha ṱhalutshedzo. Gadit i bvela phanḓa u swika ipfi ḽi tshi dzula.","exampleWord":"ṅwedzi","paras":["Dzhiani ipfi ṅwedzi, ni vhone nḓila ine ipfi ḽithihi ḽa nga vula shango ḽoṱhe ngayo.","Ṅwedzi ndi tshithu tshi vhonalaho ṱaḓulu vhusiku, tshine tsha penya tsha vhonetshela shango. Ṅwedzi ndi tshifhinga tsha maḓuvha a ṱoḓaho u vha 30, nahone ṅwaha u na miṅwedzi ya 12. Ndi ṅwedzi we na bebwa khawo, ṅwedzi wa holodei, ṅwedzi wa mbadelo. Ndi ipfi ḽine na ḽi vhona na kha mitengo ya Gadit: nga ṅwedzi.","Ipfi ḽithihi, zwipiḓa zwe na vha ni sa zwi vhoni, tshiṅwe na tshiṅwe tshi tshi tshila shangoni ḽatsho.","Kha Gadit ni wana tsumbo tharu dza vhukuma kha ṱhalutshedzo iṅwe na iṅwe. Mitaladzi ine ipfi ḽa shuma khayo nga vhukuma, hu si nga muhumbulo fhedzi. Nga nḓila iyo a ni vhoni fhedzi zwine ipfi ḽa amba, fhedzi ni vhona na nḓila ine ḽa pfala ngayo musi ḽi tshi shumiswa.","Iyi ndi mbilu ya Gadit. Ipfi ḽithihi, u swika magumoni, kha ndeme dzaḽo dzoṱhe.","Ri ni ṱuṱuwedza uri ni ṱoḓe ṅwedzi, nahone khamusi na ḽiṅwe ipfi ḽine na humbula uri no ḽi pfesesa. Ni nga mangala."],"cta":"Ṱoḓani ṅwedzi ni vhone zwipiḓa zwoṱhe","ps":"P.S. Musi ni tshi wana ndeme ine ya ni mangadza, hu na buthoni ya u kovhela tsini hayo. Zwi a tea u i rumela kha muthu ane a ḓo i takalela."},"etymology":{"subject":"Hune ipfi ḽa bva hone nga vhukuma","preheader":"Ipfi ḽiṅwe na ḽiṅwe ḽi na ḓivhazwakale yaḽo, nahone zwiṅwe zwifhinga i ṱalutshedza ṋamusi.","exampleWord":"ṅwedzi","paras":["Ro swika kha tshipiḓa tshine ra tshi funesa. Hune ipfi ḽa bva hone.","Ipfi ḽiṅwe na ḽiṅwe ḽi na ḓivhazwakale. Nahone zwiṅwe zwifhinga ḓivhazwakale iyo i ṱalutshedza ṋamusi u fhira ṱhalutshedzo iṅwe na iṅwe.","Ṅwedzi ndi tsumbo yavhuḓi. Ndi ipfi ḽa kale vhukuma ḽa nyambo dza Bantu, ḽine vhaḓivhi vha nyambo vha ḽi wana nga u vhambedza nyambo nnzhi dza Afrika. Ni nga ḽi pfa na kha dziṅwe nyambo: nga Sesotho ndi kgwedi, nga Kiswahili ndi mwezi. Kha nyambo idzi dzoṱhe ipfi iḽi ḽi amba zwivhili: ṅwedzi wa ṱaḓulu na ṅwedzi wa tshifhinga.","Zwo vha hani uri ipfi ḽithihi ḽi ambe zwithu zwivhili? Kale vhathu vho vha vha tshi vhala tshifhinga nga ṅwedzi. Ṅwedzi u thoma u tshiṱuku, u a aluwa u swika wo ḓala, u dovha u fhela, nahone zwenezwo zwi dzhia maḓuvha a ṱoḓaho u vha 30. Nga u ralo tshifhinga itsho tsho vhidzwa nga dzina ḽa ṅwedzi. Na nga Luisimane, month (ṅwedzi wa tshifhinga) i bva kha moon (ṅwedzi wa ṱaḓulu).","Lwendo loṱhe kha ipfi ḽithihi. U bva kha tshithu tshine ra tshi vhona ṱaḓulu, u swika kha nḓila ine ra vhala ngayo maḓuvha a vhutshilo hashu.","Musi ni tshi zwi ḓivha, a ni humbuli fhedzi ipfi zwavhuḓi. Ni dovha na pfesesa uri ndi ngani ndeme dzaḽo dzoṱhe dzo ṱumana. A dzo ngo ṱangana nga tshiwo.","Kha Gadit, nga fhasi ha ṱhalutshedzo dza ipfi ḽiṅwe na ḽiṅwe, hu na tshipiḓa tshine tsha ṱalutshedza vhubvo haḽo. Ḓivhazwakale yaḽo, hune ḽa bva hone. Ndi zwone zwine zwa shandukisa bugu ya maipfi u bva kha mutevhe wa ṱhalutshedzo u vha tshiṱori."],"cta":"Wanani vhubvo ha ipfi ḽi tevhelaho"},"visual":{"subject":"Ipfi nga maṱo a ṅwana","preheader":"Tshiimo tsha vhana: ipfi ḽiṅwe na ḽiṅwe ḽi ṱalutshedzwa nga luambo lwa ṅwana, hu sa xelwi vhudzivha.","paras":["Kha khumbelo dzine ra dzi wana kanzhi, iṅwe yo vha i leluwa. Ṅwana u vhudzisa uri ipfi ḽi amba mini, fhedzi ṱhalutshedzo ya tshiofisi i a konḓa vhukuma kha ene.","Ndi ngazwo Gadit i na Tshiimo tsha vhana. Ni tshi tshi vula, ipfi ḽiṅwe na ḽiṅwe ḽi ṱalutshedzwa nga luambo lwa ṅwana wa miṅwaha miṱanu u swika kha fumi. Vhudzivha vhu fanaho, hu si na maipfi mahulwane.","Dzhiani ṅwedzi. Kha tshiimo tsha misi, u ṱalutshedzwa nga zwipiḓa zwinzhi. Kha Tshiimo tsha vhana u vha tshithu tshine ṅwana a tshi pfesesa nga u ṱavhanya: ndi tshithu tshi penyaho ṱaḓulu vhusiku, tshine tsha thoma tshi tshiṱuku tsha aluwa u swika tsho ḓala, nahone tshifhinga tshenetsho ri tshi vhidza ṅwedzi.","Nahone izwi a si zwa vhana fhedzi. Zwiṅwe zwifhinga, musi ipfi ḽi tshi konḓa vhukuma, ṱhalutshedzo yo leluwaho ndi yone ine na vhahulwane vha i ṱoḓa uri vha ḽi pfesese.","Tsini na Tshiimo tsha vhana, Gadit i dovha ya sumbedza tshifanyiso kha ndeme iṅwe na iṅwe, uri ṅwana a vhone ipfi, hu si u ḽi vhala fhedzi. U pfesesa hu swika nga u ṱavhanya nahone hu dzula tshifhinga tshilapfu.","Tshiimo tsha vhana ndi tshipiḓa tsha pulane ya Family, yo itelwaho miṱa i re na vhana. Tshifanyiso kha ndeme iṅwe na iṅwe tshi dovha tsha ḓa na pulane ya Individual.","Arali hu na ṅwana tsini, dzulani nae lwa tshifhinganyana, ni vule Tshiimo tsha vhana, ni ṱoḓe ipfi noṱhe nahone ni sedze tshifanyiso tshaḽo. Ndi zwone zwine u pfesesa hu sa konḓi ha vhonala ngazwo."],"cta":"Vhonani Tshiimo tsha vhana"},"summary":{"subject":"Vhege mbili, ipfi ḽithihi","preheader":"Lwendo, na nḓila mbili dza u bvela phanḓa u bva fhano.","paras":["Kha vhege mbili dzo fhiraho ro vhona zwipiḓa zwo fhambanaho zwa ipfi. Ndeme dzaḽo dzoṱhe, na ḓivhazwakale yaḽo.","Tsini ha zwenezwo, ro vhona zwishumiswa zwine zwa ita uri Gadit i vhe tshishumiswa tsha u pfesesa nga vhudzivha: Tshiimo tsha vhana, na tshifanyiso kha ndeme iṅwe na iṅwe.","Zwiṅwe zwa zwishumiswa izwi zwo vulelwa mushumisi muṅwe na muṅwe. Akhaunthu ya mahala i na u ṱoḓa lwa 10 nga ḓuvha na bugu ya maipfi u swika kha 30.","Zwo salaho zwi vulwa nga <strong>Individual</strong>: u ṱoḓa hu si na mukano, tshifanyiso kha ndeme iṅwe na iṅwe, bugu ya maipfi ine ya vhulunga ipfi ḽiṅwe na ḽiṅwe na nḓowelo ya vhuṱali, mitambo na mbudziso, Ipfi ḽiṅwe na ḽiṅwe (dzhiani tshifanyiso tsha siaṱari ni kwame ipfi ḽiṅwe na ḽiṅwe), Ḽi ambeni u ḓowela u bula, na u vhumba mutaladzi ni wane vhuṱanzi. Arali Gadit yo no vha tshipiḓa tsha ḓuvha ḽaṋu, izwi ndi zwishumiswa zwine zwa ita phambano.","Ni na vhana hayani? Pulane ya <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> i katela vhana u swika kha vha 5, i na Tshiimo tsha vhana na tshikirini tsha vhabebi.","Nahone ri na mbekanyamushumo ya vhashumisani: linki yaṋu ine ya ni ṋea khomishini kha muthu muṅwe na muṅwe ane a ḓiṅwalisa a badela nga hayo. Nḓila yo leluwaho ya u kovhela tshine na tshi funa, ni tshi khou wana na tshelede."],"cta":"Ḓivhani Individual","ps":"P.S. Ri dzula ri tshi takalela u pfa nga ha zwishumiswa zwine na nga takalela u zwi vhona kha Gadit. Fhindulani fhedzi iyi imeiḽi."}},
  vi: {"greetNamed":"Chào {name},","greetPlain":"Xin chào,","footerReason":"Bạn nhận được email này vì bạn đã đăng ký Gadit.","unsubscribeLabel":"Hủy đăng ký","welcome":{"subject":"Chào mừng bạn đến với Gadit","preheader":"Một cuốn từ điển, một sứ mệnh. Hiểu một từ đến tận cùng. Đây là cách bắt đầu.","paras":["Chào mừng bạn đến với Gadit, và cảm ơn bạn đã tham gia.","Gadit là một cuốn từ điển với một sứ mệnh duy nhất: hiểu một từ đến tận cùng. Không phải một định nghĩa một dòng, không phải một bản dịch khô khan. Mà là mọi nghĩa, các thành ngữ, nguồn gốc của từ, và cách mọi người thực sự dùng từ đó ngày nay.","Tài khoản miễn phí của bạn có 10 lượt tra mỗi ngày và sổ tay lưu tối đa 30 từ.","Khi bạn hiểu trọn vẹn một từ, ý tưởng đằng sau nó trở nên rõ ràng, và cùng với đó là cách bạn suy nghĩ, học hỏi và đưa ra quyết định.","Gadit là một nền tảng sống và không ngừng phát triển. Nếu bạn thấy lỗi trong bất kỳ định nghĩa, ví dụ hay phần nào khác, nút báo lỗi rất đáng để bấm. Đội ngũ của chúng tôi đọc mọi phản hồi và sửa lại.","Sẵn sàng bắt đầu chưa?"],"cta":"Tra từ đầu tiên của bạn","signOff":["Thân mến,","Đội ngũ Gadit"]},"meanings":{"subject":"Một từ, những tầng nghĩa bạn chưa từng thấy","preheader":"Hầu hết công cụ dừng lại ở định nghĩa. Gadit đi tiếp cho đến khi bạn nhớ.","exampleWord":"tâm","paras":["Hãy lấy từ “tâm”, và xem một từ có thể mở ra cả một thế giới như thế nào.","Tâm là tấm lòng của con người, như khi ta nói một người “có tâm” với nghề. Tâm là tâm trí, nơi chứa suy nghĩ và cảm xúc, như trong tâm hồn, tâm trạng. Tâm là điểm chính giữa, tâm của đường tròn. Tâm là nơi mạnh nhất của một hiện tượng, tâm bão, tâm động đất. Và tâm có mặt trong những từ quen thuộc như quan tâm, tâm sự, trung tâm.","Một từ, những tầng nghĩa bạn chưa từng thấy trong nó, mỗi tầng sống trong thế giới riêng của mình.","Trên Gadit, bạn sẽ có ba ví dụ thật cho mỗi định nghĩa. Những câu mà từ đó được dùng trong thực tế, không chỉ trên lý thuyết. Nhờ vậy, bạn không chỉ thấy từ đó nói gì, mà còn thấy nó nghe ra sao khi được dùng.","Đây là trái tim của Gadit. Một từ, đến tận cùng, qua tất cả các định nghĩa của nó.","Chúng tôi gợi ý bạn tra từ “tâm”, và có thể thêm một từ khác mà bạn nghĩ là đã hiểu rõ. Có thể bạn sẽ bất ngờ."],"cta":"Tra “tâm” và xem mọi khía cạnh","ps":"T.B. Khi bạn tìm thấy một nghĩa bất ngờ, bên cạnh có nút chia sẻ. Rất đáng để gửi cho người sẽ thích nó."},"etymology":{"subject":"Một từ thực sự đến từ đâu","preheader":"Mỗi từ đều có quá khứ, và đôi khi quá khứ ấy giải thích hiện tại.","exampleWord":"tâm","paras":["Đã đến phần chúng tôi yêu thích nhất. Một từ đến từ đâu.","Mỗi từ đều có một quá khứ. Và đôi khi quá khứ ấy giải thích hiện tại rõ hơn bất kỳ định nghĩa nào.","Tâm là một ví dụ thật đẹp. Đây là một từ Hán Việt, cách đọc tiếng Việt của chữ Hán 心. Ở dạng cổ nhất, chữ này là hình vẽ trái tim, một bộ phận rất cụ thể trong lồng ngực.","Người Trung Hoa xưa xem trái tim là nơi con người suy nghĩ và cảm nhận. Vì thế, từ trái tim, nghĩa của chữ mở rộng sang tâm trí, tấm lòng, tình cảm. Từ đó, nghĩa còn mở rộng sang phần cốt lõi, điểm chính giữa của mọi thứ, như trong trung tâm hay tâm của đường tròn.","Cả một hành trình trong một từ. Từ thứ cụ thể nhất, một bộ phận trong cơ thể, đến thứ trừu tượng nhất, tâm hồn của con người. Tất cả trong một từ đã đi cùng con người hàng nghìn năm.","Khi biết điều này, bạn không chỉ nhớ từ đó tốt hơn. Bạn còn hiểu vì sao mọi nghĩa của nó liên kết với nhau. Chúng không tình cờ sống chung.","Trên Gadit, bên dưới các định nghĩa của mỗi từ có một phần giải thích nguồn gốc của nó. Bối cảnh lịch sử, từ đó đến từ đâu. Chính điều này biến một cuốn từ điển từ danh sách định nghĩa thành một câu chuyện."],"cta":"Khám phá nguồn gốc của từ tiếp theo"},"visual":{"subject":"Một từ ngang tầm mắt trẻ","preheader":"Chế độ Trẻ em: mọi từ được giải thích bằng ngôn ngữ của trẻ, mà không mất đi chiều sâu.","paras":["Một trong những yêu cầu phổ biến nhất mà chúng tôi nhận được rất đơn giản. Một đứa trẻ hỏi một từ nghĩa là gì, và định nghĩa chính thức thì quá phức tạp với các em.","Đó là lý do Gadit có Chế độ Trẻ em. Bật lên, và mọi từ được giải thích bằng ngôn ngữ của trẻ từ năm đến mười tuổi. Vẫn chiều sâu ấy, nhưng không có những từ khó.","Hãy lấy từ “trọng lực”. Ở chế độ thường, từ này được giải thích bằng vật lý và lực hút giữa các vật có khối lượng. Ở Chế độ Trẻ em, nó trở thành điều trẻ hiểu ngay: một lực vô hình kéo mọi thứ xuống mặt đất, vì thế quả bóng ném lên cao luôn rơi xuống.","Và điều này không chỉ dành cho trẻ em. Đôi khi, khi một từ thật sự khó, lời giải thích đơn giản chính là điều người lớn cũng cần để hiểu.","Cùng với Chế độ Trẻ em, Gadit còn hiển thị một hình ảnh cho mỗi nghĩa, để trẻ vừa đọc vừa nhìn thấy từ đó. Sự hiểu đến nhanh hơn và ở lại lâu hơn.","Chế độ Trẻ em là một phần của gói Family, dành cho gia đình có trẻ nhỏ. Hình ảnh cho mỗi nghĩa cũng có trong gói Individual.","Nếu có một đứa trẻ bên cạnh, hãy ngồi cùng các em một phút, bật Chế độ Trẻ em, cùng tra một từ và xem hình ảnh của nó. Khoảnh khắc hiểu ra thật nhẹ nhàng trông chính là như thế."],"cta":"Xem Chế độ Trẻ em"},"summary":{"subject":"Hai tuần, một từ","preheader":"Hành trình vừa qua, và hai cách để tiếp tục từ đây.","paras":["Trong hai tuần qua, chúng ta đã làm quen với những khía cạnh khác nhau của một từ. Mọi nghĩa của nó, và lịch sử của nó.","Song song với đó, chúng ta đã làm quen với những tính năng giúp Gadit trở thành công cụ để hiểu sâu hơn: Chế độ Trẻ em, và một hình ảnh cho mỗi nghĩa.","Một số tính năng mở cho mọi người dùng. Tài khoản miễn phí có 10 lượt tra mỗi ngày và sổ tay lưu tối đa 30 từ.","Những tính năng còn lại được mở khóa với gói Individual: tra từ không giới hạn, một hình ảnh cho mỗi nghĩa, sổ tay lưu mọi từ cùng luyện tập thông minh, trò chơi và câu đố, “Mọi từ” (chụp ảnh một trang và chạm vào bất kỳ từ nào), Say it để luyện phát âm, và đặt câu kèm nhận xét. Nếu Gadit đã trở thành một phần thói quen hằng ngày của bạn, đây là những tính năng tạo nên sự khác biệt.","Nhà có trẻ nhỏ? Gói <a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> dành cho tối đa 5 con, với Chế độ Trẻ em và bảng theo dõi dành cho phụ huynh.","Chúng tôi cũng có chương trình đối tác: một đường link cá nhân giúp bạn nhận hoa hồng cho mỗi lượt đăng ký trả phí đến từ link đó. Một cách tiện lợi để chia sẻ điều bạn yêu thích, và có thêm thu nhập trên đường đi."],"cta":"Tìm hiểu gói Individual","ps":"T.B. Chúng tôi luôn muốn được nghe về những tính năng bạn mong có trong Gadit. Bạn chỉ cần trả lời email này."}},
  xh: {"greetNamed":"Molo {name},","greetPlain":"Molo,","footerReason":"Ufumana le imeyili kuba ubhalisile kwi-Gadit.","unsubscribeLabel":"Zikhuphe kuluhlu","welcome":{"subject":"Wamkelekile kwi-Gadit","preheader":"Isichazi-magama esinye, injongo enye. Ukuqonda igama ngokupheleleyo. Nantsi indlela yokuqalisa.","paras":["Wamkelekile kwi-Gadit, kwaye enkosi ngokuzibandakanya.","I-Gadit sisichazi-magama esinenjongo enye: ukuqonda igama ngokupheleleyo. Ingeyiyo inkcazelo yomgca omnye, ingeyiyo inguqulelo eyomileyo. Zonke iintsingiselo, izaci, imvelaphi yegama, neendlela abantu abalisebenzisa ngazo namhlanje.","I-akhawunti yakho yasimahla iquka ukukhangela okuli-10 ngosuku nencwadi yamagama ukuya kutsho kuma-30.","Xa ulibamba ngokupheleleyo igama, ingcamango engasemva kwalo iyacaca, kwaye kunye nayo nendlela ocinga ngayo, ofunda ngayo nogqiba ngayo.","I-Gadit liqonga eliphilayo eliqhubeka likhula. Ukuba ubona impazamo kuyo nayiphi na inkcazelo, umzekelo okanye enye inxalenye, kukho iqhosha lokunika ingxelo elifanele ukucofwa. Iqela lethu lifunda yonke into kwaye liyayilungisa.","Ukulungele ukuqalisa?"],"cta":"Khangela igama lakho lokuqala","signOff":["Ngentlonipho,","Iqela le-Gadit"]},"meanings":{"subject":"Igama elinye, iingqimba obungazibonanga","preheader":"Uninzi lwezixhobo luyema kwinkcazelo. I-Gadit iyaqhubeka de igama lihlale.","exampleWord":"umoya","paras":["Thatha igama elithi \"umoya\", ubone ukuba igama elinye linokulivula njani ihlabathi liphela.","Umoya yinto evuthuza emithini, umoya obandayo wasebusika. Ngumoya esiwuphefumlayo, umoya ococekileyo. Ngumoya womntu ngaphakathi, intliziyo nomphefumlo wakhe. Ngumoya ophakathi kwabantu, njengomoya omhle entsapheni okanye eqeleni. Kwaye ecaweni, nguMoya oyiNgcwele.","Igama elinye, iingqimba obungazibonanga kulo, nganye iphila kwihlabathi layo.","Kwi-Gadit uza kufumana imizekelo emithathu yokwenyani yenkcazelo nganye. Izivakalisi apho igama lisebenza khona ebomini, hayi kwithiyori kuphela. Ngale ndlela ubona kungekuphela nje oko igama likuthethayo, kodwa nendlela elivakala ngayo xa lisetyenziswa.","Le yintliziyo ye-Gadit. Igama elinye, ukuya esiphelweni, kuzo zonke iinkcazelo zalo.","Sicebisa ukuba ukhangele elithi \"umoya\", mhlawumbi nelinye igama ocinga ukuba sele ulazi kakuhle. Usenokumangaliswa."],"cta":"Khangela igama elithi \"umoya\"","ps":"P.S. Xa ufumana intsingiselo ekumangalisayo, kukho iqhosha lokwabelana ecaleni kwayo. Kufanelekile ukuyithumela kumntu oya kuyixabisa."},"etymology":{"subject":"Apho igama livela khona ngokwenene","preheader":"Lonke igama linembali, kwaye ngamanye amaxesha icacisa okwangoku.","exampleWord":"umoya","paras":["Sifikile kwinxalenye esiyithanda kakhulu. Apho igama livela khona.","Lonke igama linembali. Kwaye ngamanye amaxesha loo mbali icacisa okwangoku ngcono kunayo nayiphi na inkcazelo.","Umoya ngumzekelo omhle. Eli gama alilolesiXhosa lodwa. NgesiZulu likwathi umoya, kwaye ngesiSuthu nangesiPedi lithi moya. Xa iilwimi ezizalanayo zinegama elinye ngolu hlobo, oko kubonisa ukuba lisuka kukhokho wazo omnye wakudala, ngaphambi kokuba ezi lwimi zahlukane.","Kwaye jonga indlela iintsingiselo zalo ezinxulumene ngayo. Zonke ziyinto ongenakuyibona ngamehlo kodwa uyive: umoya ebusweni bakho, umoya emiphungeni yakho, umoya ophilisa umntu. Ukusuka apho, kulula ukubona indlela igama elifikelela ngayo nakwinto engabonakaliyo ngaphakathi emntwini, umoya wakhe, nakumoya ophakathi kwabantu.","Xa iBhayibhile yaguqulelwa esiXhoseni ngenkulungwane ye-19, abaguquleli basebenzisa eli gama ukubiza uMoya oyiNgcwele.","Uhambo lonke kwigama elinye. Ukusuka kwinto oyiva ichukumisa ulusu lwakho, umoya ovuthuzayo, ukuya kweyona nto ingabonakaliyo, umoya womntu.","Xa sele ukwazi oku, akupheleli nje ekubeni ulikhumbule ngcono igama. Uyaqonda nokuba kutheni zonke iintsingiselo zalo zinxulumene. Azihlali kunye ngengozi.","Kwi-Gadit, phantsi kweenkcazelo zegama ngalinye, kukho icandelo elicacisa imvelaphi yalo. Imbali yalo, apho livela khona. Yiloo nto eguqula isichazi-magama sisuke kuluhlu lweenkcazelo sibe libali."],"cta":"Fumana imvelaphi yegama elilandelayo"},"visual":{"subject":"Igama kwinqanaba lamehlo","preheader":"IMo yabantwana: lonke igama licaciswa ngolwimi lomntwana, ngaphandle kokuphulukana nobunzulu.","paras":["Esinye sezicelo esizifumene rhoqo besilula. Umntwana ubuza ukuba igama lithetha ntoni, kodwa inkcazelo esemthethweni inzima kakhulu kuye.","Kungenxa yoko le nto i-Gadit ineMo yabantwana. Yivule, kwaye lonke igama licaciswa ngolwimi lomntwana oneminyaka emihlanu ukuya kweshumi. Ubunzulu obufanayo, ngaphandle kwamagama amakhulu.","Thatha elithi \"umoya\". Kwimo eqhelekileyo, licaciswa ngeengqimba ezininzi. KwiMo yabantwana, liba yinto umntwana ayiqondayo kwangoko, njengento oyivayo ebusweni bakho xa imithi ishukuma, nomoya ongenayo uphume xa uphefumla.","Kwaye oku akukokwabantwana kuphela. Ngamanye amaxesha, xa igama linzima ngokwenene, inkcazelo elula yiyo kanye abantu abadala abayidingayo ukuze baliqonde.","Ecaleni kweMo yabantwana, i-Gadit ikwabonisa umfanekiso kwintsingiselo nganye, ukuze umntwana abone igama kwaye alifunde. Ukuqonda kufika ngokukhawuleza kwaye kuhlala ixesha elide.","IMo yabantwana yinxalenye yesicwangciso se-Family, esenzelwe iintsapho ezinabantwana. Umfanekiso kwintsingiselo nganye ukwafumaneka kwisicwangciso se-Individual.","Ukuba kukho umntwana kufutshane, hlala naye umzuzwana, uvule iMo yabantwana, nikhangele igama kunye kwaye nijonge umfanekiso walo. Yile ndlela umzuzu wokuqonda ngaphandle kobunzima okhangeleka ngayo."],"cta":"Bona iMo yabantwana"},"summary":{"subject":"Iiveki ezimbini, igama elinye","preheader":"Uhambo, neendlela ezimbini zokuqhubeka ukusuka apha.","paras":["Kwiiveki ezimbini ezidlulileyo siye sazi amacala ahlukeneyo egama. Zonke iintsingiselo zalo, nembali yalo.","Ecaleni koko, siye sazi iimpawu ezenza i-Gadit ibe sisixhobo sokuqonda okunzulu: iMo yabantwana, nomfanekiso kwintsingiselo nganye.","Ezinye zezi mpawu zivulelekile kubo bonke abasebenzisi. I-akhawunti yasimahla iquka ukukhangela okuli-10 ngosuku nencwadi yamagama ukuya kutsho kuma-30.","Ezinye zivuleka nge-Individual: ukukhangela okungenamda, umfanekiso kwintsingiselo nganye, incwadi egcina lonke igama noziqheliso olukrelekrele, imidlalo nemibuzo, Lonke Igama (fota iphepha uze ucofe naliphi na igama), Yithethe ukuziqhelisa ukubiza amagama, nokwakha isivakalisi ufumane ingxelo. Ukuba i-Gadit sele iyinxalenye yobomi bakho bemihla ngemihla, ezi zezona mpawu zenza umahluko.","Unabantwana ekhaya? Isicwangciso se-<a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> siquka ukuya kubantwana aba-5, neMo yabantwana nebhodi yomzali.","Kwaye sinenkqubo yamaqabane: ikhonkco lakho elikunika ikomishini kuko konke ukubhalisa okuhlawulelwayo okufika ngalo. Indlela elula yokwabelana ngento oyithandayo, kwaye ufumane umvuzo endleleni."],"cta":"Yazi i-Individual","ps":"P.S. Sihlala sithanda ukuva ngezixhobo ongathanda ukuzibona kwi-Gadit. Phendula nje le imeyili."}},
  "zh-CN": {"greetNamed":"嗨 {name}，","greetPlain":"你好，","footerReason":"你收到这封邮件，是因为你注册了 Gadit。","unsubscribeLabel":"退订","welcome":{"subject":"欢迎来到 Gadit","preheader":"一本词典，一个使命：把一个词彻底弄懂。从这里开始。","paras":["欢迎来到 Gadit，谢谢你的加入。","Gadit 是一本只有一个使命的词典：把一个词彻底弄懂。不是一行字的释义，也不是干巴巴的翻译。而是全部释义、习语、这个词的来源，以及人们今天真正怎么用它。","你的免费账户每天可查 10 次，生词本最多保存 30 个词。","当你完全理解一个词，它背后的意思就清楚了，你思考、学习和做决定的方式也会随之改变。","Gadit 是一个不断成长的平台。如果你在任何释义、例句或其他地方发现错误，请按一下报告按钮。我们的团队会阅读每一条反馈，并加以修正。","准备好开始了吗？"],"cta":"查你的第一个词","signOff":["祝好，","Gadit 团队"]},"meanings":{"subject":"一个词，还有你没见过的层次","preheader":"大多数工具停在释义上。Gadit 会一直讲下去，直到你记住。","exampleWord":"道","paras":["拿“道”这个字来说，看看一个字怎样打开一整个世界。","道是人走的路，比如街道、山道。道是方法，比如生财之道、养生之道。道是道理和规律，比如天道、公道。道也是说，比如说道、道歉、道谢。它还可以是量词：一道题、一道菜、一道光。在老子的思想里，道是万物运行的根本。","一个字，许多你没留意过的层次，每一层都活在自己的世界里。","在 Gadit 里，每条释义都配有三个真实例句。是这个词在实际中怎么用，而不是纸上谈兵。这样你看到的不只是它的意思，还有它用起来是什么样子。","这就是 Gadit 的核心：一个词，从头到尾，走遍它所有的释义。","建议你查一查“道”，再查一个你以为自己早就完全懂了的词。说不定会让你吃一惊。"],"cta":"查“道”，看看它的所有面貌","ps":"附言：发现一个意想不到的释义时，旁边就有分享按钮。值得发给一个会喜欢它的人。"},"etymology":{"subject":"一个词到底从哪里来","preheader":"每个词都有过去，有时它能解释现在。","exampleWord":"道","paras":["终于到了我们最喜欢的部分：这个词从哪里来。","每个词都有过去。有时，这段过去比任何释义都更能解释现在。","“道”就是一个很美的例子。《说文解字》说：“道，所行道也。”意思就是人行走的路。字形也和行走有关：走之旁“辶”表示走路，里面是一个“首”字。","从脚下的路，引申出通往目标的方法，也就是做事的门道。再往前一步，就成了更抽象的东西：事物的规律和做人的道理。老子说“道可道，非常道”，这句话里第一个和第三个“道”是那个根本的道，中间那个“道”是“说出来”的意思。","一个字里装着一整段旅程。从最具体的东西，脚下的路，到最抽象的东西，万物的道理。这一切，都在一个陪伴了我们几千年的字里。","知道了这些，你不只是更容易记住这个词。你还会明白它所有的释义为什么彼此相连。它们住在一起，不是偶然的。","在 Gadit 里，每个词的释义下面都有一个讲它来源的部分。历史背景，它从哪里来。正是这一部分，让词典从一张释义清单变成一个故事。"],"cta":"发现下一个词的来源"},"visual":{"subject":"用孩子的视线看一个词","preheader":"儿童模式：每个词都用孩子的语言讲解，深度一点不少。","paras":["我们收到最多的请求之一很简单：孩子问一个词是什么意思，可正式的释义对他们来说太难了。","所以 Gadit 有儿童模式。打开它，每个词都会用五到十岁孩子的语言来讲解。深度不变，只是没有那些难懂的大词。","比如“重力”。在普通模式里，它是物理和公式。在儿童模式里，它变成孩子一听就懂的东西：为什么把球往上扔，它总会掉下来；为什么我们能稳稳地站在地上。","而且这不只是给孩子的。有时候，一个词真的很难，大人要弄懂它，需要的也正是这样简单的解释。","除了儿童模式，Gadit 还为每个释义配一张图片，让孩子不只是读到这个词，还能看到它。理解来得更快，也留得更久。","儿童模式属于 Family 方案，专为有孩子的家庭设计。每个释义配图也包含在 Individual 方案里。","如果身边有孩子，就和他坐一会儿，打开儿童模式，一起查一个词，看看它的图片。毫不费力就懂了的那一刻，就是这个样子。"],"cta":"了解儿童模式"},"summary":{"subject":"两周，一个词","preheader":"一路走来的旅程，以及接下来的两条路。","paras":["过去两周，我们一起认识了一个词的不同侧面：它所有的释义，还有它的历史。","同时，我们也认识了让 Gadit 成为深入理解工具的功能：儿童模式，以及每个释义配一张图片。","其中一些功能向所有用户开放。免费账户每天可查 10 次，生词本最多保存 30 个词。","其余的功能随 Individual 解锁：不限次数查词、每个释义配图、保存每个词并带智能练习的生词本、游戏和测验、“每个词”（拍下一页，点任何一个词）、练习发音的“说一说”，以及造一个句子并获得反馈。如果 Gadit 已经成了你每天的习惯，这些功能就会带来真正的不同。","家里有孩子？<a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> 方案最多可供 5 个孩子使用，并提供儿童模式和家长面板。","我们还有合作伙伴计划：一个专属链接，每有一位用户通过它付费注册，你就能获得一笔佣金。分享你喜欢的东西，顺便也有收获，很方便。"],"cta":"了解 Individual","ps":"附言：你希望 Gadit 增加哪些功能，我们随时都很想听听。直接回复这封邮件就好。"}},
  "zh-TW": {"greetNamed":"嗨 {name}，","greetPlain":"你好，","footerReason":"你收到這封信，是因為你註冊了 Gadit。","unsubscribeLabel":"取消訂閱","welcome":{"subject":"歡迎來到 Gadit","preheader":"一本字典，一個使命：把一個詞徹底弄懂。從這裡開始。","paras":["歡迎來到 Gadit，謝謝你的加入。","Gadit 是一本只有一個使命的字典：把一個詞徹底弄懂。不是一行字的解釋，也不是乾巴巴的翻譯。而是所有詞義、慣用語、這個詞的來源，以及人們今天真正怎麼使用它。","你的免費帳號每天可查 10 次，生詞本最多儲存 30 個詞。","當你完全理解一個詞，它背後的意思就清楚了，你思考、學習和做決定的方式也會隨之改變。","Gadit 是一個不斷成長的平台。如果你在任何詞義、例句或其他地方發現錯誤，請按一下回報按鈕。我們的團隊會閱讀每一則回報，並加以修正。","準備好開始了嗎？"],"cta":"查你的第一個詞","signOff":["祝好，","Gadit 團隊"]},"meanings":{"subject":"一個詞，還有你沒見過的層次","preheader":"大多數工具停在定義上。Gadit 會一直講下去，直到你記住。","exampleWord":"道","paras":["拿「道」這個字來說，看看一個字怎樣打開一整個世界。","道是人走的路，比如街道、山道。道是方法，比如生財之道、養生之道。道是道理和規律，比如天道、公道。道也是說，比如說道、道歉、道謝。它還可以是量詞：一道題、一道菜、一道光。在老子的思想裡，道是萬物運行的根本。","一個字，許多你沒留意過的層次，每一層都活在自己的世界裡。","在 Gadit 裡，每個詞義都附有三個真實例句。是這個詞在實際中怎麼用，而不是紙上談兵。這樣你看到的不只是它的意思，還有它用起來是什麼樣子。","這就是 Gadit 的核心：一個詞，從頭到尾，走遍它所有的詞義。","建議你查一查「道」，再查一個你以為自己早就完全懂了的詞。說不定會讓你嚇一跳。"],"cta":"查「道」，看看它的所有面貌","ps":"附註：發現一個意想不到的詞義時，旁邊就有分享按鈕。值得傳給一個會喜歡它的人。"},"etymology":{"subject":"一個詞到底從哪裡來","preheader":"每個詞都有過去，有時它能解釋現在。","exampleWord":"道","paras":["終於到了我們最喜歡的部分：這個詞從哪裡來。","每個詞都有過去。有時，這段過去比任何定義都更能解釋現在。","「道」就是一個很美的例子。《說文解字》說：「道，所行道也。」意思就是人行走的路。字形也和行走有關：部首「辶」表示走路，裡面是一個「首」字。","從腳下的路，引申出通往目標的方法，也就是做事的門道。再往前一步，就成了更抽象的東西：事物的規律和做人的道理。老子說「道可道，非常道」，這句話裡第一個和第三個「道」是那個根本的道，中間那個「道」是「說出來」的意思。","一個字裡裝著一整段旅程。從最具體的東西，腳下的路，到最抽象的東西，萬物的道理。這一切，都在一個陪伴了我們幾千年的字裡。","知道了這些，你不只是更容易記住這個詞。你還會明白它所有的詞義為什麼彼此相連。它們住在一起，不是偶然的。","在 Gadit 裡，每個詞的詞義下面都有一個講它來源的部分。歷史背景，它從哪裡來。正是這一部分，讓字典從一張定義清單變成一個故事。"],"cta":"發現下一個詞的來源"},"visual":{"subject":"用孩子的視線看一個詞","preheader":"兒童模式：每個詞都用孩子的語言解釋，深度一點不少。","paras":["我們收到最多的請求之一很簡單：孩子問一個詞是什麼意思，可是正式的定義對他們來說太難了。","所以 Gadit 有兒童模式。打開它，每個詞都會用五到十歲孩子的語言來解釋。深度不變，只是沒有那些難懂的大詞。","比如「重力」。在一般模式裡，它是物理和公式。在兒童模式裡，它變成孩子一聽就懂的東西：為什麼把球往上丟，它總會掉下來；為什麼我們能穩穩地站在地上。","而且這不只是給孩子的。有時候，一個詞真的很難，大人要弄懂它，需要的也正是這樣簡單的解釋。","除了兒童模式，Gadit 還為每個詞義配一張圖片，讓孩子不只是讀到這個詞，還能看到它。理解來得更快，也留得更久。","兒童模式包含於 Family 方案，專為有孩子的家庭設計。每個詞義的圖片也包含在 Individual 方案裡。","如果身邊有孩子，就和他坐一會兒，打開兒童模式，一起查一個詞，看看它的圖片。毫不費力就懂了的那一刻，就是這個樣子。"],"cta":"認識兒童模式"},"summary":{"subject":"兩週，一個詞","preheader":"一路走來的旅程，以及接下來的兩條路。","paras":["過去兩週，我們一起認識了一個詞的不同面向：它所有的詞義，還有它的歷史。","同時，我們也認識了讓 Gadit 成為深入理解工具的功能：兒童模式，以及每個詞義都有一張圖片。","其中一些功能對所有使用者開放。免費帳號每天可查 10 次，生詞本最多儲存 30 個詞。","其餘的功能隨 Individual 解鎖：不限次數查詢、每個詞義都有圖片、儲存每個詞並附智慧練習的生詞本、遊戲和測驗、「每個詞」（拍下一頁，點任何一個詞）、練習發音的「說一說」，以及造一個句子並獲得回饋。如果 Gadit 已經成了你每天的習慣，這些功能就會帶來真正的不同。","家裡有孩子嗎？<a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> 方案最多可供 5 位孩子使用，並提供兒童模式和家長面板。","我們還有合作夥伴計畫：一個專屬連結，每有一位使用者透過它付費註冊，你就能獲得一筆佣金。分享你喜歡的東西，順便也有收穫，很方便。"],"cta":"認識 Individual","ps":"附註：你希望 Gadit 增加哪些功能，我們隨時都很想聽聽。直接回覆這封信就好。"}},
  zu: {"greetNamed":"Sawubona {name},","greetPlain":"Sawubona,","footerReason":"Uthola le imeyili ngoba ubhalisile ku-Gadit.","unsubscribeLabel":"Zikhiphe ohlwini","welcome":{"subject":"Siyakwamukela ku-Gadit","preheader":"Isichazamazwi esisodwa, umgomo owodwa. Ukuqonda igama ngokugcwele. Nansi indlela yokuqala.","paras":["Siyakwamukela ku-Gadit, futhi siyabonga ngokujoyina.","I-Gadit yisichazamazwi esinomgomo owodwa: ukuqonda igama ngokugcwele. Hhayi incazelo yomugqa owodwa, hhayi ukuhumusha okomile. Zonke izincazelo, izisho, umsuka wegama, nezindlela abantu abalisebenzisa ngazo namuhla.","I-akhawunti yakho yamahhala ihlanganisa ukubheka amagama ayi-10 ngosuku nencwadi yamanothi yamagama afika ku-30.","Uma uliqonda ngokuphelele igama, umqondo ongemuva kwalo uyacaca, futhi kanye nawo nendlela ocabanga ngayo, ofunda ngayo nonquma ngayo.","I-Gadit iyinkundla ephilayo eqhubeka ikhula. Uma ubona iphutha kunoma iyiphi incazelo, isibonelo noma enye ingxenye, kukhona inkinobho yokubika okufanele uyicindezele. Ithimba lethu lifunda konke futhi liyakulungisa.","Usukulungele ukuqala?"],"cta":"Bheka igama lakho lokuqala","signOff":["Ngokuzithoba,","Ithimba lakwa-Gadit"]},"meanings":{"subject":"Igama elilodwa, izingqimba obungazibonanga","preheader":"Amathuluzi amaningi ama encazelweni. I-Gadit iqhubeka kuze kube yilapho igama linamathela.","exampleWord":"umoya","paras":["Thatha igama elithi \"umoya\", ubone ukuthi igama elilodwa lingavula kanjani umhlaba wonke.","Umoya yilokho okuvunguza ezihlahleni, umoya opholile wakusihlwa. Ngumoya esiwuphefumulayo, umoya ohlanzekile. Ngumoya womuntu ngaphakathi, inhliziyo nomphefumulo wakhe. Ngumoya ophakathi kwabantu, njengomoya omuhle emndenini noma eqenjini. Futhi esontweni, nguMoya oNgcwele.","Igama elilodwa, izingqimba obungazibonanga kulo, ngayinye iphila emhlabeni wayo.","Ku-Gadit uzothola izibonelo ezintathu zangempela zencazelo ngayinye. Imisho lapho igama lisebenza khona empilweni, hhayi ethiyori kuphela. Ngaleyo ndlela ubona hhayi nje ukuthi igama lisho ukuthini, kodwa nokuthi lizwakala kanjani uma lisetshenziswa.","Lena yinhliziyo ye-Gadit. Igama elilodwa, kuze kube sekugcineni, kuzo zonke izincazelo zalo.","Siphakamisa ukuthi ubheke elithi \"umoya\", mhlawumbe nelinye igama ocabanga ukuthi usuliqonda kakade. Ungase umangale."],"cta":"Bheka igama elithi \"umoya\"","ps":"P.S. Uma uthola incazelo ekumangazayo, kukhona inkinobho yokwabelana eceleni kwayo. Kufanele uyithumele kumuntu ozoyithokozela."},"etymology":{"subject":"Igama livelaphi ngempela","preheader":"Lonke igama linomlando, futhi kwesinye isikhathi uchaza okwamanje.","exampleWord":"umoya","paras":["Sesifike engxenyeni esiyithanda kakhulu. Lapho igama livela khona.","Lonke igama linomlando. Futhi kwesinye isikhathi lowo mlando uchaza okwamanje kangcono kunanoma iyiphi incazelo.","Umoya uyisibonelo esihle. Leli gama alilona elesiZulu kuphela. NgesiXhosa nalo lithi umoya, kanti ngesiSuthu nangesiPedi lithi moya. Uma izilimi ezihlobene zinegama elifanayo ngale ndlela, lokho kukhombisa ukuthi lisuka kokhokho wazo oyedwa wasendulo, ngaphambi kokuba lezi zilimi zahlukane.","Futhi bheka ukuthi izincazelo zalo zixhumene kanjani. Zonke ziyinto ongeke uyibone ngamehlo kodwa uyizwe: umoya ebusweni bakho, umoya emaphashini akho, umoya ophilisa umuntu. Ukusuka lapho, kulula ukubona ukuthi igama lifinyelela kanjani nakulokho okungabonakali ngaphakathi komuntu, umoya wakhe, nakumoya ophakathi kwabantu.","Kwathi lapho iBhayibheli lihunyushelwa esiZulwini ngekhulu le-19, abahumushi basebenzisa leli gama ukubiza uMoya oNgcwele.","Uhambo lonke egameni elilodwa. Kusukela entweni ozizwa ithinta isikhumba sakho, umoya ovunguzayo, kuya entweni engabonakali kunazo zonke, umoya womuntu.","Uma usukwazi lokhu, awugcini nje ngokulikhumbula kangcono igama. Uyaqonda nokuthi kungani zonke izincazelo zalo zixhumene. Azihlali ndawonye ngengozi.","Ku-Gadit, ngaphansi kwezincazelo zegama ngalinye, kunesigaba esichaza umsuka walo. Umlando walo, lapho livela khona. Yilokho okuguqula isichazamazwi sisuke ohlwini lwezincazelo sibe yindaba."],"cta":"Thola umsuka wegama elilandelayo"},"visual":{"subject":"Igama elisezingeni lamehlo","preheader":"I-Kids Mode: lonke igama lichazwa ngolimi lwengane, ngaphandle kokulahlekelwa ukujula.","paras":["Esinye sezicelo esizitholile kaningi besilula. Ingane ibuza ukuthi igama elithile lisho ukuthini, kanti incazelo esemthethweni inzima kakhulu kuyo.","Yingakho i-Gadit ine-Kids Mode. Yivule, futhi lonke igama lichazwa ngolimi lwengane eneminyaka emihlanu kuya kweyishumi. Ukujula okufanayo, ngaphandle kwamagama amakhulu.","Thatha elithi \"umoya\". Kumodi evamile, lichazwa ngezingqimba eziningana. Ku-Kids Mode, liba yinto ingane eyiqonda ngokushesha, njengalokho okuzwayo ebusweni bakho uma izihlahla zinyakaza, nomoya ongenayo uphume uma uphefumula.","Futhi lokhu akukhona okwezingane kuphela. Kwesinye isikhathi, uma igama linzima ngempela, incazelo elula yiyona kanye abantu abadala abayidingayo ukuze baliqonde.","Eceleni kwe-Kids Mode, i-Gadit ikhombisa nesithombe sencazelo ngayinye, ukuze ingane ibone igama futhi ilifunde. Ukuqonda kufika ngokushesha futhi kuhlala isikhathi eside.","I-Kids Mode iyingxenye yohlelo lwe-Family, olwenzelwe imindeni enezingane. Isithombe sencazelo ngayinye siza futhi nohlelo lwe-Individual.","Uma kunengane eduze, hlala nayo umzuzwana, uvule i-Kids Mode, nibheke igama ndawonye futhi nibuke isithombe salo. Yile ndlela umzuzu wokuqonda okungenzima obukeka ngayo."],"cta":"Bona i-Kids Mode"},"summary":{"subject":"Amasonto amabili, igama elilodwa","preheader":"Uhambo, nezindlela ezimbili zokuqhubeka ukusuka lapha.","paras":["Emasontweni amabili edlule sazi izinhlangothi ezahlukene zegama. Zonke izincazelo zalo, nomlando walo.","Eceleni kwalokho, sazi izici ezenza i-Gadit ibe yithuluzi lokuqonda okujulile: i-Kids Mode, nesithombe sencazelo ngayinye.","Ezinye zalezi zici zivulekele wonke umsebenzisi. I-akhawunti yamahhala ihlanganisa ukubheka amagama ayi-10 ngosuku nencwadi yamanothi yamagama afika ku-30.","Okunye kuvuleka nge-Individual: ukubheka amagama okungenamkhawulo, isithombe sencazelo ngayinye, incwadi yamanothi egcina lonke igama nokuzejwayeza okuhlakaniphile, imidlalo namakhwizi, Wonke Amagama (thwebula ikhasi bese uthepha noma yiliphi igama), Yisho ukuze uzejwayeze ukuphimisa, nokubhala umusho uthole impendulo. Uma i-Gadit isiyingxenye yempilo yakho yansuku zonke, lezi yizici ezenza umehluko.","Unezingane ekhaya? Uhlelo lwe-<a href=\"https://www.gadit.app/families?utm_source=email&amp;utm_medium=drip&amp;utm_campaign=summary\" style=\"color:#0EA5A5;text-decoration:underline;\">Family</a> luhlanganisa izingane ezifika ku-5, ne-Kids Mode nedeshibhodi yomzali.","Futhi sinohlelo lozakwethu: isixhumanisi sakho siqu esikunika ikhomishini kukho konke ukubhalisa okukhokhelwayo okufika ngaso. Indlela elula yokwabelana ngento oyithandayo, futhi uzuze ngesikhathi esifanayo."],"cta":"Yazi i-Individual","ps":"P.S. Sihlala sithanda ukuzwa ngezici ongathanda ukuzibona ku-Gadit. Vele uphendule le imeyili."}},
};
